\section{Setup and formulations}\label{sec:setup}
%\textcolor{red}{Find a way to incorporate definition of cohesive indicator fields!!!}

A structural rectangular domain, $\Omega$, with dimensions $L \in L_x \times L_y$ is considered. $\Omega$ is partitioned into a design domain, $\Omega_A \subseteq \Omega$, and a solid passive domain, $\Omega_P \subseteq \Omega$. The domain is subjected to surface traction $\mathbf{f}$ at Neumann boundaries, $\Gamma_N \in \Omega_P$, and fixed displacements are applied to Dirichlet boundaries, $\Gamma_D \in \Omega$. $\Omega$ is discretised on four different grids, $\mathcal{T}^{c}$, $\mathcal{T}^{i}$, $\mathcal{T}^{if}$, and $\mathcal{T}^{f}$, with the element sizes, $h^{c}$, $h^{i}$, $h^{if}$, and $h^{f}$, respectively, such that $h^{c} \leq h^{i} \leq h^{if} \leq h^{f}$ (\autoref{fig:FEmodel}). The multi-scale optimisation problem is solved on $\mathcal{T}^{c}$ while the final single-scale structure is projected to $\mathcal{T}^{f}$. $\mathcal{T}^{i}$ and $\mathcal{T}^{if}$ are intermediate grids, utilised in the dehomogenisation procedure, to limit the computational cost of smoothing and interpolating the structure.


\subsection{Homogenisation-based topology optimisation}\label{sec:TO}


A multi-scale optimisation problem, formulated on both a macro and a micro scale, is considered. On the macro scale $\Omega$ is discretised using $N_e$ equal-sized quadrilateral elements $e\in \mathcal{T}^{c}$. Let $\Omega_e\subseteq\Omega$ denote the domain spanned by the element   $e\in\mathcal{T}^{c}$. On the microscale $\Omega_e$ consists of a constant periodic laminate, the so-called Rank-2 microstructure. The Rank-2 microstructure consists of two periodic orthogonally oriented lamellar materials, parameterised on two different length scales, $\bm{y}_i = \bm{x}/\epsilon^i,\; \epsilon_i\rightarrow0$, for $i\in\{1,2\}$ (\autoref{fig:rankModel}). On the smallest length scale, $\bm{y}_1$, the lamellar material has a stiff phase, $(+)$,  and a compliant phase, $(-)$, with Youngs moduli $E^{(+)}$ and $E^{(-)}$, respectively, and identical Poisson's ratio, $\nu = 1/3$. On the second length scale, $\bm{y}_2$, the lamellar material is similarly structured, but the compliant phase is described by the effective stiffness of the $\bm{y}_1$ lamellar. The stiff phases are parameterised by their relative widths $\mu_i \in [0,1]$, for $i \in \{1,2\}$.

Assuming that the compliant phase is void, $E^{(-)} = 0$, will make the constitutive model singular, and thus non-positive definite. To mitigate this, an isotropic background material, with the stiffness $E_{\min} = 10^{-9}$, is introduced to approximate void and simplify the expression. The stiffness of the solid phase is set to unit stiffness, $E^{(+)} = 1$. Following the description of a Rank-N microstructure from \citet{Jensen2022} with Cartesian aligned laminates, the constitutive matrix is defined in \autoref{eq:cmat}.
\begin{equation}\label{eq:cmat}
    \begin{split}
    \mathbf{C}^H (\mu_1,\mu_2) = \frac{E_{\min}}{1 - \nu^2} 
    \begin{bmatrix}
        1 & \nu & 0 \\ 
        \nu & 1 & 0 \\ 
        0 & 0 & \frac{1-2}{\nu} 
    \end{bmatrix}
    \\
    + \frac{E^{(+)}}{1 - \mu_2 + \mu_1\mu_2(1 - \nu^2)} \\
    \begin{bmatrix}
        \mu_1 & \mu_1 \mu_2 \nu & 0 \\ 
        \mu_1 \mu_2 \nu & \mu_2(1 - \mu_2 + \mu_1 \mu_2) & 0 \\ 
        0 & 0 & 0 
    \end{bmatrix}
\end{split}
\end{equation}
The Rank-2 material is rotated with respect to $\bm{x}$, using the standard planar rotation (\autoref{eq:rotcmat}), where the basis-transformation matrix is given in \autoref{eq:rottmat} with $c = \cos(a)$ and $s = \sin(a)$, and $a \in [-4\pi,4\pi]$ being the orientation angle. 
\begin{equation}\label{eq:rotcmat}
    \widetilde{\mathbf{C}}^H (\mu_1,\mu_2,a) = \mathbf{T}^{\intercal}(a) \, \mathbf{C}^H (\mu_1,\mu_2) \, \mathbf{T}(a)
\end{equation}
\begin{equation}\label{eq:rottmat}
    \mathbf{T}(a) = 
    \begin{bmatrix}
        c^2 & s^2 & c\,s \\
        s^2 & c^2 & -c\,s \\
        -2c\,s & 2c\,s & c^2 - s^2 
    \end{bmatrix}
\end{equation}

The relative widths, $\mu_i$, are defined on two different scales, making a single-scale interpretation challenging. Instead, the interpretation of relative widths from single-scale, $\Bar{w}_i$, to multi-scale is significantly more straightforward to obtain~\citep{JensenThesis}. 
To this end, $\mu_i$ is obtained from $\Bar{w}_i$ by \autoref{eq:w2mu}-\autoref{eq:homrho}, where $p_i$ is the stiffness contribution from each layer and $\rho_N$ the relative density of a lamellar with $N$ layers.
\begin{equation}\label{eq:w2mu}
    \mu_i = \frac{ p_i(\bar{w})  \rho_2(\bar{w}) }{1 - \rho_{n-1}(\mu)}
\end{equation}
\begin{equation}\label{eq:w2mu_p}
    p_i = \frac{\bar{w}_i}{\sum_{j=1}^{N} \bar{w}_j}
\end{equation}
\begin{equation}\label{eq:homrho}
    \rho_N(\xi) = 1 - \prod_{i=1}^{N} (1 - \xi_i),\quad \xi\in\{\mu,\; \Bar{w}\}
\end{equation}

% design parameters

$\Bar{w}_i$ is a physical relative width, which depends on two design variables; the relative width $w_i \in [w_{\min},w_{\max}]$, where $0 \leq w_{\min} \leq w_{\max} \leq 1$, and an indicator value $s_i \in [0,1]$. The indicator determines if the material is active, $s=1$, or void, $s=0$~\citep{Giele2021a}. $w$ and $s$ are filtered to obtain $\Tilde{w}$ and $\Tilde{s}$ (\autoref{eq:filter}), where $k$ is a kernel based on the neighbourhood $\Omega^k_e \in \Omega$ defined from the filter radii $r_{\min}$ and $\alpha_{\text{rsc}}\,r_{\min}$, for $\Tilde{w}$ and $\Tilde{s}$, respectively. $\alpha_{\text{rsc}} \geq 1$ is a scaling parameter for the indicator filter radius.
\begin{equation}\label{eq:filter}
    \Tilde{\xi}_e = \frac{\sum_{i \in \Omega^k_e} k_i \xi_i }{\sum_{i \in \Omega^k_e} k_i}, \quad \xi\in\{w,\; s\}
\end{equation}

$\Tilde{s}$ is projected using the three-field robust approach~\citep{Wang2011} to $\Bar{s}^m$, for $m \in \{e,i,d\}$, representing the eroded, intermediate and dilated fields, respectively (\autoref{eq:proj}). $\eta^m \in [0,1]$ are projection thresholds and $\beta \in (0, \infty ]$ is the projection sharpness. To ensure minimum length-scale on the physical relative widths, the indicator and widths are convoluted (\autoref{eq:ip2}).
\begin{equation}\label{eq:proj}
    \Bar{s}_e^m = \frac{\tanh (\beta \eta) \, \tanh( \beta ( \Tilde{s}_e - \eta ) )}{ \tanh (\beta \eta^m) \, \tanh( \beta ( 1 - \eta^m ) ) }
\end{equation}

\begin{equation}\label{eq:ip2}
    \Bar{w}_i^m = \Tilde{w}_i \, \Bar{s}^m
\end{equation}

% optimization problem:
Let $\mathbf{w}_i \in \mathbb{R}^{N_e}$, $\mathbf{s}\in \mathbb{R}^{N_e}$ and $\mathbf{a}\in \mathbb{R}^{N_e}$ be vectors representing the design on $\Omega$, with restrictions $\mathbf{w}_i=1$ and $\mathbf{s}=1$ in $\Omega_P$, for solid passive material. Further, let $\bm{\kappa}$ denote the combined set of design variables, such that $\bm{\kappa} = \{ \mathbf{w}_1,\mathbf{w}_2,\mathbf{s},\mathbf{a} \}$. The optimisation problem of the multi-scale minimum compliance problem is stated in (\autoref{eq:TopOptObj})-(\autoref{eq:TopOptBox}).
\begin{eqnarray}\label{eq:theTopOptProb}
    %& \displaystyle \min_{\bm{\kappa} = \{ \mathbf{w}_1,\mathbf{w}_2,\mathbf{s},\mathbf{a} \}}  & : \Phi (\bm{\kappa},\mathbf{u}) = \mathcal{J}\gamma_{0} + \mathcal{P} \gamma_{S} \label{eq:TopOptObj}   \\
     & \displaystyle \min_{\bm{\kappa}}  & : \Phi (\bm{\kappa},\mathbf{u}) = \gamma_{0} J+ \gamma_{S} \frac{1}{V_{\Omega}} \int_{\Omega} \bar{\mathbf{s}}^d \mathrm{d}\Omega\label{eq:TopOptObj}   \\
    & \textrm{s.t.}                     & : \mathbf{K}( \bm{\mu}^e_1,\bm{\mu}^e_2,\mathbf{a} ) \mathbf{u} = \mathbf{f},    \label{eq:TopOptSys} \\
     &  						            & : f^o \leq f^*, \label{eq:TopOptCon} \\
    &                                   & : \underline{\bm{\kappa}} \leq  \bm{\kappa}   \leq  \overline{\bm{\kappa}} \label{eq:TopOptBox} 
\end{eqnarray}
The optimisation objective (\autoref{eq:TopOptObj}) is to minimise a weighted sum of the structural compliance (\autoref{eq:comp}), 
and a non-uniqueness penalty term~\citep{Giele2021a,Jensen2022}, with weight factors $\gamma_0$ and $\gamma_S$ respectively. $\gamma_{0}$ is the volume-weighted solid compliance of $\Omega$, and $\gamma_{S} = 1/20$ scales the penalty term.
\begin{equation} \label{eq:comp}
    J = \langle \mathbf{f},\mathbf{u} \rangle
\end{equation}

The objective is subjected to an upper bound constraint (\autoref{eq:TopOptCon}) on the overall volume (\autoref{eq:volfrac}), with $V_{\Omega}$ denoting the volume of $\Omega$.
\begin{equation} \label{eq:volfrac}
    f^o = \frac{1}{V_{\Omega}} \int_{\Omega} \rho_2(\{\bar{\mathbf{w}}^d_1,\bar{\mathbf{w}}^d_2\}) \mathrm{d}\Omega 
\end{equation} 

The displacements, $\mathbf{u}$, are obtained from the linear elastic problem~(\autoref{eq:TopOptSys}) considering the eroded multi-scale interpretation of $\mathbf{w}_i$ (\autoref{eq:w2mu}). 


The design variables are subjected to box constraints based on their defined ranges (\autoref{eq:TopOptBox}). 
The optimisation problem is solved in a nested form, where in each iteration of the procedure, the design is updated using the OC-resembling update rule from~\cite{Ferrari2021}. Sensitivities with respect to the objective and volume fraction constraint are computed using the discrete adjoint method.







