%\begin{multicols}{2}

The relation of the kernel phase shift and the location of the emitted wave signal at the kernel centre, may cause the signal from neighbouring kernels to be out-of-phase, causing destructive inference in the sampled phasor field (\cite{Tricard_orientable_2020}). To this end, phase alignment is performed to obtain a set $\varphi_e,\:\zeta(e)\in \mathcal{K}_i$ of phase shifts ensuring spatial coherency between the separate kernel wavefronts. The phase alignment procedure is a fixed-iteration heuristic, where the phase shift of each kernel $\zeta(e)\in \mathcal{K}_i$ is updated sequentially in each iteration, based on a weighted contribution from the nearby kernels. Similarly to \cite{Woldseth2023}, an anisotropic neighbourhood definition is utilised to define the subset $\mathcal{N}_e\subseteq\mathcal{K}_i$ of nearby kernels for kernel $\zeta(e)\in \mathcal{K}_i$ (\autoref{eq:align_neighbourhood}).
\begin{equation}\label{eq:align_neighbourhood}
    \mathcal{N}_e=\left\{\zeta(f)\in \mathcal{K}_i:\; \Delta_e^\mathbf{r}(\mathbf{\mathring{x}}_f)\leq R^2_e\right\}
\end{equation}
Based on the definitions of the neighbouring kernels in the current iterate, the phase shift $\varphi_{e}$ of kernel $\zeta(e)\in \mathcal{K}_i$ is the real-valued argument of the combined signal from its neighbours (\autoref{eq:phase_alignment_update}-\autoref{eq:phase_alignment_update2}). To account for the inherent $\pi$-rotational invariance of the microstructure representation in this update, the corrected phase shift $\tilde{\varphi}_{fe}$ and orientation $\tilde{\mathbf{n}}_{fe}$ contributions from kernel $\zeta(f)\in \mathcal{N}_e$, relative to the kernel $\zeta(e)\in \mathcal{K}_i$ being updated, are determined according to \autoref{eq:opposing_orient_correct}-\autoref{eq:opposing_orient_correct2}.

%\end{multicols}

\begin{align}\label{eq:phase_alignment_update}
%\begin{split}
        \varphi_e=\text{Arg}\left(\sum_{\zeta(f)\in \mathcal{N}_e} \mathrm{exp}\left({-\dfrac{1}{R_e}\|\mathbf{\mathring{x}}_e-\mathbf{\mathring{x}}_f\|_2^2}\right)\tilde{\mathcal{G}}_e^f\right)\\\label{eq:phase_alignment_update2}
       \tilde{\mathcal{G}}_e^f= \mathrm{exp}\left({\displaystyle2i\pi \omega \mathbf{\tilde{n}}_{fe}\cdot(\mathbf{\mathring{x}}_e-\mathbf{\mathring{x}}_f)+i\tilde{\varphi}_{fe}}\right)
%\end{split}
\end{align}

\begin{align}
   &\tilde{\varphi}_{fe}=\begin{cases}
        \pi-\varphi_f & \textit{if } \mathbf{n}_{ie}\cdot \mathbf{n}_{if}<0 \\
        \varphi_i     & \textit{otherwise}
    \end{cases}\label{eq:opposing_orient_correct}\\
    &\mathbf{\tilde{n}}_{fe}=\begin{cases}
        -\mathbf{n}_{if} & \textit{if } \mathbf{n}_{ie}\cdot \mathbf{n}_{if}<0 \\
        \mathbf{n}_{if}  & \textit{otherwise}\label{eq:opposing_orient_correct2}
    \end{cases}
\end{align}
