%\begin{multicols}{2}


To best adhere to the orientations $\mathbf{n}_e,\; e\in \mathcal{T}^c$ and an imposed constant periodicity $\omega$, for a non-trivial orientation field, the sampled phasor field $\mathcal{G}(\mathbf{x}),\; \mathbf{x}\in \mathcal{T}^{if}$ must contain point-singularities, which imposes branch-like bifurcations in the wave-field translations. Therefore, thresholding the triangular wave-field $\tau(\mathbf{x})$ may result in a solid-void design with disconnected structural members at these bifurcation locations (\autoref{fig:branch_closure}(a)), which are subjected to a post-processing procedure to improve structural integrity. 

The convenient relation between singularities in the complex phasor field and the branching disconnections in the corresponding real-valued conversions, allows for identifying a discrete set of points $\mathcal{B}\subset\mathcal{T}^{if}$ by identifying where the magnitude of the phasor field vanishes to \mbox{zero (\autoref{eq:branching_point_set})}.
\begin{equation}\label{eq:branching_point_set}
    \mathcal{B}=\{\mathbf{x}\in\mathcal{T}^{if}\;:\;|{\mathcal{G}}(\mathbf{x})|<\epsilon,\;\epsilon\rightarrow 0\}
\end{equation}

 Depending on the global phase of the phasor sine-wave $\psi(\mathbf{x})$, relative to a bifurcation location, the degree of disconnection of the branches may vary. Branches with a minimal degree of disconnection will require less invasive efforts to ensure connectivity, compared to those with maximal degree of disconnection. $\varrho(\boldsymbol{\gamma})\in [0,1]$ is introduced as a measure describing the degree of disconnection of a branching point $\boldsymbol{\gamma}\in\mathcal{B}$, and is computed based on the average normalised phasor sine-wave value within a circular neighbourhood $\mathcal{M}$ (\autoref{eq:disconnection_degree2}) with diameter equal to one wave-length $\lambda$ at the current periodicity $\omega$ (\autoref{eq:disconnection_degree}). 

%\end{multicols}

\begin{align}\label{eq:disconnection_degree}
    \varrho(\boldsymbol{\gamma})=1-\dfrac{1}{|\mathcal{M}(0.5\lambda)|}\displaystyle\sum_{\mathbf{x}\in \mathcal{M}(0.5\lambda)}\frac{\psi(\mathbf{x})+1}{2}\\\label{eq:disconnection_degree2}
    \mathcal{M}_{\boldsymbol{\gamma}}(s)=\{\mathbf{x}\in\mathcal{T}^i\;:\;\|\boldsymbol{\gamma}-\mathbf{x}\|_2^2\leq s^2\},\; \forall \boldsymbol{\gamma}\in \mathcal{B}
\end{align}

%\begin{multicols}{2}

To determine the unit vector $\boldsymbol{\vec{\gamma}}$ indicating the closure direction for the branch about the branching point $\boldsymbol{\gamma}\in \mathcal{B}$, the degrees of disconnection at the locations corresponding to moving $\pm\frac{1}{3}$-wavelenghts along the layer-normal $\mathbf{n}(\boldsymbol{\gamma})$ at the branching point $\boldsymbol{\gamma}$ are compared to determine the best fit (\autoref{eq:closure_direction}). Keeping the control-points within $\pm\frac{1}{3}\lambda$ of the identified bifurcation point limits potential interference of neighbouring waves on the closure direction selection.

\begin{equation}\label{eq:closure_direction}
    \vec{\boldsymbol{\gamma}} = %
    \begin{cases}
        \mathbf{n}(\boldsymbol{\gamma}) & \text{if } \varrho\left(\boldsymbol{\gamma}{+}\frac{\lambda}{3}\mathbf{n}(\boldsymbol{\gamma})\right)\leq\varrho\left(\boldsymbol{\gamma}{-}\frac{\lambda}{3}\mathbf{n}(\boldsymbol{\gamma})\right)\\
        - \mathbf{n}(\boldsymbol{\gamma}) & \text{otherwise}
    \end{cases}
\end{equation}

From the obtained closure direction and degree of disconnection of $\boldsymbol{\gamma}\in \mathcal{B}$ a perturbed branch centre $\boldsymbol{\dot{\gamma}}$ and a closure control-point $\boldsymbol{\ddot{\gamma}}$ are identified (\autoref{eq:new_centre}).  
\begin{equation}\label{eq:new_centre}
\boldsymbol{\dot{\gamma}}=\boldsymbol{\gamma}+\frac{\lambda}{3}\varrho(\boldsymbol{\gamma})\vec{\boldsymbol{\gamma}}\quad \land \quad \boldsymbol{\ddot{\gamma}}=\boldsymbol{\gamma}+\frac{2\lambda}{3}\varrho(\boldsymbol{\gamma})\vec{\boldsymbol{\gamma}}
\end{equation}

The point $\boldsymbol{\dot{\gamma}}$ is chosen as the centre location for ensuring connection by branch solidification. This is obtained by introducing a modified Gaussian $\hat{\Pi}_{\boldsymbol{\gamma}}(\mathbf{x})$ about this centre, and from the union $\hat{\Pi}(\mathbf{x})$ a density weighted localised phaseshift $\hat{\pi}(\boldsymbol{x})$ is introduced. A normalised triangular wave $\hat{\tau}(\mathbf{x})$ with solidified branch-shaped connections (\autoref{fig:branch_closure}(b)) can then be obtained by the union of the $\pm\hat{\pi}(\boldsymbol{x})$ phase-shifted sine waves $\hat{\psi}(\mathbf{x})$ (\autoref{eq:solidified_triangular}-\autoref{eq:branch_local_gaussian}). 
\begin{align}
    &\hat{\tau}(\mathbf{x})=\frac{1}{\pi}\arcsin(\hat{\psi}(\mathbf{x}))+0.5\label{eq:solidified_triangular}\\
    &\hat{\psi}(\mathbf{x})=\max\{\sin(\phi(\mathbf{x})+\hat{\pi}(\mathbf{x})),\;\sin(\phi(\mathbf{x})-\hat{\pi}(\mathbf{x}))\}\label{eq:solidified_triangular}\\
    &\hat{\pi}(\mathbf{x})=\hat{\Pi}(\mathbf{x})\pi\left(1-\tau(\mathbf{x})\right)\label{eq:phase_shift_mag}\\
    &\hat{\Pi}(\mathbf{x})=\displaystyle\max_{\boldsymbol{\gamma}\in\mathcal{B}}\hat{\Pi}_{\boldsymbol{\gamma}}(\mathbf{x})\label{eq:region_based_shift}\\
    &\hat{\Pi}_{\boldsymbol{\gamma}}(\mathbf{x})={\text{smoothstep}\left(\Pi_{\boldsymbol{\gamma}}(\mathbf{x})\right)}=3\Pi_{\boldsymbol{\gamma}}(\mathbf{x})^2-2\Pi_{\boldsymbol{\gamma}}(\mathbf{x})^3\label{eq:smoothstep_local_gaussian}\\
   &\Pi_{\boldsymbol{\gamma}}(\mathbf{x})=\mathrm{e}^{-4{\omega^2}\Delta^\mathbf{s}_{\boldsymbol{\dot{\gamma}}}(\mathbf{x})
        {\left(1-0.5\psi(\mathbf{x})\right)}},\; \mathbf{s}=\left(\dfrac{1}{2\pi},\;1\right)^\intercal\label{eq:branch_local_gaussian}
\end{align}

This branch solidification ensures connection of $\hat{\tau}(\mathbf{x})$, but also introduces excessive material in the branching region. To reduce the amount of material in the branches while maintaining appropriate branch-shapes, the localised pinch-procedure is applied (\cite{Woldseth2023}). This is an iterative procedure, where for each iterate $k\in\{1,...,k_{max}\}$ the material of a branch is reduced and its shape corrected by utilising the control points $\boldsymbol{\gamma}_k$ and $\tilde{\boldsymbol{\gamma}}_k$ to move the branch centre from $\boldsymbol{\dot{\gamma}}$ towards $\boldsymbol{\ddot{\gamma}}$, with step-magnitude determined by the degree of disconnection (\autoref{eq:pinch_control_points}).
\begin{equation}\label{eq:pinch_control_points}
\begin{split}
\boldsymbol{\gamma}_k&=(1-d_k(\boldsymbol{\gamma}))\boldsymbol{\dot{\gamma}}+d_k(\boldsymbol{\gamma})\boldsymbol{\ddot{\gamma}}\quad \land \\
\boldsymbol{\tilde{\gamma}}_k&= (1-d_k^2(\boldsymbol{\gamma}))\boldsymbol{\dot{\gamma}}+d_k^2(\boldsymbol{\gamma})\boldsymbol{\ddot{\gamma}},\\ 
d_k(\boldsymbol{\gamma})&=\dfrac{1-\varrho(\boldsymbol{\gamma})}{2}(k-1)
\end{split}
\end{equation}

The pinch operator is directed by the gradients of the union $\tilde{\Pi}_k(\mathbf{x})$ of anisotropic Gaussians constructed for each $\boldsymbol{\gamma}\in \mathcal{B}$, centred at the correponding current iterate location $\boldsymbol{\gamma}_k$ (\autoref{eq:pinch_deriv_field}).
\begin{equation}\label{eq:pinch_deriv_field}
\tilde{\Pi}_k(\mathbf{x})=\max_{\gamma\in\mathcal{B}}\mathrm{e}^{-{\omega^2}\Delta^{\mathbf{\tilde{s}}}_{\boldsymbol{{\gamma}_k}}(\mathbf{x})},\; \mathbf{\tilde{s}}=\left(\frac{1}{2\pi},1\right)^\intercal
\end{equation}

To localise the pinch impact and improve the resulting shape, a union $\bar{\Pi}_{k}(\mathbf{x})$ of modified Gaussians, controlled by the interpolated orientation $\mathbf{n}(\mathbf{x})$ and relative thickness $w(\mathbf{x})$ at the sampling point $\mathbf{x}\in\mathcal{T}^{if}$, centred at the control points $\boldsymbol{\tilde{\gamma}}_k$ is introduced (\autoref{eq:pinch_localisation}). 

\begin{equation}
\begin{split}
    \bar{\Pi}_{k}(\mathbf{x})&=\max_{\gamma\in\mathcal{B}}\mathrm{e}^{-{2\omega^2}\Delta_{\boldsymbol{\tilde{\gamma}_k}}^\mathbf{\tilde{s}_k}(\mathbf{x})-\tilde{\delta}_{\boldsymbol{\tilde{\gamma}}_k}},\\ 
    \mathbf{\tilde{s}}_k&=\left(\frac{3}{4\pi}\left(1-\frac{k-1}{2}\right),1\right)^\intercal, \\ 
    \tilde{\delta}_{\boldsymbol{\tilde{\gamma}}_k}&=\dfrac{2\omega}{(2-w({\mathbf{x}}))}|\mathbf{n}(\mathbf{x})\cdot(\mathbf{x}-\boldsymbol{\gamma}_k)|\label{eq:pinch_localisation}
\end{split}
\end{equation}

Based on the introduced pinch control measures for an iterate $k\in\{1,...,k_{max}\}$, the corresponding transformation of the triangular wave-field from $\tilde{\tau}_{k-1}(\mathbf{x})$ to $\tilde{\tau}_{k}(\mathbf{x})$ at iteration $k$ is governed by the combined pinch perturbation $\mathcal{P}_k(\mathbf{x})$ and a perturbation magnitude scaling factor $\delta(\mathbf{x})$ (\autoref{eq:stepmag_dit}-\autoref{eq:update_rho}). 
\begin{align}
   & \mathcal{P}_k(\mathbf{x})=\delta(\mathbf{x})\bar{\Pi}_k(\mathbf{x})\nabla\tilde{\Pi}_k(\mathbf{x}),\quad\delta(\mathbf{x})=\dfrac{\lambda}{3}(1-w(\mathbf{x}))\label{eq:stepmag_dit}\\
    &\tilde{\tau}_k(\mathbf{x})=\tilde{\tau}_{k-1}\left(\mathbf{x}-{\mathcal{P}}_k(\mathbf{x})\right),\quad \tilde{\tau}_0(\mathbf{x})=\hat{\tau}(\mathbf{x})\label{eq:update_rho}
\end{align}
After completing $k_{max}$ iterations, the shape and material usage of the branch connections are effectively improved. Given the connected triangular wave-field $\tilde{\tau}_i$ for lamination layer $i\in \{1,2\}$, the corresponding thickness-adhering solid-void projection $\rho^s_i$ is obtained by \autoref{eq:layer_dens} (\autoref{fig:branch_closure}(c)).
\begin{equation}\label{eq:layer_dens}
    \rho^s_i=\mathcal{H}\left(\mathbf{w}_i-\tilde{\tau}_i\right),\;i\in\{1,2\}
\end{equation}
The combined dehomogenised structure, represented by the density-field $\rho^s$, is then obtained by the union of the lamination layers within the specified structural domain $\mathcal{I}\subseteq\Omega$ (\autoref{eq:layer_union}), and the corresponding dehomogenised volume fraction is computed according to \autoref{eq:volfrac_dehom}.
\begin{equation}\label{eq:layer_union}
    \rho^s=\left(\displaystyle\bigcup_{i\in\{1,2\}}\rho^s_i\right)\bigcap \mathcal{I}
\end{equation}

\begin{equation} \label{eq:volfrac_dehom}
    f^s = \frac{1}{V_{\Omega}} \int_{\Omega} \rho^s \mathrm{d}\Omega 
\end{equation} 
%and the dehomogenised design for lamination layer $i\in \{1,2\}$ is obtained . 

%The union of the two dehomogenised lamination layers, obtained by the described phasor approach, forms the infill of the structure. To improve the transition between porous structure and void, a varying thickness structural boundary in constrcuted. 

%\end{multicols}



