    \includegraphics[width=\linewidth]{figs_seamline_seamline_eng}
    \captionof{figure}{Highlight of the analysed dehomogenised structure without angle invariance corrections of the optimisation starting guess.}
    \label{fig:seamline_eng}
\end{Figure}





