\title{On near optimal colorable graphs}

\author{C.~U.~Angeliya\thanks{Computer Science Unit, Indian Statistical
Institute, Chennai Centre, Chennai 600029, India. This research is   supported by National Board of Higher Mathematics (NBHM), DAE, India.  } \and Arnab Char\thanks{Computer Science Unit, Indian Statistical
