\section{The class of ($2P_1+P_3, K_4-e$)-free graphs}\label{sec:2P1+P3}

In this section, we give a proof of \cref{col-thm-2}, and it follows from a structure theorem for such a class of graphs (see \cref{main-thm-2}).
First  we prove some general structural properties  of a ($2P_1+P_3$,\,$K_4-e$)-free graph  that  contains a $C_5$, and use them in the latter sections.
 \subsection{Properties of  ($2P_1+P_3, K_4-e$)-free graphs  that  contain a  $C_5$}\label{genprop-3}


Let $G$ be a ($2P_1+P_3, K_4-e$)-free graph.
Suppose that $G$ contains a  $C_5$, say with
 vertex-set $C:= \{v_1, v_2, v_3, v_4, v_5\}$ and edge-set $\{v_1 v_2, v_2 v_3, v_3 v_4, v_4 v_5, $ $v_5 v_1\}$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use  the properties given in \cref{genprop}.
 In addition, for each $i\in [5]$, the following hold:
\begin{enumerate}[label=  $(\mathbb{M}\arabic*)$, leftmargin=2.25cm] \itemsep=0pt
\item \label{cliq}    {\it  $A_i\cup T$ is a clique.}
\item \label{ato-2}   {\it  $[A_i, (A\sm A_i)\cup B_{i+2} \cup (D\sm D_{i}) \cup Z_i]$ is complete.}
 \item \label{bd}  {\it One of $X_i$ and $D_{i-1} \cup D_{i+2}$ is  empty.}
  \end{enumerate}



\begin{proof}
\ref{cliq}:~If there are nonadjacent vertices in $A_i \cup T$, say $u$ and $v$, then $\{u, v, v_{i+1}, v_{i+2}, v_{i-2}\}$ induces a $2P_1+P_3$. So \ref{cliq} holds. $\sq$

\smallskip
\noindent{\ref{ato-2}}:~Suppose not. Then up to symmetry, we may assume that there are nonadjacent vertices, say $u\in A_i$ and   $v \in A_{i+1}\cup A_{i+2}\cup B_{i+2} \cup Z_i \cup D_{i+1}\cup D_{i+2}$. But then $\{ u, v_{i-1}, v, v_{i+1}, v_{i+2}\}$ induces a $2P_1+P_3$.  So \ref{ato-2} holds. $\sq$





\smallskip
\noindent{\ref{bd}}:~Suppose to the contrary that there are vertices, say $u \in X_i$ and $v \in D_{i-1} \cup D_{i+2}$. Then from \ref{bto}, we have $uv\notin E(G)$.   But then $\{v, v_{i-1}, u, v_{i+1}, v_{i+2}\}$ or   $\{v, v_{i+2}, u, v_{i}, v_{i-1}\}$ induces a $2P_1+P_3$  which is a contradiction. So \ref{bd} holds.
  \end{proof}















\subsection{Structure of ($2P_1+P_3, K_4-e$)-free graphs} \label{Sec:Struc-thm2}
Our main result in this section is the following.
 \begin{theorem}\label{main-thm-2}
Let $G$ be a  ($2P_1+P_3, K_4-e$)-free graph which is not perfect. Then either    $G$ has a vertex with degree  at most 5 or $G$ is a good graph with $\omega(G)\geq 4$ or    $G$ is $6$-colorable.
\end{theorem}

The proof of \cref{main-thm-2} follows from the lemmas given below, and it is given at the end of this section.


\begin{lemma}\label{l1}
    Let $G$ be ($2P_1+P_3, K_4-e$)-free graph. If $G$ contains a $C_5+K_1$, then $G$ has a vertex with degree at most 5.
\end{lemma}
\begin{proof}
Let $G$ be a ($2P_1+P_3, K_4-e$)-free graph. Suppose that $G$ contains a $C_5 + K_1$, say a $C_5$ with
vertex-set $C := \{v_1, v_2, v_3, v_4, v_5\}$ and edge-set \{$v_1 v_2$, $v_2 v_3$, $v_3 v_4$, $v_4 v_5$, $v_5 v_1$\} plus a vertex $t$ such that $[\{t\}, C] = \emptyset$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$ and $T$ as in  \cref{genprop}, and we use the properties given in \cref{genprop} and \cref{genprop-3}. Clearly  $t \in T$. In addition, we claim that the following hold:

\begin{claim}\label{tto-1}
    $[T, A \cup B \cup D \cup Z]$ is complete.
\end{claim}
\no{\it Proof of \cref{tto-1}}.~Suppose to the contrary that there are nonadjacent vertices, say $u\in T$ and $v\in A\cup B\cup D \cup Z$. Then from \ref{cliq}, we may assume that $v\in X_i\cup D_{i+2}$, for some $i\in [5]$. But then $\{u,v_{i-1},v,v_{i+1},v_{i+2}\}$ induces a $2P_1+P_3$ which is a contradiction. So \cref{tto-1} holds. $\sq$


\begin{claim}\label{t-card}
For each $i\in [5]$, we have $|A_i\cup Z_i|\leq 1$ ,  $|X_i\cup D_{i+2}|\leq 1$ and $|X_i\cup D_{i-1}|\leq 1$.
\end{claim}
\no{\it Proof of \cref{t-card}}.~If there are vertices, say $u,v\in  A_i\cup Z_i$, then from \ref{cliq}, \ref{ato-2} and from \cref{tto-1}, we see that $\{t,u,v,v_i\}$ induces a $K_4-e$; so $|A_i\cup Z_i|\leq 1$. Next if there are vertices, say $u,v\in  X_i\cup D_{i+2}$, then from    \cref{tto-1}, we see that $\{t,u,v,v_{i+1}\}$ induces a $K_4-e$ or $\{v_{i-1}, v_{i+2},t,u,v\}$ induces a $2P_1+P_3$; so  $|X_i\cup D_{i+2}|\leq 1$. Likewise, $|X_i\cup D_{i-1}|\leq 1$. This proves \cref{t-card}. $\sq$

\medskip
So from above claims,  we observe that $d(v_1) = |N(v_1)| = |\{v_{2},v_{5}\} \cup (X_5\cup D_2)\cup (X_1\cup D_5)\cup (A_1\cup Z_1)| \leq 2 + 1 + 1 +1 = 5$. This proves Lemma \ref{l1}.
\end{proof}

\begin{lemma}\label{lem-2k1p3-c5}
    Let $G$ be ($2P_1+P_3, K_4-e$)-free graph. If $G$ contains a $C_5$, then $G$ has a vertex with degree at most 5 or $G$ is a good graph with $\omega(G)\geq 4$ or $G$ is $6$-colorable.
\end{lemma}
\begin{proof}
Let $G$ be a ($2P_1+P_3, K_4-e$)-free graph. Suppose that $G$ contains a $C_5$, say with
vertex-set $C := \{v_1, v_2, v_3, v_4, v_5\}$ and edge-set \{$v_1 v_2$, $v_2 v_3$, $v_3 v_4$, $v_4 v_5$, $v_5 v_1$\}. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$ and $T$ as in  \cref{genprop} and we  use the properties given in \cref{genprop} and \cref{genprop-3}.  By \cref{l1}, we may assume that $G$ is $(C_5+K_1)$-free; so $T=\es$.  In addition:

\begin{claim}\label{2.1}
        We may assume that $A$ is an empty set.
    \end{claim}
    \noindent{\it Proof of \cref{2.1}}.~Suppose that $A\neq \es$, say $A_1 \neq \emptyset$. Let $a\in A_1$. Then the following hold:

    \vspace{-0.15cm}
     \begin{enumerate}[label=$(\roman*)$, leftmargin=0.85cm]\itemsep=0pt
   \item\label{A-2k1p3-X15} For any vertex, say $u\in X_1\cup X_5$, since $\{a,v_5,u,v_2,v_3\}$ or $\{a,v_2,u,v_5,v_4\}$ does not induce a $2P_1+P_3$ (by \ref{bto}), we conclude that  $X_1\cup X_5=\es$.
              \item\label{A-2k1p3-D25-card}   If there are nonadjacent vertices, say $d\in D_2$ and $d'\in D_5$, then  $\{d,v_2, d',v_4,v_5\}$   induces a $2P_1+P_3$; so $[D_2, D_5]$ is complete. Also, if there are vertices, say $d,d'\in D_2$, then from \ref{ato-2}, $\{v_2,v_4,d,a,d'\}$ induces a $2P_1+P_3$; so $|D_2|\leq 1$. Likewise, $|D_5|\leq 1$.
          \item\label{A-2k1p3-D25-A1} If  $|A_1|=1$, then from \ref{A-2k1p3-X15}, \ref{A-2k1p3-D25-card}, \ref{DZ} and \ref{bd}, we note that  $d(v_1) = |N(v_1)| = |\{v_2,v_5\} \cup A_1 \cup (D_2 \cup D_5) \cup Z_1| \leq 2 + 1 + 1+1 = 5$   and we are done; so we may assume that $|A_1|\geq 2$, and  we let $a_1,a_1'\in A_1$.  Note that $a_1a_1'\in E(G)$, by \ref{cliq}. Then for any $u\in (A\sm A_1)\cup B_3\cup D_3\cup D_4$, since $\{u,a_1,a_1',v_1\}$ does not induce a $K_4-e$ (by  \ref{ato-2}), we see that $(A\sm A_1)\cup B_3\cup D_3\cup D_4=\es$. Also for any $w\in D_1$, since $\{w,v_2,v_3,v_4,v_5,a_1,a_1'\}$ does not induce a $C_5+K_1$, we have $wa_1,wa_1'\in E(G)$, and then $\{w,a_1,a_1',v_1\}$ induces a $K_4-e$; so $D_1=\es$.
                  \item \label{A-2k1p3-ome} If $|X_2| \leq 1$, then from  \ref{DZ}, we have $d(v_2) = |N(v_2)| =|\{v_1, v_3\} \cup X_2 \cup Z_2| \leq 2+1+1=4$ and we are done; so we may assume that $|X_2|\geq 2$. Hence $\omega(G)\geq 4$, by \ref{X-matching}.
                           \end{enumerate}

         Thus from above conclusions, we observe that $V(G) = C \cup A_1 \cup D_2 \cup D_5 \cup X_2 \cup X_4 \cup Z_1$. Now we let $Q_1 := \{v_1\} \cup A_1 \cup D_2\cup D_5\cup Z_1$, $Q_2 := \{v_2, v_3\} \cup X_2$, and $Q_3 := \{v_4, v_5\} \cup X_4$. Then from  \ref{A-2k1p3-D25-card}, \ref{A-2k1p3-ome}, \ref{DZ}--\ref{bto} and from \ref{cliq}--\ref{bd}, we deduce that $Q_1$, $Q_2$ and $Q_3$  are three cliques such that $Q_i$'s are pairwise graded  with $\omega(G) \geq 4$.   Hence $G$ is a good graph with $\omega(G)\geq 4$, and we  are done. So we may assume that $A=\es$. $\sq$




     \begin{claim}\label{2.2}
        We may assume that $B$ is an empty set.
    \end{claim}
\noindent{\it Proof of \cref{2.2}}.~Suppose that $B\neq \es$.  If $B_i\neq \es$, then we let $b_i$ denote a vertex in $B_i$. First if there is an $i\in [5]$ such that $B_{i-1},B_i$ and $ B_{i+1}$ are nonempty, say $i=1$, then since $\{b_1, b_2, b_5, v_5, v_4\}$ does not induce a   $2P_1+P_3$ (by \ref{bto}), we have $b_2 b_5 \in E(G)$, but then $\{b_2, b_5, v_5, v_4, v_3, b_1\}$ induces a $C_5 + K_1$ which is a contradiction; so  there does not exist an   $i\in [5]$ such that  $B_{i-1},B_i$ and $ B_{i+1}$ are nonempty.

    Next suppose that there is an index $i\in [5]$ such that  $B_i$ and $ B_{i+1}$ are nonempty, say $i=1$. Then $B_3\cup B_5=\es$, and $D_1\cup D_3\cup D_4\cup D_5 =\es$ (by \ref{bd}). Also for any $d\in D_2$, since $\{d, v_4, b_1, v_2, b_2\}$ does not induce a  $2P_1+P_3$ (by \ref{bto}), we have $D_2=\es$. Moreover for any $z\in Z_1\cup Z_3$, since
    $\{b_1,b_2, z,v_4,v_5\}$  does not induce a  $2P_1+P_3$ (by \ref{bto}), we have $Z_1\cup Z_3=\es$.
    Hence from \cref{2.1}, $V(G) = C \cup X_1 \cup X_2 \cup X_4$.     Recall that $[X_1, X_2] = \emptyset$ (by \ref{bto}), and $\{X_1, X_4\}$ and $\{X_2, X_4\}$ are graded (by \ref{X-matching}). Now if $|X_j|\leq 1$ for each $j\in \{1,2,4\}$, then $d(v_2)= |N(v_2)| = |\{v_1,v_3\} \cup X_1 \cup X_2 \cup X_4| \leq 5$, and we are done. So there is a $j\in \{1,2,4\}$ such that $|X_j|\geq 2$.   Then since $\{v_j,v_{j+1}\}$ is complete to  $X_j$, we have $\omega(G)\geq 4$ (by \ref{X-matching}). Again by using \ref{X-matching}, it is easy to see that $V(G)$ can be partitioned in three cliques, namely $\{v_1, v_2\} \cup X_1$, $\{v_2, v_3\} \cup X_2$ and $\{v_4, v_5\} \cup X_4$  which are pairwise graded. Hence $G$ is a good graph with $\omega(G)\geq 4$, and we are done.


 Finally since  $B\neq \es$, we may assume the $B_1 \neq \emptyset$.
      If $B\sm B_1=\es$, then from \ref{DZ}, \ref{bd} and \cref{2.1}, we have $d(v_4) = |N(v_4)| = |\{v_3,v_5\} \cup Z_1 \cup Z_2 \cup Z_4| \leq 5$, and we are done.  So we may assume that $B_3 \neq \emptyset$.  Then  $D_2 \cup D_3 \cup D_5 = \emptyset$ (by \ref{bd}), and from  the previous arguments, we have $B_2 \cup B_4 \cup B_5 = \emptyset$.
   Also if  $|D_1| \geq 2$, then for any $d, d'\in D_1$, since $\{b_1, v_3, d, v_5, d'\}$ does not induce a $2P_1+P_3$ (by  \ref{DZ} and \ref{bto}), we have $|D_1|\leq 1$.   Likewise, $|D_4| \leq 1$. Hence $|D_1\cup Z_2\cup Z_5|\leq 2$ and $|D_4\cup Z_3|\leq 1$ (by  \ref{DZ} and \ref{bd}). Then $d(v_5) = |N(v_5)| = |\{v_1,v_4\} \cup D_1 \cup D_4 \cup Z_2 \cup Z_3 \cup Z_5|  \leq 5$, and we are done.  This proves \ref{2.2}. $\sq$


  \medskip
    Now  from \cref{2.1} and \cref{2.2}, we conclude that $V(G) = C \cup  D \cup Z$. Now we let $S_j:= \{v_j\}\cup D_j$, for $j\in [5]$, and let $S_6:= Z$.    Then from  \ref{DZ} and \ref{bto}, we conclude that $S_1, S_2, \ldots, S_6$ are stable sets, and hence $G$ is $6$-colorable. This proves \cref{lem-2k1p3-c5}.
\end{proof}

\begin{lemma}\label{lem-2k1p3-c7}
If $G$ is a ($2P_1+P_3, K_4-e, C_5$)-free graph that contains a $C_7$, then $G$ is isomorphic to $C_7$.
\end{lemma}
\begin{proof}
Let $G$ be a ($2P_1+P_3, K_4-e, C_5$)-free graph. Suppose that $G$ contains a $C_7$, say with vertex-set $C := \{v_1, v_2, v_3, v_4, v_5, v_6, v_7\}$ and edge-set \{$v_1 v_2$, $v_2 v_3$, $v_3 v_4$, $v_4 v_5$, $v_5 v_6$, $v_6 v_7$, $v_7 v_1$\}. Suppose to the contrary that $V(G)\sm C\neq \es$, and let $u\in V(G)\sm C$. Since $C\cup \{u\}$ does not induce a $2P_1+P_3$, clearly $u$ has a neighbor in $C$. First suppose that there is an $i\in [7]$ such that $uv_i, uv_{i+1}\in E(G)$.  Then since  $\{v_7,v_1,v_2,v_3,u\}$ does not induce a  $K_4-e$, we have $uv_7, uv_3\notin E(G)$. Then since $\{v_3,v_5,v_7,v_1,u\}$ does not induce a $2P_1+P_3$, we have $uv_5\in E(G)$, and then since $\{v_1,u,v_5,v_6,v_7\}$ and $\{v_2,v_3,v_4,v_5,u\}$ do not induce $C_5$'s, we have $uv_4,uv_6\in E(G)$, but then $\{u,v_4,v_5,v_6\}$ induces a $K_4-e$ which is a contradiction. So  we may assume that for each $i\in [7]$, we have either $uv_i\notin E(G)$ or $uv_{i+1}\notin E(G)$. Now since $u$ has a neighbor in $C$, we may assume that $uv_1\in E(G)$. Then by our claim, $uv_2,uv_7\notin E(G)$. Again from our claim and since $\{u,v_1,v_2,v_3,v_4\}$ and $\{u,v_5,v_6,v_7,v_1\}$ do not induce $C_5$'s, we have $uv_4,uv_5\notin E(G)$. Then since $\{v_4,v_6, u,v_1,v_2\}$ and $\{v_3,v_5, u,v_1,v_7\}$ do not induce ($2P_1+P_3$)'s, we have $uv_3,uv_6\in E(G)$. But then $\{u,v_3,v_4,v_5,v_6\}$ induces a $C_5$ which is a contradiction. This proves \cref{lem-2k1p3-c7}.
\end{proof}

\noindent{\bf Proof of \cref{main-thm-2}}. Let $G$ be a ($2P_1+P_3, K_4-e$)-free graph which is not perfect.   Then by \cref{spgt}, $G$ contains either an odd-hole or the complement graph of an odd-hole. Since the
complement graph of any odd-hole of length at least 7 contains a $K_4-e$, and since any odd-hole of length at least 9 contains a $2P_1+P_3$, we may assume that $G$ contains either a $C_5$ or a $C_7$. If $G$ is $C_5$-free and $G$ contains a $C_7$, then from \cref{lem-2k1p3-c7}, $G\cong C_7$, and hence $G$ is $3$-colorable and we are done. So suppose that $G$ contains a $C_5$. Then the theorem follows from  \cref{lem-2k1p3-c5}. This completes the proof of \cref{main-thm-2}. \hfill{$\Box$}

\subsection{Coloring ($2P_1+P_3, K_4-e$)-free graphs}

In this section, we prove \cref{col-thm-2} and its consequences.  First we prove the following.

 \begin{lemma}\label{col2-K4-free}
 If $G$ is a  ($2P_1+P_3, K_4-e, K_4$)-free graph, then $\chi(G)\leq 5$.
 \end{lemma}
 \begin{proof} Let $G$ be a  ($2P_1+P_3, K_4-e, K_4$)-free graph.   Let $v$ be any vertex in $G$.
 Then   clearly $N(v)$ induces a bipartite graph, and   $G[\overline{N}(v)]$ is  ($P_1+P_3, K_4-e, K_4$)-free.
It follows from a result of Gei\ss er \cite{Geiber} that  $\chi(G[\overline{N}(v)])\leq 3$. So $\chi(G)\leq \chi(G[N(v)])+\chi(G[\overline{N}(v)\cup\{v\}])\leq 2+3 =5$, and we are done.
  \end{proof}



\noindent{\bf Proof of \cref{col-thm-2}}.~Clearly \cref{col-thm-2}:$(i)$ follows from \cref{col2-K4-free}. To prove $(ii)$,
 let $G$ be a ($2P_1+P_3, K_4-e$)-free graph with $\omega(G)\geq 4$, and let $\ell = \max\{6, \omega(G)\}$. We may assume that $G$ is not perfect. We prove the theorem by induction on $|V(G)|$.  From  \cref{lem-good} and  \cref{main-thm-2}, we may assume that   $G$ has a vertex of degree at most $5$, say $v$.    By induction hypothesis, we have $\chi(G - \{v\}) \leq  \ell$. Since $v$ has at most 5 neighbors in $G - \{v\}$, we can take any $\ell$-coloring of $G - \{v\}$ and extend it to a $\ell$-coloring of $G$, using for $v$ a (possibly new) color that does not appear in its neighborhood.  This proves the first assertion.


The bound  is clearly tight when $\omega(G)\geq 6$ (for instance, take $G\cong K_t, t\geq 6$).   \hfill{$\Box$}


\medskip
We remark that   the bound given in \cref{col-thm-2} does not seem to be tight when $\omega(G)\in \{3,4,5\}$. Note that there are ($2P_1+P_3, K_4-e$)-free graphs with chromatic number equal to $4$ and clique number equal to 3; see  $H_1$ and $H_2$ in \cref{fig-opt}.

\begin{cor}\label{2P1P3-NOC}
The class of ($2P_1+P_3, K_4-e$)-free graphs is nearly optimal colorable. That is, every ($2P_1+P_3, K_4-e$)-free graph $G$ satisfies $\chi(G)\leq \max\{6, \omega(G)\}$.
\end{cor}
\begin{proof}
Since every ($2P_1+P_3, K_3$)-free graph $G$ satisfies $\chi(G)\leq 3$, by a result of Randerath \cite{Rand-Thesis}, the proof follows from \cref{col-thm-2}.
\end{proof}

 Brandst\"adt et al. \cite{BDHP} showed that \textsc{Coloring} for  the class of ($2P_1+P_3$, $K_4-e$)-free graphs is solvable in  polynomial time   for every fixed positive integer $k \leq 5$. This result together with \cref{2P1P3-NOC} and \cref{JH-thm}  imply  the following.

 \begin{cor}
  \textsc{Chromatic Number} for
	the class of ($2P_1+P_3$, $K_4-e$)-free graphs can be solved in  polynomial time.
 \end{cor}

