\section{The class of ($3P_1+P_2$,\,$K_4-e$)-free graphs}\label{sec:3P1+P2}
In this section, we give a proof of \cref{col-thm}, and it follows from a structure theorem for such class of graphs (see \cref{main-thm}).
First  we prove some general structural properties  of a ($3P_1+P_2$,\,$K_4-e$)-free graph  that  contains a $C_5$, and use them in the latter sections.

\subsection{Properties of ($3P_1+P_2$,\,$K_4-e$)-free graphs that contain a $C_5$}\label{3P1P2-prop}
Let $G$ be a ($3P_1+P_2$,\,$K_4-e$)-free graph.
Suppose that $G$ contains a  $C_5$, say with
 vertex-set $C:= \{v_1, v_2, v_3, v_4, v_5\}$ and edge-set $\{v_1 v_2, v_2 v_3, v_3 v_4, v_4 v_5, $ $v_5 v_1\}$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we  use the properties given in \cref{genprop}.   Moreover
for each $i\in [5]$, the following hold:
{\it \begin{enumerate}[label=  $(\mathbb{L} \arabic*)$, leftmargin=2.25cm] \itemsep=0pt
\item\label{df} $|D_{i}|\leq 1$.
\item \label{abf}       $A_{i}\cup T$ is a clique.
\item\label{ato}  $[A_{i}, A_{i+2} \cup D_{i+1}]$ is complete. Likewise,  $[A_{i}, A_{i-2} \cup D_{i-1}]$ is complete.
\item\label{abz} If $A_i\cup D_{i+1}\neq \es$, then $|X_{i-1}|\leq 1$. Likewise, if $A_i\cup D_{i-1}\neq \es$, then $|X_i|\leq 1$.
\item\label{abb}  One of  $A_{i}\cup D_i$, $B_{i-1}$ and $B_{i}$ is   empty.	
\item\label{afd} One of $A_{i}$, $D_{i+1}\cup D_{i-1}$ and $Z_{i}$ is   empty.
\item\label{bfd}One of $B_i$, $D_{i+2} \cup D_{i-1}$ and $Z_{i-2}$ is empty.
\item \label{zzd} One of $Z_{i}$, $B_i \cup B_{i+1} \cup Z_{i-2}$ and $D_{i+1}$ is empty. Moreover, $|D_{i+1}\cup Z_{i}\cup Z_{i-2}|\leq 2$.
  \end{enumerate}
}
        \begin{proof}
        \ref{df}:~If there are two vertices in $D_i$, say $x$ and $y$, then $xy\notin E(G)$ (by  \ref{DZ}), and then $\{v_{i}, x, y, v_{i-2}, v_{i+2}\}$ induces a  $3P_1+P_2$. So \ref{df} holds. $\sq$

\smallskip
  \no{\ref{abf}}:~If there are nonadjacent vertices  in $A_{i}\cup T$, say $u$ and $v$, then $\{u,v,v_{i-1},v_{i+1}, v_{i+2}\}$ induces a $3P_1+P_2$. So  \ref{abf} holds. $\sq$

\smallskip
  \no{\ref{ato}}:~If  there are nonadjacent vertices, say $u\in A_{i}$ and $v\in A_{i+2}\cup D_{i+1}$, then $\{u,v, v_{i+1}, v_{i-1}, v_{i-2}\}$ induces a $3P_1+P_2$. So \ref{ato} holds. $\sq$

\smallskip
  \no{\ref{abz}}:~If there  are two vertices in $X_{i-1}$, say $u$ and $v$, then $uv\in E(G)$ (by \ref{X-matching}), and then for any $w\in A_i\cup D_{i+1}$, $\{w, v_{i+1},v_{i-2},u,v\}$ induces a $3P_1+P_2$, by \ref{bto}. So \ref{abz} holds. $\sq$

\smallskip
  \no{\ref{abb}}:~Suppose to the contrary that there are vertices, say $u\in A_{i}\cup D_i$, $v\in B_{i-1}$ and  $w\in B_{i}$. Then from \ref{bto}, clearly $\{u,v,w\}$ is a stable set. But then   $\{u,v,w, v_{i-2}, v_{i+2}\}$ induces a $3P_1+P_2$ which is a contradiction. So \ref{abb} holds. $\sq$

\smallskip
  \no{\ref{afd}}:~Suppose to the contrary that there are vertices, say $x \in A_i$, $y\in D_{i+1}\cup D_{i-1}$ and $z\in Z_{i}$. Then $xy\in E(G)$, by \ref{ato} and $yz \not\in E(G)$, by \ref{bto}. Now if $xz \in E(G)$, then     $\{y,x,v_i,z\}$ induces a $K_4-e$; so $xz\notin E(G)$. But then $\{v_{i-1}, v_{i+1},  z,  x, y\}$  induces a $3P_1+P_2$ which is a contradiction. So \ref{afd} holds. $\sq$

\smallskip
  \no{\ref{bfd}}:~Suppose to the contrary that there are vertices, say $x \in B_i$, $y\in D_{i+2}\cup D_{i-1}$  and $z\in Z_{i-2}$. Then using \ref{X-matching} and \ref{bto}, we see that $\{ y, v_{i+2}, v_{i-1}, x, z\}$ induces $3P_1+P_2$ which is a contradiction. So \ref{bfd}  holds.  $\sq$

\smallskip
  \no{\ref{zzd}}:~Suppose to the contrary that there are vertices, say $x \in Z_i$, $y\in B_i \cup B_{i+1} \cup Z_{i-2}$  and $z\in D_{i+1}$. Then from \ref{X-matching} and  \ref{bto}, we see that $\{ v_{i-1}, x, z, y, v_{i+1}\}$ induces $3P_1+P_2$ which is a contradiction.
So the first assertion holds. The second assertion follows from the first assertion, \ref{DZ} and \ref{df}.
         \end{proof}


