\subsection{Structure of ($3P_1+P_2, K_4-e$)-free graphs} \label{Sec:Struc-thm}
Our main result in this section is the following.
 \begin{theorem}\label{main-thm}
If $G$ is a  ($3P_1+P_2, K_4-e$)-free graph, then either    $G$ has a vertex with degree  at most 6 or $G$ is a good graph with $\omega(G)\geq 4$.
\end{theorem}

The proof of \cref{main-thm} is based on a sequence of lemmas given below which depend on some special forbidden induced subgraphs that contain a $C_5$ or a $C_7$ (some of them are given in Figure~\ref{fig-F1234}), and it is given at the end of this section. We start with the following.


\begin{lemma}\label{NC5:deg6}
   Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. If $G$ contains  a $C_5+K_1$, then $G$ has a vertex with degree  at most 6.
\end{lemma}
\begin{proof}
 Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. Suppose that $G$ contains  a $C_5+K_1$,   say a $C_5$ with
 vertex-set $C:= \{v_1, v_2, v_3, v_4, v_5\}$ and edge-set $\{v_1 v_2, v_2 v_3, v_3 v_4, v_4 v_5, $ $v_5 v_1\}$ plus a vertex $t$  such that $[\{t\},C]=\es$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use the properties in Section~\ref{genprop} and in \cref{3P1P2-prop}.  Clearly $t\in T$. Moreover:

\begin{claim}\label{tto}
For each $i\in [5]$, we have $[T, A_{i}\cup D_{i+1}]$ is complete. Moreover, if $T\neq \es$, then $|A_i|\leq 1$ and $|X_i|\leq 2$.
\end{claim}
   \no{\it Proof of  \cref{tto}}.~If  there are vertices, say $u\in T$ and $v\in A_{i}\cup D_{i+1}$ such that $uv\notin E(G)$, then $\{u, v, v_{i+1}, v_{i-1}, $ $ v_{i-2}\}$ induces a $3P_1+P_2$; so the first assertion holds. Next if there are two vertices, say $a$ and $a'$ in $A_i$, then  for any $t\in T$, $\{t, a,a', v_i\}$ induces a $K_4-e$, by \ref{abf} and by the first assertion; so $|A_i|\leq 1$.

 Next, suppose to the contrary that there  are three vertices, say $u,v$ and $w$ in $X_i$. Note that $\{u,v,w\}$ is clique, by \ref{X-matching}. Now since $\{t, u,v,w, v_i\}$ does not induce a $K_4-e$, we see that $t$ is nonadjacent to at least two vertices in $\{u,v,w\}$, and we may assume that $tu, tv\notin E(G)$. Then $\{t,v_{i+2}, v_{i-1},u,v\}$ induces a $3P_1+P_2$ which is a contradiction; so $|X_i|\leq 2$. So \ref{tto} holds. $\sq$

 Next:

\begin{claim}\label{TA-emp}
  We may assume that $A$ is an empty set.
  \end{claim}
  \no{\it Proof of  \cref{TA-emp}}.~Suppose that $A\neq \es$, say $A_1\neq \es$. Let $a\in A_1$.  Then $|X_1|\leq 1$ and $|X_5|\leq 1$, by \ref{abz}. Also  for any $d\in D_{2}\cup D_{5}$, since $\{t,a,d,v_{i}\}$ does not induce a $K_4-e$ (by  \ref{ato}  and  \ref{tto}),  we have $D_2\cup D_5=\es$. Hence $d(v_1)=|N(v_1)| =
|\{v_2, v_5\}\cup A_1 \cup B_1 \cup B_5 \cup Z_1 \cup  Z_3 \cup Z_4| = |\{v_2, v_5\}|+ |A_1|+ |X_1|+ |X_5|+ |Z_1|\leq 2+1+1+1+1 = 6$, by \ref{tto} and \ref{DZ}, and we are done. So we may assume that $A = \es$. $\sq$



 Next:

\begin{claim}\label{TD-emp}
  We may assume that $D$ is an empty set.
  \end{claim}
  \no{\it Proof of  \cref{TD-emp}}.~Suppose that $D\neq \es$, say $D_2\neq \es$. Let $d\in D_2$. Then the following hold:
   \begin{enumerate}[label=($\roman*$)]\itemsep=0pt
   \item\label{TD-B} \emph{One of $B_1$ and $B_5$ is empty}: Otherwise, for any $b\in B_1$ and $b'\in B_5$, $\{d, b', v_4, b,v_2\}$  induces a $3P_1+P_2$, by \ref{bto}.
  \item\label{TD-Z13} \emph{One of $Z_1$ and $Z_3$ is empty}: Otherwise, for any $z\in Z_1$ and $z'\in Z_3$, $\{d, v_2,z, z', v_5\}$ induces a $3P_1+P_2$, by  \ref{bto}.
\item\label{TD-Z4} \emph{One of $D_5$ and $Z_4$ is empty}: From \ref{tto}, first note that for any $u\in D_5$, since $\{t,d,u,v_i\}$ does not induce a $K_4-e$, we have $du\notin E(G)$, and then for any $z\in Z_4$,   $\{v_5, u,z, v_3, d\}$  induces a $3P_1+P_2$ (by \ref{bto}); so one of $D_5$ and $Z_4$ is empty.
   \end{enumerate}
From \ref{TD-Z13} and \ref{DZ}, we have $|Z_1\cup Z_3|\leq 1$. From \ref{TD-Z4}, \ref{DZ} and  \ref{df}, we have $|D_5 \cup Z_4| \leq 1$. Moreover  $|D_5\cup X_1| \leq 2$, by \ref{df}, \ref{bfd} and \ref{tto}. Also $|D_2\cup X_5|\leq 2$, by  \ref{df} and \ref{abz}. Note that from  \cref{TA-emp}, $d(v_1)=|N(v_1)| =|\{v_2, v_5\}\cup B_1 \cup B_5 \cup D_2 \cup D_5 \cup Z_1 \cup  Z_3 \cup Z_4|$. Now from \ref{TD-B}, we have two cases. If $B_5=\es$, then $d(v_1)= |\{v_2, v_5\}|+  |D_2|+| Z_1\cup Z_3| + |D_5\cup X_1|\leq 2+1+1+2 = 6$, by \ref{df}, and we are done. So we may assume that $B_1=\es$. Then  $d(v_1)= |\{v_2,v_5\}| + |D_2\cup X_5| + |D_5 \cup Z_4| + |Z_1|\leq 2 + 2 + 1 + 1 = 6$, by \ref{df}, and again we are done. So we may assume that $D=\es$.  $\sq$

%Next:
%\begin{claim}\label{TBi-Nemp}
%  We may assume that $B_i \neq \es$, for each $i \in [5]$, and that $Z_i \neq \es$, for each $i\in [5]$.
%  \end{claim}
%\no{\it Proof of  \cref{TBi-Nemp}}.~Suppose that there is an index $i\in [5]$ such that $B_{i}=\es$, say $i=1$. Then from \ref{DZ} and from above claims, we see that $d(v_1)=|\{v_2,v_5\}|+|X_5|+|Z_1|+|Z_4|\leq 2+2+1+1 = 6$, and we are done. So we may assume that $B_i \neq \es$, for each $i \in [5]$.
%
%Next suppose that there is an index $i\in [5]$ such that $Z_{i}=\es$, say $i=1$. Then from above claims, we see that $d(v_1)=|\{v_2,v_5\}|+|X_1|+|X_5|\leq 2+2+2 = 6$, and we are done. So we may assume that $Z_i \neq \es$, for each $i \in [5]$.  $\sq$

 Next:
\begin{claim}\label{TBi-Nemp}
  We may assume that $|X_i|=2$, for each $i\in [5]$.
  \end{claim}
\no{\it Proof of  \cref{TBi-Nemp}}.~Suppose that there is an index $i\in [5]$ such that $|X_{i}|\leq 1$, say $i=1$. Then from \ref{DZ} and from above claims, we see that $d(v_1)=|\{v_2,v_5\}|+|X_1|+|X_5|+|Z_1|\leq 2+1+2+1 = 6$, and we are done. So from \cref{tto}, we may assume that $|X_i|=2$, for each $i \in [5]$. $\sq$


\medskip
  From \cref{TBi-Nemp},  for each $i\in [5]$, there are vertices in $X_i$, say $x_i$ and $x_i'$,  such that  $x_ix_i'\in E(G)$, by \ref{X-matching}. Then:

 \begin{claim}\label{deg-t}
 For each $i\in [5]$, we have $|N(t)\cap X_i|\leq 1$. Moreover, $|N(t)\cap T|\leq 1$.
 \end{claim}
\no{\it Proof of  \cref{deg-t}}.~If  $|N(t)\cap X_i|=2$, then $\{t, x_i, x_i', v_i\}$ induces a $K_4-e$; so the first assertion holds. Next suppose to the contrary that there are vertices in $T$, say $t'$ and $t''$ such that $\{t,t',t''\}$ is a clique (by \ref{abf}). Then since $\{v_3,v_5,x_1,t,t',t''\}$ does not induce a $3P_1+P_2$ or a $K_4-e$, clearly $x_1$ is adjacent to every vertex in  $\{t,t',t''\}$. Likewise, $x_2$ is adjacent to every vertex in  $\{t,t',t''\}$. But then from \ref{bto},  $\{x_1,t,t',x_2\}$ induces a $K_4-e$ which is a contradiction. So $|N(t)\cap T|\leq 1$. $\sq$

\medskip
From \cref{deg-t}, we conclude that $d(t)\leq |N(t)\cap T|+ \sum_{i=1}^5|N(t)\cap X_i|\leq 6$. This proves \cref{NC5:deg6}.
\end{proof}

