\begin{lemma}\label{F1:thm}
    Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. If $G$ contains  an $F_1$, then $G$ has a vertex with degree  at most 6.
\end{lemma}
\begin{proof}
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. Suppose that $G$ contains  an $F_1$ as shown in Figure~\ref{fig-F1234}.  We let  $C:= \{v_1, v_2, v_3, v_4, v_5\}$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use the properties in Section~\ref{genprop}  and in \cref{3P1P2-prop}. Clearly $a_3\in A_3$, $x\in B_3$ (if $xv_1\notin E(G)$) and $x\in Z_3$ (if $xv_1\in E(G)$).   Moreover  the following hold.
\begin{enumerate}[label=($\roman*$)]\itemsep=0pt
   \item\label{F1-A3} If there is a vertex, say $a'~(\neq a_3)$ in $A_3$, then $a_3a'\in E(G)$ (by \ref{abf}), and then from \ref{bto}, we see that $\{v_2,v_5,x,a_3,a'\}$ induces a $3P_1+P_2$; so $A_3=\{a_3\}$ and $|A_3|=1$.
       \item\label{F1-D2}  If there is a vertex, say $d\in D_2$, then $\{v_2,v_5,x,a_3,d\}$  induces a $3P_1+P_2$ (by \ref{bto} and \ref{ato}); so $D_2=\es$.
  \item\label{F1-B3Z1} Since $A_3\neq \es$,  we have $|D_4\cup Z_3|\leq 1$ (by \ref{DZ}, \ref{df} and \ref{afd}), and   $|X_2|\leq 1$ and $|X_3|\leq 1$ (by \ref{abz}).

   \end{enumerate}
Now from above items, we see that $d(v_3)=|N(v_3)|= |\{v_2, v_4\}|+|A_3|+
 |X_2|+|X_3|+|D_4 \cup Z_3|\leq 2+1+1+1+1 =6$. This proves \cref{F1:thm}.
\end{proof}


\begin{lemma}\label{F2:thm}
    Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. If $G$ contains  an $F_2$, then $G$ has a vertex with degree  at most 6.
\end{lemma}
\begin{proof}
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. From \cref{F1:thm}, we may assume that $G$ is $F_1$-free. Suppose that $G$ contains  an $F_2$ as shown in Figure~\ref{fig-F1234}.  We let  $C:= \{v_1, v_2, v_3, v_4, v_5\}$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use the properties in Section~\ref{genprop}  and in \cref{3P1P2-prop}. Clearly $a_3\in A_3$  and $a_4\in A_4$. Since $A_3, A_4\neq \es$  and since $G$ is $F_1$-free, we have $B_2\cup B_3\cup Z_1\cup Z_5 =\es$. Also since $A_3\neq \es$, we have $|D_4\cup Z_3|\leq 1$ (by \ref{DZ}, \ref{df} and \ref{afd}). Moreover  if there are vertices, say $a_3'$ and $a_3''$, which are distinct from $a_3$, since $\{a_3,a_3',a_3''\}$ is a clique (by \ref{abf})  and  since $\{v_2,v_5,a_4,a_3,a_3',a_3''\}$ does not induce a $3P_1+P_2$, we see that $a_4$ is adjacent to at least two vertices in $\{a_3,a_3',a_3''\}$, and then $\{a_4, a_3,a_3',a_3'', v_3\}$ induces a $K_4-e$; so we conclude that $|A_3|\leq 2$. Thus
   $d(v_3)=  |\{v_2, v_4\}\cup A_3  \cup D_2\cup  D_4 \cup Z_3 |= |\{v_2, v_4\}|+|A_3|+
 |D_2|+ |D_4 \cup Z_3|\leq 2+2+1+1=6$, by \ref{df}. This proves \cref{F2:thm}.
\end{proof}

\begin{lemma}\label{F3:thm}
    Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. If $G$ contains  an $F_3$, then either $G$ has a vertex with degree  at most 6 or $G$ is a good graph with $\omega(G)\geq 4$.
\end{lemma}
\begin{proof}
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph.  From \cref{NC5:deg6,F1:thm,F2:thm}, we may assume that $G$ is ($F_1, F_2, C_5+K_1$)-free. Suppose that $G$ contains  an $F_3$  as shown in Figure~\ref{fig-F1234}. We let  $C:= \{v_1, v_2, v_3, v_4, v_5\}$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use the properties in Section~\ref{genprop}  and in \cref{3P1P2-prop}. Clearly  $b_1\in B_1$, $b_3\in B_3$ and $b_5\in B_5$. Since $G$ is $F_1$-free, we have $A=\es$, and since $G$ is ($C_5+K_1$)-free, we have $T=\es$. Recall that $[B_1, B_5] =\es$, by \ref{bto}.  In addition, we have the following.
 \begin{claim}\label{F3-D125}
  $D_1\cup D_2\cup D_5$ is an empty set.
 \end{claim}
\no{\it Proof of  \cref{F3-D125}}.~Suppose to the contrary that $D_1\cup D_2\cup D_5\neq \es$, and let $x\in D_1\cup D_2\cup D_5$. Then clearly $x\notin D_1$, by \ref{abb}. So, up to symmetry, we may assume that $x\in D_2$. Note that $x$ is nonadjacent to every vertex in $\{b_1,b_3,b_5\}$, by \ref{bto}. Now since $\{v_5,b_3,x,b_1,v_2\}$ and $\{v_2,b_3,x,b_5,v_5\}$ do not induce $3P_1+P_2$'s, we have $b_1b_3\in E(G)$ and $b_3b_5\in E(G)$. But then $\{b_1,b_3,v_4,v_5,v_1,b_5,x\}$ induces an $F_1$ which is a contradiction to our assumption that $G$ is $F_1$-free. So \cref{F3-D125} holds. $\sq$

Next:
\begin{claim}\label{F3-D34}
  We may assume that  $D_3\cup D_4$ is an empty set.
 \end{claim}
\no{\it Proof of  \cref{F3-D34}}.~Suppose that $D_3\neq \es$. We let $D_3=\{x\}$, by \ref{df}.  Now if $|N(x)\cap B_5|\geq 2$, then for any $b, b' \in N(x)\cap B_5$ (say), we see that $\{v_5,b,b',x\}$ induces a $K_4-e$ (by \ref{X-matching}); so $|N(x)\cap B_5|\leq 1$. Then from \ref{DZ}, \ref{bto},  \ref{df} and \cref{F3-D125}, we observe that $d(x) =|\{v_2,v_4\}|+|N(x)\cap B_5|+|N(x)\cap D_4|+|N(x)\cap Z_3| \leq 2+1+1+1 =5$,  and we are done. So we may assume that  $D_3 =\es$. Likewise, we may assume that  $D_4=\es$.   $\sq$

Next:
\begin{claim}\label{F3-Z25}
  We may assume that  $Z_2\cup Z_5$ is an empty set.
 \end{claim}
\no{\it Proof of  \cref{F3-Z25}}.~Suppose that $Z_5\neq \es$. We let $Z_5=\{z\}$, by \ref{DZ}. Note that $z$ is nonadjacent to every vertex in $B_1\cup B_3\cup B_5$, by \ref{bto}. Now if there is a vertex, say $x~(\neq b_5)$ in $X_5$, then $xb_5\in E(G)$ (by \ref{X-matching}), and then $\{z,b_1,v_4,b_5,x\}$ induces a $3P_1+P_2$ (by \ref{bto}); so $|X_5|=1$. A similar argument shows that $|B_1|=1$.
Hence from above claims  and from \ref{DZ},  we have $d(v_1)=|\{v_2, v_5\} \cup B_1 \cup X_5 \cup Z_1 \cup Z_4| = |\{v_2, v_5\}|+|B_1|+|X_5|+|Z_1|+|Z_4|\leq 2+1+1+1+1 = 6$, and we are done. So we may assume that  $Z_5 =\es$. Likewise, we may assume that  $Z_2=\es$.   $\sq$

Next:
 \begin{claim}\label{F3-B24}
  We may assume that  $B_2\cup B_4$ is an empty set.
 \end{claim}
\no{\it Proof of  \cref{F3-B24}}.~Suppose that $B_2\neq \es$. Let $x \in B_2$.  Then since $x$ is nonadjacent to both $b_1$ and $b_3$ (by \ref{bto}), and since $\{v_1, b_1, b_3, v_4, v_5, x\}$ does not induce  a $C_5+K_1$, we have $b_1b_3\notin E(G)$. Then since $\{x,v_3,v_4,v_5,b_5,b_1\}$ does not induce  a $C_5+K_1$, we have $xb_5\notin E(G)$.
Now if there is a vertex, say $x'~(\neq x)$ in $B_2$, then $xx'\in E(G)$ (by \ref{X-matching}), and then $\{b_1,b_3,v_5,x,x'\}$ induces a $3P_1+P_2$; so $|B_2|=1$. A similar argument shows that $|B_1|=1$. Thus from above claims and from \ref{DZ},  we have $d(v_2)=|\{v_1, v_3\}|+ |B_1|+|B_2|+|Z_4|\leq 2+1+1+1  = 5$,  and we are done. So we may assume that  $B_2 =\es$. Likewise, we may assume that  $B_4=\es$.   $\sq$

\medskip
 From above conclusions, we observe that $V(G) = C \cup X_1 \cup X_3 \cup X_5$.  If $|X_1|\leq 1$, then from \ref{DZ} and from above conclusions, $d(v_2)=|N(v_2)|= |\{v_1,v_3\}\cup X_1|\leq 3$, and we are done; so we may assume that $|X_1|\geq 2$. Then since $\{v_3,v_4\}\cup X_1$ is a clique (by \ref{X-matching}), we have $\omega(G)\geq 4$. Also recall that since  $[X_1, X_5]=\es$ (by \ref{bto}), and $\{X_1, X_3\}$ and $\{X_3, X_5\}$ are graded (by \ref{X-matching}), we conclude that $V(G)$ can be partitioned into three cliques, namely $\{v_1, v_2\}\cup X_1$,  $\{v_3, v_4\}\cup X_3$  and $\{v_5\}\cup X_5$ which are pairwise graded. Hence $G$ is a good graph with $\omega(G)\geq 4$. This proves \cref{F3:thm}.
 \end{proof}




\begin{lemma}\label{F4:thm}
    Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. If $G$ contains  an $F_4$, then either $G$ has a vertex with degree  at most 6 or $G$ is a good graph with $\omega(G)\geq 4$.
\end{lemma}
\begin{proof}
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph.  From \cref{NC5:deg6,F1:thm,F2:thm}, we may assume that $G$ is ($F_1, F_2, C_5+K_1$)-free. Suppose that $G$ contains  an $F_4$  as shown in Figure~\ref{fig-F1234}. We let  $C:= \{v_1, v_2, v_3, v_4, v_5\}$. Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use the properties in Section~\ref{genprop} and in \cref{3P1P2-prop}.   Clearly  $b_1\in B_1$, $b_3\in B_3$ and $a_5\in A_5$. Since $G$ is $F_1$-free, we have $A\sm A_5=\es$ and $X_4\cup X_5=\es$, and since $G$ is ($C_5+K_1$)-free, we have $T=\es$.  Moreover  we have the following.

\begin{enumerate}[label=$(\roman*)$, leftmargin=1.1cm]\itemsep=0pt
\item \label{F4-A5} If $|A_5|\leq 1$, then $d(v_5) = |N(v_5)| = |\{v_1, v_4\}| + |A_5|+|D_1| + |D_4| +|Z_5|  \leq 2 + 1+1 + 1 +1 = 6$ (by \ref{DZ} and \ref{df}), and we are done; so we may assume that $|A_5|\geq 2$.
   \item\label{F4-B13} If $|B_1|\leq 1$, then by using \ref{DZ} and \ref{df}, since $|D_2 \cup Z_1|\leq 1$ (by \ref{zzd}),  we see that $d(v_1) = |N(v_1)| = |\{v_2, v_5\}| + |B_1| + |D_2 \cup Z_1|+|Z_4| + |D_5| \leq 2 + 1 + 1+1 + 1 = 6$, and we are done; so we may assume that $|B_1|\geq 2$. Likewise, we may assume that $|B_3|\geq 2$. Hence there exist vertices, say $u, u' \in B_1$ and $v, v'\in B_3$ such that $uu', vv'\in E(G)$ and $uv\not\in E(G)$, by \ref{X-matching}.
       \item\label{F4-B2}  For any $b\in B_2$, since $\{u',v_1,v_5,v_4,v, b\}$ does not induce a $C_5+K_1$, we have $u'v\notin E(G)$ (by \ref{bto}), and then    $\{b,v,v_5,u,u'\}$  induces a $3P_1+P_2$ (by \ref{F4-B13} and \ref{bto}); so $B_2=\es$.
       \item \label{F4-D235} For any $d\in D_2\cup D_3\cup D_5$, since  $\{d, v_5, v, u, v_2\}$ or $\{d, v_5, u,v_3, v\}$ does  not induce a $3P_1+P_2$ (by \ref{F4-B13} and \ref{bto}), we see  that  $D_2\cup D_3\cup D_5 =\es$.
       \item\label{F4-A5D1D4} For any $d\in D_1$ and $d'\in D_4$, since $\{d,a_5,v_5,d'\}$ does not induce a $K_4-e$ (by \ref{ato}), $[D_1, D_4]$ is complete, and hence $A_5\cup D_1\cup D_4$ is a clique, by \ref{df}, \ref{abf} and \ref{ato}.

       \item\label{F4-A5Z5} If there are vertices, say $z\in Z_5$ and  $a\in A_5$ such that $za\notin E(G)$, then for any $a'\in A_5\sm \{a\}$ (such a vertex $a'$ exists by \ref{F4-A5}) $aa'\in E(G)$ (by \ref{abf}), and then    $\{v_1,z,v_4, a,a'\}$ induces a $3P_1+P_2$  or $\{z,a,a',v_5\}$ induces a $K_4-e$; so $[A_5,Z_5]$ is complete.
                       \item\label{F4-grad} As in the proof of \ref{X-matching}, by using \ref{abf}, we see that $\{A_5, X_1\}$ and $\{A_5, X_3\}$ are graded.
              \end{enumerate}

Thus from above conclusions, we see that $V(G) = C \cup A_5 \cup X_1 \cup X_3 \cup D_1 \cup D_4   \cup Z_5$, where  $|A_5| \geq 2$, $|B_1| \geq 2$ and $|B_3| \geq 2$. Since $|B_1|\geq 2$, clearly  $\omega(G) \geq 4$ (by \ref{X-matching}).  Also since $A_5\neq \es$, we see that one of $D_1\cup D_4$ and $Z_5$ is empty, by \ref{afd}.  Now we let $Q_1:= \{v_5\} \cup A_5 \cup D_1 \cup D_4\cup Z_5$, $Q_2:= \{v_1, v_2\} \cup X_1$ and $Q_3:= \{v_3, v_4\} \cup X_3$. Then from  \ref{X-matching}, \ref{bto}, \ref{F4-A5D1D4}, \ref{F4-A5Z5} and \ref{F4-grad}, we deduce that $Q_1, Q_2$ and $Q_3$ are three cliques which are pairwise graded  whose union is $V(G)$.   Hence $G$ is a good graph with $\omega(G)\geq 4$. This completes the proof.
\end{proof}





\begin{lemma}\label{C5:thm}
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph. If $G$ contains  a $C_5$, then   either $G$ has a vertex with degree  at most 6 or $G$ is a good graph with $\omega(G)\geq 4$.
\end{lemma}
\begin{proof}
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph.  From \cref{NC5:deg6,F1:thm,F2:thm,F3:thm,F4:thm}, we may assume that $G$ is ($F_1, F_2, F_3, F_4, C_5+K_1$)-free.  Suppose that $G$ contains  a  $C_5$, say with vertex-set $C:= \{v_1, v_2, v_3, v_4, v_5\}$ and edge-set  $\{v_1 v_2, v_2 v_3, v_3 v_4, v_4 v_5, $ $v_5 v_1\}$.   Then, with respect to $C$, we define the sets $A$, $B$, $D$, $Z$   and $T$ as in Section~\ref{genprop}, and we use the properties in Section~\ref{genprop}  and in \cref{3P1P2-prop}.
Moreover:

 \begin{claim}\label{C5-B13}
  We may assume that  there does not exist an index $i\in [5]$  such that $B_i$ and $B_{i+2}$ are nonempty.
 \end{claim}
   \no{\it Proof of \cref{C5-B13}}.~Suppose that there  exists an index $i\in [5]$  such that $B_i$ and $B_{i+2}$ are nonempty, say $i=1$.   Then since $G$ is $F_3$-free, we have $B_4\cup B_5=\es$. Also  since $G$ is $F_4$-free, we have $A_5=\es$. Now since $B_1 \neq \es$, one of $D_1$ and $Z_5$ is empty (by  \ref{zzd}), and hence $|D_1\cup Z_5| \leq 1$, by \ref{DZ} and \ref{df}. So $d(v_5) = |N(v_5)| = |\{v_1, v_4\}| + |D_1 \cup Z_5| + |D_4| + |Z_2| + |Z_3| =2+1+1+1+1 \leq 6$ (by \ref{DZ} and \ref{df}), and we are done. $\sq$

Then:
\begin{claim}\label{C5-B15}
  We may assume that  there does not exist an index $i\in [5]$  such that $B_i$ and $B_{i+1}$ are nonempty.
 \end{claim}
 \no{\it Proof of \cref{C5-B15}}.~Suppose that there  exists an index $i\in [5]$  such that $B_i$ and $B_{i+1}$ are nonempty, say $i=5$.   Then by using \cref{C5-B13}, we have $B_2\cup B_3\cup B_4 = \es$. Since $G$ is $F_1$-free, we have $A_1\cup A_2\cup A_5=\es$. Recall that $[B_1, B_5]=\es$, by \ref{bto}. Moreover we have the following.
 \begin{enumerate}[label=($\roman*$)]\itemsep=0pt
\item \label{C5-B15-D2} If there is a vertex, say $d\in D_2$,  then for any $b_1\in B_1$ and $b_5\in B_5$, we see that $\{v_1, d, v_3, v_4, v_5,b_5,b_1\}$   induces an $F_1$ (by \ref{bto}); so $D_2=\es$.

    \item If there are vertices, say $a\in A_3$ and $b\in B_1$ such that $ab\notin E(G)$, then since $\{b_5,a,v_4,b,v_2\}$ does not induce a $3P_1+P_2$, we have $ab_5\in E(G)$, and then $\{b_5,a,v_3,v_4,v_5,b\}$ induces a $C_5+K_1$ which is a contradiction; so we conclude that $[A_3, B_1]$ is  complete. Hence if there are two vertices, say $a,a'$ in $A_3$, then $\{b_1,a,a',v_3\}$ induces a $K_4-e$; so $|A_3|\leq 1$.
    \end{enumerate}
   Now from above conclusions and since $|D_4 \cup Z_1 \cup Z_3| \leq 2$ (by \ref{zzd}), we see that $d(v_3) = |\{v_2, v_4\}| + |D_4 \cup Z_1 \cup Z_3| + |A_3|+|Z_5| \leq 2 + 2 + 1+1 = 6$, by \ref{DZ}, and  we are done. $\sq$

Finally:
   \begin{claim}\label{C5-B}
 We may assume that $B$ is an empty set.
   \end{claim}
 \no{\it Proof of \cref{C5-B}}.~Suppose that $B\neq \es$. Then from \cref{C5-B13} and \cref{C5-B15}, we may assume that there is an index $i\in [5]$  such that $B_i\neq \es$ and $B\sm B_i=\es$, say $i=5$.    Then since $G$ is $F_1$-free, $A_1\cup A_5 =\es$, and so $A = A_2 \cup A_3 \cup A_4$. Also since $G$ is $F_2$-free,  there exists an index $j\in \{2,3,4\}$ and $j$ mod 5 such that $A_j=\es$, and then $d(v_j) = |\{v_{j-1}, v_{j+1}\}|+|D_{j-1}|+|D_{j+1} \cup Z_j \cup Z_{j-2}|+|Z_{j+2}| \leq 2+1+2+1 =6$ (by \ref{DZ}, \ref{df} and \ref{zzd}), and we are done. $\sq$

\medskip
Now since $G$ is $F_2$-free, there exists an index $i\in [5]$ such that $A_i=\es$, say $i=2$. Clearly  $|D_3 \cup Z_2 \cup Z_5| \leq 2$, by \ref{zzd}. So from \cref{C5-B}, we conclude that $d(v_2) = |\{v_1, v_3\}| + |D_1| + |D_3 \cup Z_2 \cup Z_5| + |Z_4| \leq 2 + 1 + 2 + 1 = 6$. This proves \cref{C5:thm}.
 \end{proof}

 \begin{lemma}\label{C7:thm}
Let $G$ be a  ($3P_1+P_2, K_4-e, C_5$)-free graph. If $G$ contains  a $C_7$, then    $G$ has a vertex with degree  at most 6.
\end{lemma}
\begin{proof}
Let $G$ be a ($3P_1+P_2, K_4-e, C_5$)-free graph. Suppose that $G$ contains an induced $C_7$, say with
 vertex-set $C:= \{v_1, v_2, ,\ldots, v_6, v_7\}$ and edge-set $\{v_1 v_2, v_2 v_3, \ldots,  v_6 v_7, v_7v_1\}$.  For $i\in [7]$, we let  $A_i:=\{u\in V(G)\sm C \mid uv_i, uv_{i+1}\in E(G)$ and $uv_{i+2}, uv_{i-1}, uv_{i-3}\notin E(G)\}$, and let $A=\cup_{i=1}^7A_i$. Then we have the following.
 \begin{claim}\label{C7-nei}
 $V(G) = C\cup A$.
 \end{claim}
 \no{\it Proof of \cref{C7-nei}}.~Suppose not. Let $u\in  V(G)\sm (C\cup A)$.  First suppose that there exists an index $i\in  [7]$ such that $uv_i,uv_{i+1}\in E(G)$.
Then since $\{u,v_i,v_{i+1},v_{i-1}\}$ and $\{u,v_i,v_{i+1},v_{i+2}\}$ do not induce $K_4-e$'s, we have  $uv_{i-1},uv_{i+2}\notin E(G)$.
Now if $uv_{i-3} \in E(G)$, then since $\{v_i,u,v_{i-3},v_{i-2},v_{i-1}\}$ and $\{v_{i+1},u,v_{i-3},v_{i+3},v_{i+2}\}$ do not induce $C_5$'s, we have $uv_{i-2},uv_{i+3}\in E(G)$, and then $\{v_{i-2},u,v_{i-3},$ $v_{i+3}\}$ induces a $K_4-e$; so $uv_{i-3} \notin E(G)$, and hence $u\in A_i$ which is a contradiction. So we may assume that for each $i\in [7]$, either $uv_i\notin E(G)$ or $uv_{i+1}\notin E(G)$. But since $G$ is  ($3P_1+P_2$)-free, clearly $u$ has neighbor in $C$, say $uv_1\in E(G)$. So from our assumption, we have $uv_2,uv_7\notin E(G)$.  Then since $\{v_7,u,v_2,v_4,v_5\}$ does not induce a $3P_1+P_2$, either $uv_4 \in E(G)$ or $uv_5\in E(G)$, say $uv_4\in E(G)$ (by symmetry). But then since $uv_3\notin E(G)$ (by our assumption), we see that $\{v_1,v_2,v_3,v_4,u\}$ induces a $C_5$ in $G$ which is a contradiction. So $V(G)\sm (C\cup A)=\es$, and \cref{C7-nei} holds. $\sq$

\begin{claim}\label{C7-Aicard}
For each $i\in [7]$, we have $|A_i|\leq 1$.
 \end{claim}
 \no{\it Proof of \cref{C7-Aicard}}.~If there are  vertices, say $a$ and $a'$ in $A_i$, then since $\{a,v_i,v_{i+1},a'\}$ does not induce a $K_4-e$, we have $aa'\in E(G)$, and then $\{v_{i+2}, v_{i-1}, v_{i-3},a,a'\}$ induces a $3P_1+P_2$; so  $|A_i|\leq 1$. $\sq$

\medskip
Now from above conclusions, $d(v_1)\leq |\{v_2,v_7\}|+|A_1|+|A_3|+|A_5|+|A_7|\leq 6$. This completes the proof.
 \end{proof}




\medskip
\noindent{\bf Proof of \cref{main-thm}}.
Let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph which is not perfect.  Then by \cref{spgt}, $G$ contains either an odd-hole or the complement graph of an odd-hole. Since the complement graph of any odd-hole of length at least 7 contains a $K_4-e$,  and since any odd-hole of length at least 9 contains a $3P_1+P_2$, we may assume that $G$ contains either a $C_5$ or a $C_7$. If $G$ contains a $C_5$, then the theorem follows from \cref{C5:thm}, and if $G$ is $C_5$-free and contains a $C_7$, then the theorem follows from \cref{C7:thm}. This proves \cref{main-thm}.
\hfill{$\Box$}

\subsection{Coloring ($3P_1+P_2$,\,$K_4-e$)-free graphs}\label{Sec:col}

In this section, we prove \cref{col-thm} and its consequences. First we prove the following.

 \begin{lemma}\label{col-K4-free}
 If $G$ is a  ($3P_1+P_2, K_4-e, K_4$)-free graph, then $\chi(G)\leq 5$.
 \end{lemma}
 \begin{proof} Let $G$ be a  ($3P_1+P_2, K_4-e, K_4$)-free graph.   Let $v$ be any vertex in $G$.
 Then   clearly $N(v)$ induces a bipartite graph, and   $G[\overline{N}(v)]$ is  ($2P_1+P_2, K_4-e, K_4$)-free.
It follows from a result of Gy\'arf\'as \cite{Gyarfas} that  $\chi(G[\overline{N}(v)])\leq 3$. So $\chi(G)\leq \chi(G[N(v)])+\chi(G[\overline{N}(v)\cup\{v\}])\leq 2+3 =5$, and we are done.
  \end{proof}



\noindent{\bf Proof of \cref{col-thm}}.~Clearly \cref{col-thm}:$(i)$ follows from \cref{col-K4-free}. To prove $(ii)$, let $G$ be a  ($3P_1+P_2, K_4-e$)-free graph with $\omega(G)\geq 4$, and let $\ell := \max\{7, \omega(G)\}$. We prove the theorem by induction on $|V(G)|$. From  \cref{main-thm} and \cref{lem-good}, we may assume that $G$ has a vertex with degree  at most 6, say $v$. By induction hypothesis, we have $\chi(G-\{v\})\leq  \ell$. Since $v$ has at most 6 neighbors in $G-\{v\}$,  we can take any $ \ell$-coloring
of $G-\{v\}$ and extend it to a $\ell$-coloring of $G$, using for $v$ a (possibly new) color
that does not appear in its neighborhood. This proves $(ii)$.

Clearly the bound in \cref{col-thm} is  tight when $\omega(G)\geq 7$ (for instance, take $G\cong K_t$ where $t\geq 7$).
\hfill{$\Box$}







\medskip
We remark that   the bound given in \cref{col-thm} does not seem to be tight when $\omega(G)\in \{3,4,5,6\}$. Note that there are ($3P_1+P_2, K_4-e$)-free graphs with chromatic number equal to $4$ and clique number equal to 3; see \cref{fig-opt} for such graphs.


\begin{cor}\label{3P1P2-NOC}
The class of ($3P_1+P_2, K_4-e$)-free graphs is nearly optimal colorable. That is, every ($3P_1+P_2, K_4-e$)-free graph $G$ satisfies $\chi(G)\leq \max\{7, \omega(G)\}$.
\end{cor}
\begin{proof}
Since every ($3P_1+P_3, K_3$)-free graph $G$ satisfies $\chi(G)\leq 3$, by a result of Randerath \cite{Rand-Thesis}, the proof follows from \cref{col-thm}.
\end{proof}






  Dabrowski,  Golovach and  Paulusma \cite{DGP-TCS14} showed that \textsc{Coloring} for  the class of ($3P_1+P_2$, $K_4-e$)-free graphs is solvable in  polynomial time   for every fixed positive integer $k \leq 6$. This result together with \cref{3P1P2-NOC} and \cref{JH-thm}  imply  the following.

 \begin{cor}
  \textsc{Chromatic Number} for
	the class of ($3P_1+P_2$, $K_4-e$)-free graphs can be solved in  polynomial time.
 \end{cor}






