\begin{algorithm}[t]
	\caption{UniCaCLF}\label{algorithm}
	\begin{algorithmic}[1]
		\Require A set of labeled temporal embedding feature ${X} = \{ {x_t}\} _{t = 1}^{{T}},{x_t} \in {\mathbb{R}^{C}},\forall t$, the corresponding instant-level labels $Y=\{ {y_t}\} _{t = 1}^T, {y_t} \in \{ 0,1\} ,\forall t$ and the learning rate $\eta$.
		\Ensure Learned parameter $W$ of UniCaCLF.
		\State Initialize the temporal instant feature sequence ${X^{(0)}} = X$
		\State Initialize the global context ${g^{(0)}} = {1 \over T}({\sum\nolimits_{t = 1}^T x _t})$
		\Repeat
		\For{$l=1:L$}
		\State ${X^l} = {f_{HAO}}({g^{(l - 1)}},{X^{(l - 1)}})$ 
		\State $g^{l} = {f_{ACU}}({g^{(l - 1)}},{X^{(l)}})$
		\EndFor
		\State Compute the loss function in Eq. \ref{eqn:07}
		\State Update $W$ by $W= W - \eta {\nabla _W}L$
		\Until {Converges}
	\end{algorithmic}
\end{algorithm}

\subsection{Training and Inference}
Each scale level of the feature pyramid outputs a temporal instant feature sequence, which is then fed into the classification head and regression head to localize forged segments. The overall loss function is defined as follows:
\begin{normalsize}
	\begin{equation}
	\label{eqn:07}
	Loss = {Loss_{cls}} + \varphi_{1}{Loss_{reg}} + \varphi_{2} {Loss_{CaCL}},
	\end{equation}
\end{normalsize}
where ${Loss_{cls}}$ is the classification loss and $Loss_{reg}$ is the regression loss. $\varphi_{1}$ and $\varphi_{2}$ are hyperparameters to balance the relationship between different losses. By default, we set $\varphi_{1} = 2$ and $\varphi_{2} = 0.5$. Since the forged segment usually occupies a small portion of an untrimmed video, we use the focal loss \cite{lin2017focal} as the classification loss because it can solve the problem of fake and genuine sample imbalance. Meanwhile, Distance-IoU (DIoU) loss \cite{zheng2020distance} is adopted as the regression loss for faster convergence during training and more accurate boundary. Algorithm \ref{algorithm} outlines the training process. 

In inference phase, our model output $({p_i},{s_i},{e_i})_{i = 1}^n$ as the prediction forgery set, where $n$ denotes the total number of prediction forged segments. $s_i$, $e_i$ represent the start time and end time of the $i$-th forged segment and $p_i$ is its classification confidence. Soft-NMS \cite{bodla2017soft} is applied to remove the redundant forged segments.

