\noindent To ensure that key results (including both simple and more complicated ones) are clearly visible and easily accessible, we formulate all of them as lemmas or theorems. Also, since we will be adapting results of \cite{Stojnicphretreal24}, we to a large degree parallel the methodology presented therein. However, to ensure that unnecessary repetitions are avoided whenever possible, we skip rehashing already introduced concepts and instead focus on emphasizing those that are different.







\vspace{.1in}

\noindent \underline{1) \textbf{\emph{Algebraic fd-pro characterization:}}}  Due to  rotational invariance of $A$ one can
 without loss of generality rotate $\bar{\x}$ so that it becomes $\bar{\x}=[\|\bar{\x}\|_2,0,\dots,0 ]^T$. That allows to
first rewrite (\ref{eq:ex1a4a0}) as
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} & &
   \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} \bar{\z}_{jm+1}^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
\nonumber \\
  \mbox{subject to} & &  A\x=\z \nonumber \\
  & &  A\bar{\x}=A_{:,1}\|\bar{\x}\|_2=\bar{\z} \nonumber \\
  & & \x^T\bar{\x}=x \nonumber \\
  & & \|\x\|_2^2=c, \label{eq:rdteq0a0a0}
\end{eqnarray}
with $A_{:,i}$ being the $i$-th column of $A$. After noting that restriction $\|\bar{\x}\|_2=1$ brings no loss of generality, one then also has
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} & &
   \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} A_{jm+1,1}^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
\nonumber \\
  \mbox{subject to} & &  A\x=\z \nonumber \\
   & & \x^T\bar{\x}=\x_1\|\bar{\x}\|_2=\x_1= x \nonumber \\
  & & \|\x\|_2^2=c, \label{eq:rdteq0a0}
\end{eqnarray}
After setting $r\triangleq \sqrt{c-x^2}$, (\ref{eq:rdteq0a0}) is further rewritten as
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} & &
     \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} A_{jm+1,1}^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
  \nonumber \\
  \mbox{subject to} & &  A\x=A_{:,1}x + A_{:,2:n}\x_{2:n} = \z \nonumber \\
   & & \sum_{i=2}^{n}\x_i=c-x^2=r^2, \label{eq:rdteq0a1}
\end{eqnarray}
Utilizing the Lagrangian we have
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} \max_{\y}   & &
     \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} A_{jm+1,1}^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
  +\y^TA_{:,1}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \nonumber \\
  \mbox{subject to}
     & & \sum_{i=2}^{n}\x_i=c-x^2=r^2. \label{eq:rdteq0a2}
\end{eqnarray}
We then also set $\g^{(0)}=A_{:,1}$ and write  (\ref{eq:rdteq0a2}) in the following more compact form
 \begin{eqnarray}
  \xi(c,x) = \min_{\|\x_{2:n}\|_2=r,\z} \max_{\y}  \lp
       \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} \lp \g_{jm+i}^{(0)}\rp^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp. \label{eq:rdteq0a3}
\end{eqnarray}
The above  is a key algebraic characterization of fd-pro. It is summarized in the following lemma together with its implications regarding theoretical solvability of RdM PR.

\begin{lemma} Consider rank $d$ measurements phase retrieval (RdM PR) problem with $dn$ unknowns and sample complexity $m$. Let $A\in\mR^{dm\times dn}$, $\g^{(0)}\triangleq A_{:,1}$, and assume a high-dimensional linear (proportional) regime,
with sample complexity ratio $\alpha=\lim_{n\rightarrow\infty}\frac{m}{n}$. Then, RdM PR is theoretically solvable (i.e., it has a unique (up to a global phase) solution) provided that
 \begin{equation}\label{eq:ta10}
 \forall x\neq 1 \qquad f_{rp}(1,x;A)>0,
\end{equation}
where
\begin{equation}\label{eq:ta11}
f_{rp}(c,x;A) \hspace{-.03in}\triangleq   \hspace{-.05in}\frac{1}{dn} \hspace{-.04in} \min_{\|\x_{2:n}\|_2=r,\z} \max_{\y}  \lp
       \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} \lp \g_{jm+i}^{(0)}\rp^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp.
\end{equation}
    \label{lemma:lemma1}
\end{lemma}
\begin{proof}
Follows as an automatic consequence of the preceding discussion and the recognition that (\ref{eq:ta11}) is (\ref{eq:rdteq0a3})  cosmetically  scaled by $\frac{1}{dn}$.
\end{proof}

The optimization on the right hand side of (\ref{eq:ta11}) is the so-called \emph{random primal}. We determine the corresponding \emph{random dual} next.





\vspace{.1in}
\noindent \underline{2) \textbf{\emph{Determining the random dual:}}} As usual within the RDT, the concentration of measure is utilized as well. This basically means that for any fixed $\epsilon >0$,  one has (see, e.g. \cite{StojnicCSetam09,StojnicRegRndDlt10,StojnicICASSP10var})
\begin{equation*}
\lim_{n\rightarrow\infty}\mP_{A}\left (\frac{|f_{rp}(c,x;A)-\mE_{A}(f_{rp}(c,x;A)|}{\mE_{A}(f_{rp}(c,x;A)}>\epsilon\right )\longrightarrow 0.\label{eq:ta15}
\end{equation*}
 The following, so-called random dual, theorem is another critically important RDT ingredient.
\begin{theorem} Assume the setup of Lemma \ref{lemma:lemma1} with the elements of $A\in\mR^{dm\times dn}$ ($\g^{(0)}\in\mR^{dm\times 1}$ and $A_{:,2:dn}\in\mR^{dm\times dn-1 }$), $\g^{(1)}\in\mR^{dm\times 1}$, and  $\h^{(1)}\in\mR^{(dn-1)\times 1}$  being iid standard normals. For two positive scalars $c$ and $x$  ($0\leq x \leq c$) set $r\triangleq \sqrt{c-x^2}$. Let
\vspace{-.0in}
\begin{eqnarray}
\cG  \hspace{-.12in} & \triangleq &  \hspace{-.12in} \lp A,\g^{(1)},\h^{(1)}\rp = \lp\g^{(0)},A_{:,2:dn},\g^{(1)},\h^{(1)}\rp  \nonumber \\
\phi(\x,\z,\y) \hspace{-.12in}& \triangleq &\hspace{-.12in}
        \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} \lp \g_{jm+i}^{(0)}\rp^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
\hspace{-.05in}  +\y^T \g^{(0)}x   +  \y^T \g^{(1)}\|\x_{2:dn}\|_2 + \lp \x_{2:dn}  \rp^T\h^{(1)}\|\y\|_2  -\y^T  \z
\nonumber \\
 f_{rd}(c,x;\cG) \hspace{-.12in} & \triangleq &  \hspace{-.12in}
\frac{1}{dn}  \min_{\|\x_{2:dn}\|_2=r,\z} \max_{\|\y\|_2=r_y,r_y>0}  \phi(\x,\z,\y)
  \nonumber \\
 \phi_0 \hspace{-.12in} & \triangleq &  \hspace{-.12in} \lim_{n\rightarrow\infty} \mE_{\cG} f_{rd}(c,x;\cG).\label{eq:ta16}
\vspace{-.0in}\end{eqnarray}
One then has \vspace{-.02in}
\begin{eqnarray}
  \lim_{n\rightarrow\infty}\mP_{ A } (f_{rp} (c,x; A )   >  \phi_0)\longrightarrow 1,\label{eq:ta17a0}
\end{eqnarray}
and
\begin{eqnarray}
\hspace{-.07in}(\phi_0  > 0)   &  \Longrightarrow  & \lp \lim_{n\rightarrow\infty}\mP_{\cG}\lp \frac{\xi(c,x)}{dn} = f_{rd}(c,x;\cG) >0 \rp \longrightarrow 1\rp
\quad  \Longrightarrow \quad \lp \lim_{n\rightarrow\infty}\mP_{ A } (f_{rp} (c,x; A )   >0)\longrightarrow 1 \rp  \nonumber \\
& \Longrightarrow & \lp \lim_{n\rightarrow\infty}\mP_{A} \lp \mbox{PR is (uniquely) solvable} \rp \longrightarrow 1\rp.\label{eq:ta17}
\end{eqnarray}
 \label{thm:thm1}
\end{theorem}\vspace{-.17in}
\begin{proof}
It is an immediate consequence of Theorem 1 in \cite{Stojnicphretreal24} which follows through conditioning on $\g^{(0)}$ and application of the Gordon's comparison theorem (see, e.g., Theorem B in \cite{Gordon88}). Gordon's theorem can be obtained as a special case of a series of Stojnic's results from \cite{Stojnicgscomp16,Stojnicgscompyx16} (see Theorem 1, Corollary 1, and Section 2.7.2 in \cite{Stojnicgscomp16} as well as Theorem 1, Corollary 1, and Section 2.3.2 in \cite{Stojnicgscompyx16}).
\end{proof}




\vspace{.1in}
\noindent \underline{3) \textbf{\emph{Handling the random dual:}}} To handle the above random dual we rely on \cite{Stojnicphretreal24} (the results of \cite{Stojnicphretreal24} were obtained following the methodologies invented in \cite{StojnicCSetam09,StojnicICASSP10var,StojnicISIT2010binary,StojnicICASSP10block,StojnicRegRndDlt10}). After solving the optimizations over $\x$ and $\y$ we first obtain from (\ref{eq:ta16})
\begin{equation}
 f_{rd}(c,x;\cG) \hspace{-.03in}= \hspace{-.05in}
\frac{1}{dn}  \min_{\z} \max_{r_y>0}
\lp
        \sum_{i=1}^{m} \lp \sqrt{\sum_{j=0}^{d-1} \lp \g_{jm+i}^{(0)}\rp^2}
   -
   \sqrt{\sum_{j=0}^{d-1} \z_{jm+i}^2  }
   \rp^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2 r_y - \|\h^{(1)} \|_2 r r_y \rp.
\label{eq:hrd1}
 \end{equation}
We find it useful to set
\begin{eqnarray}
\g_{(i)}^{(0)}  & \triangleq  &
\begin{bmatrix}
  \g_{i}^{(0)}
 & \g_{m+i}^{(0)}
 & \g_{2m+i}^{(0)}
 & \dots & \g_{(d-1)m+i}^{(0)}
\end{bmatrix}^T \nonumber \\
\g_{(i)}^{(1)}  & \triangleq  &
\begin{bmatrix}
  \g_{i}^{(1)}
 & \g_{m+i}^{(1)}
 & \g_{2m+i}^{(1)}
 & \dots & \g_{(d-1)m+i}^{(1)}
\end{bmatrix}^T \nonumber \\
\z_{(i)} & \triangleq  &
\begin{bmatrix}
  \z_{i}
 & \z_{m+i}
 & \z_{2m+i}
 & \dots & \z_{(d-1)m+i}
\end{bmatrix}^T.
 \label{eq:hrd1a0}
 \end{eqnarray}
A combination of (\ref{eq:hrd1}) and (\ref{eq:hrd1a0}) then gives
\begin{eqnarray}
 f_{rd}(c,x;\cG)
\hspace{-.09in}  &  =  & \hspace{-.09in}
\frac{1}{dn}  \min_{\z} \max_{r_y>0}
\lp
        \sum_{i=1}^{m} \lp \|  \g_{(i)}^{(0)}   \|_2
   -
\|  \z_{(i)}   \|_2
   \rp^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2 r_y - \|\h^{(1)} \|_2 r r_y \rp
  \nonumber \\
\hspace{-.05in}  &  =  &\hspace{-.09in}
\frac{1}{dn}  \min_{\z} \max_{r_y>0}
\lp
        \sum_{i=1}^{m} \lp \|  \g_{(i)}^{(0)}   \|_2
   -
\|  \z_{(i)}   \|_2
   \rp^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2^2 r_y - \|\h^{(1)} \|_2^2 r^2 r_y \rp
  \nonumber \\
\hspace{-.05in}  &  \geq  &\hspace{-.09in}
\frac{1}{dn}  \max_{r_y>0} \min_{\z}
\lp
        \sum_{i=1}^{m} \lp \|  \g_{(i)}^{(0)}   \|_2
   -
\|  \z_{(i)}   \|_2
   \rp^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2^2 r_y - \|\h^{(1)} \|_2^2 r^2 r_y \rp
  \nonumber \\
\hspace{-.05in}   &  =   &\hspace{-.09in}
\frac{1}{dn}  \max_{r_y>0} \min_{\z_i}
 \lp
\sum_{i=1}^{m}
\lp \lp \|\g_{(i)}^{(0)}\|_2 - \|\z_{(i)}\|_2  \rp^2
  +\|\g_{(i)}^{(0)}x   +  \g_{(i)}^{(1)}r -\z_{(i)}\|_2^2 r_y \rp
  - \|\h^{(1)} \|_2^2 r^2 r_y \rp
    \nonumber \\
 \hspace{-.05in}  &  =   & \hspace{-.09in}
\frac{1}{dn}  \max_{r_y>0} \min_{\z_i}
 \lp
\sum_{i=1}^{m}
\lp \lp \|\g_{(i)}^{(0)}\|_2 - \|\z_{(i)}\|_2  \rp^2
  +\lp \| \g_{(i)}^{(0)}x   +  \g_{(i)}^{(1)}r \|_2  - \|\z_{(i)}\|_2   \rp^2 r_y \rp
  - \|\h^{(1)} \|_2^2 r^2 r_y \rp. \nonumber \\
\label{eq:hrd2}
 \end{eqnarray}
 The above optimization is structurally identical to the one given in (16) in \cite{Stojnicphretreal24}. One can then  repeat all the steps between (17) and (27) in \cite{Stojnicphretreal24}. Analogously to (20) in \cite{Stojnicphretreal24}, we first finds for the optimal $\|z_{(i)}\|_2$
\begin{eqnarray}
\|\hat{\z}_{(i)}\|_2= \frac{1}{1+r_y} \lp   \|\g_{(i)}^{(0)}\|_2 + \|\g_{(i)}^{(0)}x   +  \g_{(i)}^{(1)}r \|_2 r_y \rp.
\label{eq:hrd7a1}
 \end{eqnarray}
After setting
\begin{eqnarray}
f_q & \triangleq & \mE_{\cG}\lp \|\g_{(i)}^{(0)}\|_2 - \|\g_{(i)}^{(0)}x   +  \g_{(i)}^{(1)}r\|_2  \rp^2,
\label{eq:hrd7a2a0}
 \end{eqnarray}
one then analogously to (27) in \cite{Stojnicphretreal24} obtains
\begin{eqnarray}
 \phi_0 & \geq &
    \max_{r_y>0}
  \lp
  \frac{\alpha}{d}
\frac{r_y}{1+r_y} f_q
  -  r^2 r_y \rp.
\label{eq:hrd7a4}
 \end{eqnarray}
It is not necessarily relevant for what we consider here, but we do mention that (as in \cite{Stojnicphretreal24}) the inequality signs in (\ref{eq:hrd2}) and (\ref{eq:hrd7a4}) can trivially be replaced with equalities. After solving the residual optimization over $r_y$  one finally finds
\begin{eqnarray}
 \phi_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f_{rd}(\cG)
  \geq
\max\lp \sqrt{\frac{\alpha}{d} f_q}
  -  r,0\rp^2.
\label{eq:hrd7a7}
 \end{eqnarray}
(\ref{eq:hrd7a2a0})  and (\ref{eq:hrd7a7}) are basically sufficient to ultimately handle the random dual. From (\ref{eq:hrd7a2a0})we then have
\begin{eqnarray}
f_q & \triangleq & \mE_{\cG}\lp \|\g_{(i)}^{(0)}\|_2 - \|\g_{(i)}^{(0)}x   +  \g_{(i)}^{(1)}r\|_2  \rp^2
\nonumber \\
& = &
d(1+c) -2 \mE_{\cG}\lp \|\g_{(i)}^{(0)}\|_2 \|\g_{(i)}^{(0)}x   +  \g_{(i)}^{(1)}r\|_2  \rp
\nonumber \\
& = &
d(1+c) -2 \mE_{\cG}\lp \|\g_{(i)}^{(0)}\|_2 \| U\g_{(i)}^{(0)}x   +  U\g_{(i)}^{(1)}r\|_2  \rp
\nonumber \\
& = &
d(1+c) -2r \mE_{\cG}\lp \|\g_{(i)}^{(0)}\|_2 \left \| \frac{1}{r}\g_{(i)}^{(0,u)}x   +  \g_{(i)}^{(1)}\right \|_2  \rp,
\label{eq:hrd7a2a0a0}
 \end{eqnarray}
 where $U^TU=I$ and $U$ is such that
 \begin{eqnarray}
\g_{(i)}^{(0,u)} = U \g_{(i)}^{(0)}  & = &
\begin{bmatrix}
  \frac{\| \g_{(i)}^{(0)}  \|_2}{\sqrt{d}}
 &   \frac{\| \g_{(i)}^{(0)}  \|_2}{\sqrt{d}}
 &   \frac{\| \g_{(i)}^{(0)}  \|_2}{\sqrt{d}}
 & \dots
  &   \frac{\| \g_{(i)}^{(0)}  \|_2}{\sqrt{d}}
\end{bmatrix}^T.
  \label{eq:hrd7a2a0a1}
 \end{eqnarray}
Conditioned on $\| \g_{(i)}^{(0)}  \|_2$, $\| \frac{1}{r}\g_{(i)}^{(0,u)}x   +  \g_{(i)}^{(1)}\|_2$ is a non-central chi distributed random variable with $d$ degrees of freedom and the mean of each of the $d$ constituting iid Gaussians $\mu=\frac{\| \g_{(i)}^{(0)}  \|_2 x }{r\sqrt{d}}$. One then sets
\begin{eqnarray}
\lambda_d = \mu\sqrt{d},   \label{eq:hrd7a2a0a32}
 \end{eqnarray}
 and finds
\begin{eqnarray}
  \mE_{\g_{(i)}^{(1)}}  \left \| \mu   +  \g_{(i)}^{(1)}\right \|_2
  = L_{\frac{1}{2}}^{\frac{d}{2}-1} \lp -\frac{\lambda_d^2}{2}\rp,
   \label{eq:hrd7a2a0a3}
 \end{eqnarray}
where $L_{\frac{1}{2}}^{\frac{d}{2}-1} (\cdot)$ is a Laguerre function. As $u=\| \g_{(i)}^{(0)}  \|_2$ itself is a central chi square distributed with $d$ degrees of freedom, one has for its pdf
\begin{eqnarray}
 p(u) = \frac{u^{d-1} e^{-\frac{x^2}{2}}}{2^{\frac{d}{2}-1 }  \Gamma\lp\frac{d}{2}\rp }, u\geq 0.
   \label{eq:hrd7a2a0a4}
 \end{eqnarray}
A combination of (\ref{eq:hrd7a2a0a0}), (\ref{eq:hrd7a2a0a3}), and (\ref{eq:hrd7a2a0a4}) then gives
\begin{eqnarray}
f_q
& = &
d(1+c) -2r \mE_{\cG}\lp \|\g_{(i)}^{(0)}\|_2 \left \| \frac{1}{r}\g_{(i)}^{(0,u)}x   +  \g_{(i)}^{(1)}\right \|_2  \rp
\nonumber \\
& = &
d(1+c) -2r \mE_{\|\g_{(i)}^{(0)}\|_2 }  \lp \|\g_{(i)}^{(0)}\|_2
\mE_{\|\g_{(i)}^{(1)}\|_2 }
 \left \| \frac{1}{r}\g_{(i)}^{(0,u)}x   +  \g_{(i)}^{(1)}\right \|_2  \rp\nonumber \\
& = &
d(1+c) -2r \mE_{\|\g_{(i)}^{(0)}\|_2 }  \lp \|\g_{(i)}^{(0)}\|_2
\mE_{\|\g_{(i)}^{(1)}\|_2 }
 \left \| \mu   +  \g_{(i)}^{(1)}\right \|_2  \rp
 \nonumber\\
 & = &
d(1+c) -2r \mE_{\|\g_{(i)}^{(0)}\|_2 }  \lp \|\g_{(i)}^{(0)}\|_2
 L_{\frac{1}{2}}^{\frac{d}{2}-1} \lp -\frac{\lambda_d^2}{2}\rp \rp
  \nonumber\\
 & = &
d(1+c) -2r \mE_{\|\g_{(i)}^{(0)}\|_2 }  \lp \|\g_{(i)}^{(0)}\|_2
 L_{\frac{1}{2}}^{\frac{d}{2}-1} \lp -\frac{\| \g_{(i)}^{(0)}  \|_2^2 x^2 }{2r^2} \rp \rp
   \nonumber\\
 & = &
d(1+c) -2r \int_{0}^{\infty}
u L_{\frac{1}{2}}^{\frac{d}{2}-1} \lp -\frac{u^2 x^2 }{2r^2} \rp
 \frac{u^{d-1} e^{-\frac{x^2}{2}}}{2^{\frac{d}{2}-1 }  \Gamma\lp\frac{d}{2}\rp }du.
\label{eq:hrd7a2a0a5}
 \end{eqnarray}
The elegance and simplicity of the numerical evaluations depends on $d$. For the concreteness we take $d=2$ as it corresponds to a direct emulation of the complex phase retrieval. Then for $x_{\lambda} =\frac{\lambda_d^2}{2}$ the above has a bit more convenient form
\begin{eqnarray}
f_q
& = &
 2(1+c) -2r \int_{0}^{\infty}
u L_{\frac{1}{2}}^{0} \lp -\frac{u^2 x^2 }{2r^2} \rp
 u e^{-\frac{u^2}{2}}du
\nonumber \\
 & = &
 2(1+c) -2r \int_{0}^{\infty}
u
\sqrt{\frac{\pi}{2}} \lp (x_{\lambda}+1) \cI_0 \lp \frac{x_{\lambda}}{2} \rp  +x_{\lambda} \cI_1 \lp \frac{x_{\lambda}}{2}\rp  \rp  e^{-\frac{x_{\lambda}}{2}}
 u e^{-\frac{u^2}{2}}du
 \nonumber \\
 & = &
 2(1+c) -2r \int_{0}^{\infty}
u
\sqrt{\frac{\pi}{2}} \lp \lp \frac{u^2 x^2 }{2r^2} +1 \rp \cI_0 \lp \frac{u^2 x^2 }{4r^2}  \rp  + \frac{u^2 x^2 }{2r^2}  \cI_1 \lp \frac{u^2 x^2 }{4r^2}  \rp  \rp  e^{-\frac{u^2 x^2 }{4r^2}   }
 u e^{-\frac{u^2}{2}}du,
\label{eq:hrd7a2a0a6}
 \end{eqnarray}
where $\cI_0(\cdot)$ and $\cI_1(\cdot)$ are  modified Bessel functions of the first kind. Plugging the value from (\ref{eq:hrd7a2a0a6}) in (\ref{eq:hrd7a7}) completes handling of the random dual for $d=2$. For different $d$ one can proceed with similar numerical evaluations. Since the analytical expression  similar to the ones given in (\ref{eq:hrd7a2a0a6}) get a bit more cumbersome as $d$ increases we skip stating them explicitly but do mention that the underlying numerical evaluations can be done without much of a problem.

%\begin{equation}\label{eq:hrd7a2a0a7}
%  p(u,d;\lambda_d)= \frac{ e^{-\frac{u^2+\lambda_d^2}{2}} u^d\lambda_d  } { (\lambda_d u)^{\frac{d}{2}} }
%   \cI_{\frac{d}{2}-1} \lp \lambda_d u  \rp
%\end{equation}



  \vspace{.1in}
\noindent \underline{4) \textbf{\emph{Double checking the strong random duality:}}}   The last step of the RDT machinery assumes double checking whether the strong random duality holds. As in \cite{Stojnicphretreal24},  a lack of deterministic strong duality does not allow for a utilization of the reversal considerations from \cite{StojnicRegRndDlt10}  and the strong random duality is not in place. This practically  implies that the above results are strict lower bounds on the fd-pro's scaled objective, $\xi(c,x)$ .










