	\end{pmatrix}
	\right)
\]
and hence the bound
	\begin{eqnarray*}
		\|	D[\Omega_{A_i}](\mathbf X,\mathbf y) \mathbf u\|_2 &\ge&  
		\left\|
{ \scriptsize	\begin{pmatrix}
	\Delta^{(0)} \\
		& \Delta^{(1)} \\
\end{pmatrix} 
	\left(
	\begin{pmatrix}
		\mathbf 0 & C_i^{(0)} \\
		B_i^{(1)}& C_i^{(1)} \\
	\end{pmatrix} 
\begin{pmatrix}	\diag{\mathbf X}^{-1} & \\ & I \end{pmatrix} \mathbf u
		-t 
	\begin{pmatrix}
		\mathbf 1\\
		\mathbf 1
	\end{pmatrix}
		\right)}
	\right\|_{\infty}
		\\
	&\ge&
		\left\|
{ \scriptsize	\begin{pmatrix}
	\Delta^{(0)} \\
		& \Delta^{(1)} \\
\end{pmatrix} 
	\left(
	\begin{pmatrix}
