As in the proof of \eqref{metric1}, we fix $i$ so that 
the maximum in
Definition \eqref{JTI} is attained. Then,
$\finsler{\mathbf u}{\Omega(\mathbf X,\mathbf y)} \ge \| D[\Omega_{A_i}](\mathbf X,\mathbf y)\mathbf u\|$. 
As before,
\begin{equation}\label{lower-partial1}
\finsler{\mathbf u}{\Omega(\mathbf X,\mathbf y)} 
	\ge 
		\frac{\lambda_{\omega}}{\max_i \sqrt{8 \#A_i}\, e^{\ell_i(\mathbf y)+\ell_i(-\mathbf y)}}
	\finsler{\mathbf u}{\omega} - h \nu_{\omega} \finsler{\mathbf u}{\omega} - h |t| .
\end{equation}

Let  $s_i = \sqrt{\frac{\# A_i}{\#A_i^{(0)}}}$. 
We claim that 
\begin{equation}\label{momentumbound}
	|t(\mathbf X,\mathbf y)| \le (1+hs_i e^{2\ell_i(\mathbf y)}) \nu_{\omega} \finsler{\mathbf u}{\omega}. 
\end{equation}
and
\begin{equation}\label{momentumbound2}
	|t(\mathbf X,\mathbf 0)| \le 2hs_i \nu_{\omega} \finsler{\mathbf u}{\omega}. 
\end{equation}

Indeed, write $t=t'+t''$
\[
	t'= \frac{ \sum_{c \in C_i^{(0)}} e^{2 \mathbf c \Re(\mathbf y)} \mathbf c \mathbf u_2}
{\sum_{(\mathbf b,\mathbf c)\in A_i} |\mathbf X|^{2\mathbf b} e^{2\mathbf c\Re(\mathbf y)} }
\]
and
\[
t''=
\frac{ \sum_{(\mathbf b,\mathbf c) \in A_i^{(1)} \cup A_i^{(2)} \cup \dots} |\mathbf X|^{2\mathbf b} e^{2\mathbf c\Re(\mathbf y)} (\mathbf b \mathbf X^{-1} \mathbf u_1 + \mathbf c \mathbf u_2)}
{\sum_{(\mathbf b,\mathbf c)\in A_i} |\mathbf X|^{2\mathbf b} e^{2\mathbf c\Re(\mathbf y)} }
\]
The first term can be bounded by noticing that
\[
|t'| \le 
	\left| \frac{ \sum_{\mathbf c \in C_i^{(0)}} e^{2 \mathbf c \Re(\mathbf y)} \mathbf c \mathbf u_2}
{\sum_{\mathbf c\in C_i^{(0)}} e^{2\mathbf c\Re(\mathbf y)} }
	\right|
\]
and the expression inside the absolute value is a convex linear combination of the $\mathbf c \mathbf u_2$. 
If $\mathbf y = 0$, Definition \ref{normal-form}(c) implies that $t'=0$. Unconditionally,
$|t'| \le \nu_{\omega} \finsler{\mathbf u}{\omega}$. The second term
is more challenging. 

The denominator of $t''$ is not smaller than
\[
	\sum_{\mathbf c\in C_i^{(0)}} e^{2\mathbf c\Re(\mathbf y)} \ge \sqrt{\#A_i^{(0)}} 
	\sum_{\mathbf c\in C_i^{(0)}} \frac{ \exp(2\mathbf c\Re(\mathbf y))} {\sqrt{\#A_i^{(0)}}}
.
\]
Combining Jensen's inequality and Definition~\ref{normal-form}(c),
\[
\sum_{\mathbf c\in C_i^{0}} e^{2\mathbf c\Re(\mathbf y)} \ge 
\sqrt{\#A_i^{(0)}} \exp\left(
\sum_{\mathbf c\in C_i^{0}} 
\frac{ 2\mathbf c\Re(\mathbf y)
	}{\sqrt{\#A_i^{(0)}}}
	\right)
= \sqrt{\#A_i^{(0)}} \ .
\]
All the terms in the numerator of $t''$ are multiple of $|X_j| \le h < 1$, so
\[
	|t''| \le \frac{\sqrt {\#A_i}}{
		\sqrt{\#A_i^{(0)}}} h \max_{\mathbf b,\mathbf c} e^{2\mathbf c\Re(\mathbf y)} \left|\strut\mathbf b\, |\mathbf u_1| + \mathbf c \mathbf u_2\right|
	\le h s_i e^{2 \ell_i(\mathbf y)} \nu_{\omega} 
	\finsler{\strut(|\mathbf u_1|,\mathbf u_2)}{\omega}
\]
where the absolute value of $|\mathbf u_1|$ is meant coordinatewise.
Definition \ref{normal-form}(a) and Lemma \ref{lem-Li} imply that for all $i$,
$ \|(|\mathbf u_1|,\mathbf u_2)\|_{i,\omega} = \| (\mathbf u_1, \mathbf u_2)\|_{i,\omega}$.
The same holds therefore for the Finsler norm.
This establishes bounds \eqref{momentumbound} and \eqref{momentumbound2}.
\medskip
\par
Plugging \eqref{momentumbound} into \eqref{lower-partial1}, we recover
that
\begin{equation}\label{lower-partial2a}
\finsler{
	\mathbf u}{\Omega(\mathbf X,\mathbf y)} \ge 
\left( \frac{\lambda_{\omega}}{\sqrt{8\#A_i}\, e^{\ell_i(\mathbf y)+\ell_i(-\mathbf y)}}
	-h (2+hs_ie^{2\ell_i(\mathbf y)}) \nu_{\omega}\right) \finsler{\mathbf u}{\omega}.
\end{equation}
This expression simplifies after introducing \eqref{h-bound}.
Because of remark~\ref{lambda-nu}, $h s_i e^{\ell_i(\mathbf y)} \le \frac{\lambda_{\omega} s_i}{8 \nu_{\omega} \sqrt{\#A_i}}
\le \frac{1}{4\sqrt{\# A_i}} \le \frac{1}{4}$
\begin{equation}\label{lower-partial2}
\finsler{
	\mathbf u}{\Omega(\mathbf X,\mathbf y)}  \ge 
	\frac{ 
	\lambda_{\omega}}
{14\sqrt{\#A_i}\, e^{\ell_i(y)+\ell_i(-y)}}
\finsler{\mathbf u}{\omega}.
\end{equation}

\end{proof}

\subsection{The condition number bound}\label{proof-condition-bound}

\begin{proof}[Proof of Theorem~\ref{cost-of-renorm-legacy}]
	Since $	 V_{\mathbf A}(\mathbf z)$ is a root of $\mathbf f$, $\mathbf 0$ is a root 
	of $\mathbf f \cdot R(\mathbf 0, \mathbf y)$ and
	\[
		\mu(\mathbf f R(\mathbf z), \mathbf 0)^{-1} =
		\inf_{\mathbf u \ne 0}
		\frac{1}{\|\mathbf u\|_0}
		\left\|
		\diag{\frac{1}{\|f_i R_i(\mathbf z)\| \|V_{A_i}(\mathbf 0)\|}}
	\begin{pmatrix}
		\vdots\\
		f_i R_i(\mathbf z) DV_{A_i}(\mathbf 0) \mathbf u \\
		\vdots
	\end{pmatrix}
		\right\|
	.
\]
	Assume that the infimum is attained at a certain $\mathbf u_*$.
Then,
\begin{eqnarray*}
	\mu(
	\mathbf f , V_{\mathbf A}(\mathbf z))^{-1} 
		&=&
	\inf_{\mathbf w \ne 0}
	\frac{1}{\|\mathbf w\|_{\mathbf z}}
	\left\|
	\diag{\frac{1}{\|f_i \| \|V_{A_i}(\mathbf z)\|}}
	\begin{pmatrix}
		\vdots\\
		f_i DV_{A_i}(\mathbf z) \mathbf w \\
		\vdots
	\end{pmatrix}
		\right\|
		\\
&\le&
	\frac{1}{\|\mathbf u_*\|_{\mathbf z}}
	\left\|
		\diag{\frac{1}{\|f_i \| \|V_{A_i}(\mathbf z)\|}}
	\begin{pmatrix}
		\vdots\\
		f_i DV_{A_i}(\mathbf z) \mathbf u_* \\
		\vdots
	\end{pmatrix}
		\right\|
\end{eqnarray*}
We notice that
	\[
		f_i DV_{A_i}(\mathbf z)= f_i \diag{V_{A_i}(\mathbf z)} A_i = 
	(f_i R_i(\mathbf z) ) \diag{\mathbf 1} A_i =f_i R_i(\mathbf z) DV_{A_i}(\mathbf 0)
.\]
Hence,
\[
	\mu(\mathbf f, V_A(\mathbf z))^{-1} \le 
\frac {\|\mathbf u_*\|_{\mathbf 0}}
	{\|\mathbf u_*\|_{\mathbf z}}
		\max_i \left(\frac
	{\|f_i R_i(\mathbf z)\| \|V_{A_i}(\mathbf 0)\|}
	{\|f_i\| \|V_{A_i}(\mathbf z)\|}
	\right)
	\mu(\mathbf f R(\mathbf z), V_{\mathbf A}(\mathbf 0))^{-1} 
.\]
This is the same as
\[
	\mu(\mathbf f R(\mathbf z), V_{\mathbf A}(\mathbf 0))\le
\frac {\|\mathbf u_*\|_{\mathbf 0}}
	{\|\mathbf u_*\|_{\mathbf z}}
		\max_i \left(\frac
	{\|f_i R_i(\mathbf z)\| \|V_{A_i}(\mathbf 0)\|}
	{\|f_i\| \|V_{A_i}(\mathbf z)\|}
	\right)
	\mu(\mathbf f, V_A(\mathbf z)) .
\]
By the construction of $\ell_i$,
$\| f_i R_i(\mathbf z) \| \le e^{\ell_i(\mathbf z)} \|f_i\|$ and
$\| V_{A_i}(\mathbf 0) \| \le e^{\ell_i(-\mathbf z)} \|V_{A_i}(\mathbf z)\|$.

The ratio
\[
\frac {\|\mathbf u_*\|_{\mathbf 0}}
{\|\mathbf u_*\|_{\mathbf z}}
\le
\sqrt{n} \frac{\sqrt{8 \# A_i}}{\lambda_{\mathbf 0}}
\]
follows directly from \eqref{metric1}. The square root of $n$ goes away if we replace the usual operator
norm by a Finsler operator norm in the definition of the condition $\mu$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{cost-of-renorm}]
Since $	 \Omega(\mathbf X,\mathbf 0)$ is a root of $\mathbf f R(\mathbf 0, \mathbf y)$,
	\[
	\begin{split}
		\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}^{-1}  
		& =
\\
		\inf_{\mathbf u \ne 0}
		\frac{1}{\|\mathbf u\|_{\omega}}&
	\left\|
		\diag{\frac{1}{\|f_i R_i(\mathbf 0,\mathbf y)\| \|\omega_i\|}}
	\begin{pmatrix}
		\vdots\\
		f_i R_i(\mathbf 0,\mathbf y) D\Omega_{A_i}(\mathbf X,\mathbf 0) \mathbf u \\
		\vdots
	\end{pmatrix}
		\right\|
	\end{split}.
\]
	Assume that the infimum is attained at a certain $\mathbf u_*$.
Then,
\begin{eqnarray*}
	\mu(
	\mathbf f , \Omega(\mathbf X,\mathbf y))^{-1} 
		&=&
	\inf_{\mathbf w \ne 0}
	\frac{1}{\|\mathbf w\|_{\Omega(\mathbf X,\mathbf y)}}
	\left\|
	\diag{\frac{1}{\|f_i \| \|\Omega_{A_i}(\mathbf X,\mathbf y)\|}}
	\begin{pmatrix}
		\vdots\\
		f_i D\Omega_{A_i}(\mathbf X, \mathbf y) \mathbf w \\
		\vdots
	\end{pmatrix}
		\right\|
		\\
&\le&
	\frac{1}{\|\mathbf u_*\|_{\Omega(\mathbf X,\mathbf y)}}
	\left\|
		\diag{\frac{1}{\|f_i \| \|\Omega_{A_i}(\mathbf X,\mathbf y)\|}}
	\begin{pmatrix}
		\vdots\\
		f_i D\Omega_{A_i}(\mathbf X,\mathbf y) \mathbf u_* \\
		\vdots
	\end{pmatrix}
		\right\|
\end{eqnarray*}
As before, 
	\[
f_i D\Omega_{A_i}(\mathbf X,\mathbf y)=
\sum_{\mathbf a = (\mathbf b\, \mathbf c) \in A_i} 
	f_{i \mathbf a} X^{\mathbf b} e^{\mathbf c\mathbf y} (\mathbf b\, \diag{X_i^{-1}}, \mathbf c ) 
=
f_i R_i(\mathbf 0,\mathbf y) D\Omega_{A_i}(\mathbf X,\mathbf 0) 
.\]
Hence,
\[
\mu(\mathbf f, \Omega(\mathbf X,\mathbf y))^{-1} \le 
\frac {\|\mathbf u_*\|_{\omega}}
	{\|\mathbf u_*\|_{\Omega(\mathbf X,\mathbf y)}}
		\max_i \left(\frac
	{\|f_i R_i(\mathbf 0,\mathbf y)\| \|\omega_i\|}
	{\|f_i\| \|\Omega_{A_i}(\mathbf X,\mathbf y)\|}
	\right)
		\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}^{-1}  
.\]
This is the same as
\[
\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}  
\le 
\frac {\|\mathbf u_*\|_{\omega}}
	{\|\mathbf u_*\|_{\Omega(\mathbf X,\mathbf y)}}
\max_i \left(\frac
	{\|f_i R_i(\mathbf y)\| \|\omega_i\|}
	{\|f_i\| \|\Omega_{A_i}(\mathbf X,\mathbf y)\|}
	\right)
\mu(\mathbf f, \Omega(\mathbf X,\mathbf y))
.
\]
By definition, $\| f_i R_i(\mathbf 0,\mathbf y) \| \le e^{\ell_i(\mathbf y)} \|f_i\|$. For all $\mathbf a = (\mathbf b\, \mathbf c) \in A_i$, 
\[
	|\mathbf X^{\mathbf b}| = |\mathbf X^{\mathbf b} e^{\mathbf c\mathbf y} e^{-\mathbf c\mathbf y}| \le |\mathbf X^{\mathbf b} e^{\mathbf c} e^{\ell_i(-\mathbf y)}|
\]
so
\[
\max{\frac
	{\|f_i R_i(\mathbf y)\| \|\Omega_{A_i}(\mathbf X,\mathbf 0)\|}
	{\|f_i\| \|\Omega_{A_i}(\mathbf X,\mathbf y)\|}
	}
\le e^{\max \ell_i(\mathbf y)+\ell_i(-\mathbf y)}.
\]
The ratio
\[
\frac {\|\mathbf u_*\|_{\omega}}
{\|\mathbf u_*\|_{\Omega(\mathbf X,\mathbf y)}}
\le
\sqrt{n} 
\frac {\finsler{\mathbf u_*}{\omega}}
{\finsler{\mathbf u_*}{\Omega(\mathbf X,\mathbf y)}}
\]
is bounded by \eqref{metric2}.
\end{proof}

\section{Higher Derivative Estimate at toric infinity}
\label{sec:higher}

The analysis of Newton iteration based homotopy algorithms requires a
criterion of quadratic convergence for the iteration, such as the
$\beta \gamma \le \alpha_0$ criterion from Smale's alpha-theory. As explained
by \ocite{BCSS}*{Section 14.2}, this criterion can be checked by 
bounding the gamma invariant in terms of the condition number. 
This idea was generalized to the realm of sparse polynomials  
in Theorem~\toricI{3.6.1}. Unfortunately, the bound in that
theorem depends from the $\nu$ invariant. Therefore, it is not sharp
 near toric infinity. This section will provide a criterion for
 quadratic convergence near toric infinity.


Assume that the tuple $\mathbf A=(A_1, \dots, A_n)$ satisfies Hypothesis~\ref{NDIH}, in particular it is in normal form.
In the previous section, we associated to each $\mathbf {\bar y}$
a `local' map at toric infinity, viz.
\begin{equation}\label{ersatz}
	\defun{\mathbf Q}{T_{\boldsymbol \omega}\mathscr V_{\mathbf A}}{\mathbb C^n}
	{(\mathbf X,\mathbf y)}{
\begin{pmatrix}
	\frac{1}{\|\omega_1\|\|f_1 \cdot R_1(\mathbf 0, \mathbf{\bar y})\|} f_1  \cdot R_1(\mathbf 0, \mathbf{\bar y})\cdot \Omega_{A_1}(\mathbf X,\mathbf y)
\\
\vdots \\
	\frac{1}{\|\omega_n\|\|f_n \cdot R_n(\mathbf 0, \mathbf{\bar y})\|} f_n \cdot R_n(\mathbf 0, \mathbf{\bar y}) \cdot \Omega_{A_n}(\mathbf X,\mathbf y)
\end{pmatrix}
	.}
\end{equation}
To simplify notations, we write $\mathbf q=\mathbf f \cdot R(\mathbf 0, \mathbf{\bar y})$
so that
\[
	\mathbf Q(\mathbf X,\mathbf y)= \begin{pmatrix}
	\frac{1}{\|\omega_1\|\|q_1\|} q_1 \Omega_{A_1}(\mathbf X,\mathbf y)
\\
\vdots \\
	\frac{1}{\|\omega_n\|\|q_n\|} q_n \Omega_{A_n}(\mathbf X,\mathbf y)
\end{pmatrix}
\]


This map vanishes at $(\mathbf X, \mathbf y)$ if and only if $\Omega(\mathbf X, \mathbf{\bar y}+\mathbf y)$
is a `toric' zero for the system $\mathbf f$.
Newton iteration of $\mathbf Q$ is defined as usual by
\begin{equation}\label{Newton-ersatz}
	\defun{N(\mathbf Q, \cdot)}
	{T_{\boldsymbol \omega}\mathscr V_{\mathbf A}}
	{T_{\boldsymbol \omega}\mathscr V_{\mathbf A}}
	{(\mathbf X,\mathbf y)}{
		N( \mathbf Q, (\mathbf X, \mathbf y)) 
		= (\mathbf X, \mathbf y) - D\mathbf Q(\mathbf X,\mathbf y)^{-1} \mathbf Q(\mathbf X, \mathbf y).}
\end{equation}


A sufficient condition for the quadratic convergence of the
Newton iterates 
\begin{equation}\label{Newton-infinity}
\left\{
	\begin{array}{lcl}
		(\mathbf X_{t+1}, \mathbf y_{t+1}) &=& N( \mathbf Q, (\mathbf X_t, \mathbf y_t)) 
		,\hspace{2em} t=0, 1, \dots
	\\
		(\mathbf X_0, \mathbf y_0)&=&(\mathbf {\bar X},\mathbf 0), 
	\end{array} \right.
\end{equation}
will be given below. It implies that the sequence converges 
to a zero $(\tilde {\mathbf X},\tilde {\mathbf y}) \in T_{\boldsymbol \omega}\mathscr V_{\mathbf A}$
for $\mathbf Q$, and hence $\Omega_{\mathbf A}(\tilde{\mathbf X},\bar {\mathbf y}+\tilde{\mathbf y})$ is a toric zero
for $\mathbf f$.
The criterion follows from 
Smale's alpha theory applied to the local map $\mathbf Q$. All metric estimates, including the
definition of the $\gamma$ invariant, assume the Hermitian (resp. Finsler) metric of
$T_{\boldsymbol \omega}\mathscr V_{\mathbf A}$. In coordinates,
\[
	\langle \mathbf u, \mathbf w \rangle_{\boldsymbol \omega} = 
	\left(D\boldsymbol \Omega_{\mathbf A}(\mathbf 0,\mathbf 0) 
	\mathbf w\right)^* 
	\diag{\|\omega_i\|^{-2}}
	D\boldsymbol \Omega_{\mathbf A}
	(\mathbf 0,\mathbf 0) \mathbf u
\]
and
\[
	\finsler{\mathbf u}{\omega} = \max \left \| \frac{1}{\|\omega_i\|} D\Omega_{A_i}(0,0) \mathbf u \right \|
\]
\begin{remark}\label{finsler}
All results in this section assume the Hermitian metric of $T_{\boldsymbol \omega}\mathscr V_{\mathbf A}$. Using the
Finsler metric produces sharper results, but I know no efficient way to compute operator norms with respect
to a Finsler structure. 
\end{remark}
Recall the notations $s_i = \sqrt{\#A_i / \#A_i^{(0)}}$.
\begin{theorem}[Higher derivative estimate]\label{th-higher}
	Assume that the tuple $\mathbf A$ satisfies Hypothesis~\ref{NDIH} with splitting $\mathbb R^l \times \mathbb R^{n-l}$.
	Let $\mathbf f$, $\mathbf{\bar y}$ and $\mathbf Q$ be defined
	as above. If $|X_k|<h<1$ for $1\le l \le k$, then
\[
\gamma(\mathbf Q,(\mathbf X,\mathbf 0)) \le
	\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1} \|_{\omega} 
	\frac{\nu_{\mathbf \omega} \sqrt{\sum_i s_i^2}  }{(1-h)^3}
.
\]
\end{theorem}

Smale's alpha-theorem yields:

\begin{corollary}\label{cor-quadratic}
	Let $0<h<1$ and 
	\begin{equation}\label{c-star}
	c_* \ge  
	\frac{\nu_{\mathbf \omega} \sqrt{\sum_i s_i^2}  }{(1-h)^3}.
\end{equation}
	Define $\beta_t = \| (\mathbf X_{t+1}, \mathbf y_{t+1}) - (\mathbf X_t, \mathbf y_t) \|_{\omega}$
	and
	\[
	\bar \mu
	= 
	\|D\mathbf Q(\mathbf X,\mathbf 0)^{-1} \|_{\omega}
	\,
	\]
Let \[
\alpha 
\le
\alpha_0 = \frac{13 - 3 \sqrt{17}}{4},
\]
\[
	r_0 = \changed{r_0(\alpha)=}
\frac{1+\alpha-\sqrt{1-6\alpha+\alpha^2}}{4\alpha} 
\text{ and }
	r_1 =\changed{r_1(\alpha)=}
\frac{1-3\alpha-\sqrt{1-6\alpha+\alpha^2}}{4\alpha} 
.
\]
	If $c_* \beta_0 \bar \mu \le \alpha$, then the sequence $(\mathbf X_y, \mathbf y_t)$ from 
	\eqref{Newton-infinity}
	is well-defined and converges to a zero $(\tilde{\mathbf X}, \tilde{\mathbf y})$ of $\mathbf Q$.
	Moreover,
\begin{enumerate}[(a)]
\item
$
		\| (\mathbf X_t, \mathbf y_t) - (\tilde{\mathbf X}, \mathbf {\tilde y}) \|_{\omega}
	\le 2^{-2^i+1} \beta_0
$
\item 
$
		\| (\tilde{\mathbf X}, \tilde{\mathbf y})-(\mathbf{\bar X}, \mathbf 0) \|_{\omega} \le r_0 \beta_0
$
\item
$
		\| (\tilde{\mathbf X}, \tilde{\mathbf y}) - (\mathbf X_1,\mathbf y_1)\|_{\omega} \le r_1 \beta_0
$
\end{enumerate}
\end{corollary}
It follows from the construction of $\mathbf Q$ that $\boldsymbol \Omega_{\mathbf A}(\tilde{\mathbf X}, \mathbf{\bar y}+\tilde{\mathbf{y}})$
is a toric zero of $\mathbf f$.

\subsection{The $p$-th derivative of $\Omega_{A_i}$}

Towards the proof of Theorem~\ref{th-higher},
we want to estimate 
$\frac{1}{p!}\|D^p\boldsymbol \Omega_{\mathbf A}(\mathbf 0,\mathbf 0)\|$, 
and then $\frac{1}{p!}\|D^p\boldsymbol \Omega_{\mathbf A}(\mathbf X,\mathbf 0)\|$. 


\begin{lemma}\label{coord}
	If $\finsler{\mathbf u}{\omega} \le 1$ and $j \le l$, then for all $i$ with $u_j \in B_i^{(1)}$,  
	$|u_j| \le \nu_{i,\omega}$.
	If Hypothesis \ref{NDIH} holds, then
	$|u_j| \le \min \nu_{i,\omega}$ where the minimum is taken over
	all $i$ with $\mathrm e_j \in B_i^{(1)}$ and is always attained, so 
	$|u_j| \le \nu_{\omega}$.
\end{lemma}
\begin{proof}
 	Write $\mathbf u = \begin{pmatrix}\mathbf u'\\ \mathbf u''\end{pmatrix}$ with $\mathbf u' \in \mathbb R^l$. Because of
		\eqref{Li}, 
 	\[
		\finsler{\begin{pmatrix}\mathbf u'\\\mathbf 0\end{pmatrix}}{\omega} \le 1. 
 	\]
	Suppose that 
	$\mathrm e_j \in B_i^{(1)}$. There is $\mathbf c \in C_i^{(1)}$ be such that
	$(\mathrm e_j \ \mathbf c) \in A_i^{(1)}$,
 \[
 	|u_j| = \left|(\mathrm e_j \ \mathbf c)  \begin{pmatrix}\mathbf u'\\0\end{pmatrix} \right| 
 \le
 \nu_{i,\omega}	.
 \]
	Hypothesis \ref{NDIH} implies that the matrix $L$ from \eqref{Li} has full rank. Thus, there is at least one pair $(i,j)$ 
	with $\mathrm e_j \in B_i^{(1)}$.
\end{proof}
\begin{lemma} \label{coord-c}
	Suppose that $(\mathbf b\, \mathbf c) \in A_i$ for some $i$. Then
	\[
		|(\mathbf 0,\mathbf c) \mathbf u| \le \nu_{i,\omega} \|\mathbf u\|_{i,\omega} 
		\le \nu_{\omega} \finsler{\mathbf u}{\omega}
.	\]

\end{lemma}
\begin{proof}
 	As before, write $\mathbf u = \begin{pmatrix}\mathbf u'\\ \mathbf u''\end{pmatrix}$ with $\mathbf u' \in \mathbb R^k$. From the
 block structure of each $L_i$, 
 	\[
		\left \|\begin{pmatrix}\mathbf 0\\\mathbf u''\end{pmatrix}
			\right\|
			_{i,\omega}
			\le \|\mathbf u\|_{i,\omega}. 
 	\]
	Then $|(\mathbf 0,\mathbf c) \mathbf u| = |(\mathbf b,\mathbf c) \mathbf u| \le \nu_{i,\omega} \|\mathbf u\|_{i,\omega}$.
\end{proof}
\begin{lemma}\label{lemma-high-1} Assume Hypothesis \ref{NDIH}.
	Let $p \ge 2$. 
	If $\finsler{\mathbf u_1}{\omega}, \dots, \finsler{\mathbf u_p}{\omega} \le 1$, then
\[
 	\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
 	\le \nu_{\omega}^{p-1} 
	\sqrt{\# A_i}.
\]
If one further assumes that for each $1\le i \le l$, $\mathbf u_i = \begin{pmatrix}
	\mathbf u_i' \\ \mathbf 0
\end{pmatrix}$ with each coordinate of $\mathbf u_i'$ of absolute value less than $h$, 
then 
\[
\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
\le
	h^l \sqrt{\# A_i} \nu_{\omega}^{p-l}
.
\]
\end{lemma}

\begin{proof} We prove the general case first.
First assume that $j_1 \le j_2 \le \dots \le j_n$ is
	given, and let $(\mathbf b, \mathbf c)$ satisfy: 
	\begin{equation}\label{bcj}
	\mathbf X^{\mathbf b} e^{\mathbf c\mathbf y}
=
	X_{j_1} X_{j_2} \dots X_{j_k} 
	e^{y_{j_{k+1}} + \dots + y_{j_n}} 
.
\end{equation}
If $p<|\mathbf b|$, 
\[
	\frac{1}{p!} D^p_{|\mathbf X=\mathbf 0, \mathbf y=\mathbf 0} \mathbf X^{\mathbf b} e^{\mathbf c\mathbf y} (\mathbf u_1, \dots, \mathbf u_p) =
0
\]
If $p\ge|\mathbf b|$, we can write
\[
\begin{split}
	\frac{1}{p!} D^p_{|\mathbf X=\mathbf 0, \mathbf y=\mathbf 0} & \mathbf X^{\mathbf b} e^{\mathbf c\mathbf y} (\mathbf u_1, \dots, \mathbf u_p) =
\\
	=&	\frac{1}{p!}\sum_{\sigma \in S_p} 
	(\mathbf u_{\sigma(1)})_{j_1}
\dots
(\mathbf u_{\sigma(k)})_{j_k}
	(\mathbf 0\  \mathbf c)\mathbf u_{\sigma(k+1)}
\dots
	(\mathbf 0\ \mathbf c)\mathbf u_{\sigma(p)}
.
\end{split}
\]
By triangular inequality
	\begin{equation}\label{Dp1}\begin{split}
	\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
	\le \hspace{-12em} & 
\\
	&\le 
\frac{1}{p!}
\sum_{\sigma \in S_p}
\left\|
\begin{pmatrix}
	\vdots \\
	(\mathbf u_{\sigma(1)})_{j_1}
\dots
(\mathbf u_{\sigma(k)})_{j_k}
	(\mathbf 0\  \mathbf c)\mathbf u_{\sigma(k+1)}
\dots
	(\mathbf 0\ \mathbf c)\mathbf u_{\sigma(p)}
\\
	\vdots
\end{pmatrix}_{(\mathbf b\, \mathbf c) \in A_i}
\right\|
	\end{split}
\end{equation}
        Lemma~\ref{coord} bounds $|u_j|\le \nu_{\omega}$, $j \le l$, while
	Lemma~\ref{coord-c} bounds $|(\mathbf 0,\mathbf c) \mathbf u| \le \nu_{i,\omega}$.
	Hence,

	\begin{eqnarray*}
\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
	\le \hspace{-12em} & &
\\
&\le &
\frac{1}{p!}
\sum_{\sigma \in S_p}
\left\|
\begin{matrix}
\begin{pmatrix}\vdots \\
	\nu_{i,\omega}^{p-1}
	(\mathbf 0\ \mathbf c) \mathbf u_{\sigma(1)}\\
	\vdots
\end{pmatrix}_{(\mathbf 0,\mathbf c) \in A_i^{(0)}}
\\
\begin{pmatrix}\vdots \\
	\nu_{i,\omega}^{p-1}
	(u_{\sigma(1)})_{j_1(\mathbf b)}
	\\ \vdots
\end{pmatrix}_{(\mathbf b\, \mathbf c) \in A_i^{(1)}}
\\
	\begin{pmatrix}\vdots \\
	\nu_{i,\omega}^{p-2}
	\nu_{\omega}
		(u_{\sigma(1)})_{j_1(\mathbf b)}
	\\ \vdots
	\end{pmatrix}_{(\mathbf b,\mathbf c) \in A_i^{(2)}}
\\
\vdots
\end{matrix}
\right\|.
\end{eqnarray*}
All this simplifies to
\begin{eqnarray*}	
\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
	\le \hspace{-12em} & &
\\
	&\le& 
	\frac{\nu_{\omega}^{p-1}}
	{p!}
\sum_{\sigma \in S_p}
\left\|
\begin{matrix}
	A_i^{(0)} \mathbf u_{\sigma(1)} 
\\
	A_i^{(1)} \mathbf u_{\sigma(1)} 
\\
	\nu_{\omega}^{-1} 
	\begin{pmatrix}\vdots \\
		(u_{\sigma(1)})_{j_1(\mathbf b)} \\ \vdots
\end{pmatrix}_{(\mathbf b\,\mathbf c) \in A_i(2)}
\\
\vdots
\end{matrix}
\right\|.
\end{eqnarray*}
According to Lemma~\ref{lem-Li}, the top two blocks are 
\[
	\sqrt{\#A_i} L_i \mathbf u_{\sigma(1)} =
\sqrt{\#A_i} D[\Omega_{A_i}(\mathbf 0,\mathbf 0)] \mathbf u_{\sigma(1)}
\]
with total norm $\le \sqrt{\# A_i^{(0)}}$. 
From Lemma~\ref{coord},
the other coordinates are bounded by $1$,
and there are $\#A_i-\#A_i^{(0)}$ of them. 
Hence,
\[
\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
\le
\nu_{\omega}^{p-1}
\sqrt{\# A_i}
.
\]
\medskip
\par
We prove now the special case $\mathbf u = \begin{pmatrix}
	\mathbf u_i' \\ \mathbf 0
\end{pmatrix}$ with $\| u_i'\|_{\infty} \le h$ for $i \le l$.
Under the notation in \eqref{bcj},
Equation \eqref{Dp1} becomes
\begin{equation}\label{Dp2}\begin{split}
	\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
	\le \hspace{-12em} & 
\\
	&\le 
\frac{1}{p!}
\sum_{\sigma \in S}
\left\|
\begin{pmatrix}
	\vdots \\
	(\mathbf u_{\sigma(1)})_{j_1}
\dots
(\mathbf u_{\sigma(k)})_{j_k}
	(\mathbf 0\  \mathbf c)\mathbf u_{\sigma(k+1)}
\dots
	(\mathbf 0\ \mathbf c)\mathbf u_{\sigma(p)}
\\
	\vdots
\end{pmatrix}_{(\mathbf b\, \mathbf c) \in A_i}
\right\|
	\end{split}
\end{equation}
where the sum ranges over the subset $S \subset S_p$ of permutations
with $\sigma(1), \dots, \sigma(l) \le k$. There are 
$ \le p!$ such permutations.
The rows indexed by $(\mathbf b, \mathbf c)$ in submatrices $A_i^{0}$ to $A_i^{l-1}$ all
vanish. The remaining rows in the matrix can be bounded in absolute value by
\[
	\nu_{\omega}^{k-l}
	\nu_{\omega_i}^{p-k} 
	\le
	h^l 
	\nu_{\omega}^{p-l}
\]
and hence 
\[
\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf 0,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
\le
h^l \sqrt{\# A_i}\nu_{\omega}^{p-l}
.
\]
\end{proof}

\begin{lemma}\label{lemma-high-2}
	Assume that $|X_1|, \dots, |X_l| \le h$. Then,
	\[
		\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf X, \mathbf 0)\right\|_{\omega}
		\le
		\frac{\sqrt{\#A_i} \nu_{\omega}^p}
		{(1-h)^{p+1}}
	\]
\end{lemma}

\begin{proof}
	Assume that $\|\mathbf u_1\|_{i,\omega}, \dots, \|\mathbf u_p\|_{i,\omega}
	\le 1$.
Expand
\[
	\frac{1}{p!}D^p\Omega_{A_i}(\mathbf X, \mathbf 0)(\mathbf u_1, \dots, \mathbf u_p)=
	\sum_{q \ge 0}
	\frac{1}{p!q!}
	D^{p+q}\Omega_{A_i}(\mathbf 0, \mathbf 0)
	\left(
	\begin{pmatrix} 
	\mathbf X\\\mathbf 0 \end{pmatrix}^q,
	\mathbf u_1, \dots, \mathbf u_p
	\right)  
\]
	The initial term $q=0$ is bounded above by $\sqrt{\#A_i} \nu_{\omega}^p$
	and subsequent terms by 
	$\binomial{p+q}{q} h^q \sqrt{\#A_i} \nu_{\omega}^{p}$.
Thus,
	\begin{eqnarray*}
	\frac{1}{p!}
	\left\| 
D^p\Omega_{A_i}(\mathbf X, \mathbf 0)(\mathbf u_1, \dots, \mathbf u_p)
		\right\| &\le&
		\sqrt{\#A_i} 
		\nu_{\omega}^p
		\left( 1 + \binomial{p+1}{1}h + \binomial{p+2}{2}h^2 + \dots \right)
\\
		&=&
		\frac{\sqrt{\#A_i} \nu_{\omega}^p}
		{(1-h)^{p+1}}
		\end{eqnarray*}


\end{proof}



\subsection{Proof of the Higher Derivative Estimate}

\begin{proof}[Proof of Theorem~\ref{th-higher}]
	We have to prove that
	\begin{equation}\label{gamma-part}
	\gamma (\mathbf Q; \mathbf X, \mathbf 0) 
\le 
	\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
	\frac{\nu_{\mathbf \omega}^2}{(1-h)^3}
	\sqrt{\sum_i s_i^2}  
	\end{equation}
	The case $
	\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}=
	\infty$ is trivial, so we assume
	$
	\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
	< \infty$.
	As before, suppose that $\|\mathbf u_1\|_{\omega}, \dots, \|\mathbf u_p\|_{\omega} \le 1$. Lemma~\ref{lemma-high-2} yields:
\[
	\frac{1}{p!} \left\| D^p\Omega_{A_i}(\mathbf X,\mathbf 0) (\mathbf u_1, \dots, \mathbf u_p) \right\|
	\le \frac{\nu_\omega^{p-1} 
	\sqrt{\# A_i}}{(1-h)^{p+1}}
\]
	Let $\Delta = \diag{\|\omega_i\| \|\mathbf q_i\|}$.
	Since $\| \omega_i \|=\sqrt{\#A_i^{(0)}}$, 
\[
	\frac{1}{p!} \left\| \Delta^{-1} \begin{pmatrix}\vdots \\ \mathbf q_i D^p\Omega_{A_i}(\mathbf X,\mathbf 0)\\ \vdots\end{pmatrix} (\mathbf u_1, \dots, \mathbf u_p) \right\|
		\le 
	\frac{\nu_\omega^{p-1} \sqrt{\sum s_i^2}}{(1-h)^{p+1}} 
\]
Therefore, 
	\[
	\frac{1}{p!} \left\|D\mathbf Q(\mathbf X, \mathbf 0)^{-1} 
		\Delta^{-1}
	\begin{pmatrix}\vdots \\ \mathbf q_i D^p\Omega_{A_i}\\ \vdots\end{pmatrix} (\mathbf u_1, \dots, \mathbf u_p) \right\|_{\omega}
		\le  
	\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
\frac{\nu_{\omega}^{p}
\sqrt{\sum_i s_i^2}  
	}{(1-h)^{p+1}} 
		\]
	and we would like to take the $p-1$-th root of the right-hand-side, which factors as
\[
		\left(\frac{\nu_{\omega}}{1-h} \right)^{p-1}
		\left(\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
\frac{\sqrt{\sum_i s_i^2}  
		}{(1-h)^{2}}\right) 
\]
	We claim that the expression under parentheses is $\ge 1$. 
By construction, for any $\mathbf u$ with $\|\mathbf u\|_{\omega}=1$ we have
\[
	\|D\mathbf Q(\mathbf X,\mathbf 0)\mathbf u\| \le \|\mathbf u\|_{\omega} \max_i \frac{\|\Omega_{A_i}(X,0)\|}
	{\| \omega_i\|} \le 1+h \max s_i.
\]
	It follows that 
		\[
\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
(1+h\max s_i)   
\ge 1
\]
and
\[
		\| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
\frac{\sqrt{\sum_i s_i^2}  
		}{(1-h)^{2}} 
\ge
\frac{\sqrt{\sum_i s_i^2}  
}{(1-h)^{2}(1+h \max s_i)} 
\ge
\frac{1}{(1-h)^2} \ge 1
.
\]
We deduce that
\[
	\gamma (\mathbf Q; \mathbf X,\mathbf 0) \le 
        \| D\mathbf Q(\mathbf X,\mathbf 0)^{-1}\|_{\omega}
	\frac{\nu_{\omega}
\sqrt{\sum_i s_i^2}  
	}{(1-h)^3}
	.
\]
\end{proof}





\section{Homotopy near infinity}
\label{sec:homotopy}

We keep the assumption that the tuple $\mathbf A$ satisfies Hypothesis~\ref{NDIH}, with splitting 
$\mathbb R^n = \mathbb R^l \times \mathbb R^{n-l}$ with $l \ge 1$.
Through this section we consider an homotopy path in the solution variety
of the form $(\mathbf g_t, \Omega_{\mathbf A}(\tilde {\mathbf X}_t, \tilde {\mathbf y}_t))$,
so that $\mathbf g_t \cdot \Omega_{\mathbf A}(\tilde {\mathbf X}_t, \tilde {\mathbf y}_t) \equiv \mathbf 0$.
We will assume that the {\em partially renormalized} condition metric integral
$\renlength{l}=	\renlength{l}(\mathbf g_t
\cdot 
\mathbf R(\mathbf 0, \tilde {\mathbf y}_t)
, \Omega_{\mathbf A}(\tilde {\mathbf X}_t, \mathbf 0
); 0,T)$ is finite,
\[
	\renlength{l} =
	\int_{0}^{T}
\left(\left\| \frac{\partial}{\partial t} \mathbf g_t 
\cdot 
\mathbf R(\mathbf 0, \tilde {\mathbf y}_t)
\right\|_{\mathbf g_t} 
+\left\| \frac{\partial}{\partial t} \Omega_{\mathbf A}(\tilde {\mathbf X}_t, 
\mathbf 0 
)
\right\|_{\boldsymbol \omega}
\right) \mu(\mathbf g_t, \Omega_{\mathbf A}(\tilde {\mathbf X}_t, \tilde {\mathbf y}_t))
\dd t .
\]
Above, the first norm in the integrand is the product Fubini-Study metric in 
multiprojective space 
$\MP(\mathscr P_{\mathbf A})= \mathbb P(\mathscr P_{A_1}) \times \cdots \times \mathbb P(\mathscr P(A_n))$.
The second norm is the norm in $T_{\boldsymbol \omega}\mathscr V_{\mathbf A}$ induced by the
embeding of 
$\mathscr V_{\mathbf A}$ in multiprojective
space $\mathbb P(\mathbb C^{A_1}) \times \dots \times \mathbb P(\mathbb C^{A_n})$. 


\subsection{Partially renormalized homotopy}

The objective of this section is to produce a viable numerical method for path-following near toric infinity.
We will approximate the neighborhood of toric infinity $\boldsymbol \omega$ up to first order by
the tangent plane $T_{\boldsymbol \omega} \mathscr V_{\mathbf A}$. The systems of equations will be
approximated as in the previous sections, but this time by a family of partially renormalized systems
\begin{equation}\label{ersatz2}
	\defun{\mathbf Q = \mathbf Q_{t, \bar y}}{T_{\boldsymbol \omega}\mathscr V_{\mathbf A}}{\mathbb C^n}
	{(\mathbf X,\mathbf y)}{
\begin{pmatrix}
	\frac{1}{\|\omega_1\|\|(g_{t})_{1} \cdot R_1(\mathbf 0, \mathbf{\bar y})\|} (g_{t})_1  \cdot R_1(\mathbf 0, \mathbf{\bar y})\cdot \Omega_{A_1}(\mathbf X,\mathbf y)
\\
\vdots \\
	\frac{1}{\|\omega_n\|\|(g_{t})_{n} \cdot R_n(\mathbf 0, \mathbf{\bar y})\|} (g_{t})_n \cdot R_n(\mathbf 0, \mathbf{\bar y}) \cdot \Omega_{A_n}(\mathbf X,\mathbf y)
\end{pmatrix}
	.}
\end{equation}
The main difference is that $g_t$ depends on a parameter $t$. The values of $\mathbf{\bar y}$ will be computed
during  the approximation procedure described below. Once $\bar{\mathbf y}$ is fixed,
the partially renormalized Newton operator for $\mathbf Q_{t, \bar{\mathbf y}}$ is
\[
	N (\mathbf Q_{t, \bar {\mathbf y}}; \mathbf X,\mathbf y) = 
	(\mathbf X,\mathbf y) - D\mathbf Q_{t,\bar{\mathbf y}}(\mathbf X,\mathbf y)^{-1} 
	\mathbf Q_{t,\bar {\mathbf y}}(\mathbf X,\mathbf y).
\]
We will denote by $N^s(\mathbf Q_{t, \bar {\mathbf y}}; \cdot)$ the composition
of $s$ steps of Newton iteration, that is
\[
	N^{s+1}(\mathbf Q_{t, \bar {\mathbf y}}; \mathbf X,\mathbf y) =
N(\mathbf Q_{t, \bar {\mathbf y}}; 
N^s(\mathbf Q_{t, \bar {\mathbf y}}; \mathbf X,\mathbf y))
\]
where $\bar {\mathbf y}$ does not change.

\begin{definition}[Partially renormalized homotopy]\label{defprh} 
Let $c_{**}$ and $\alpha$ be constants to be determined, depending on $\mathbf A$ and on the splitting
$\mathbb R^l \times \mathbb R^{n-l}$.
	The  
	approximation algorithm for the partially renormalized homotopy path 
	$(\mathbf g_t \cdot R( \mathbf 0, \mathbf{\tilde y_t}), ( \mathbf{\tilde X}_t,\mathbf 0
	))_{t \in [t_0, T]}$ is given by the recurrence:
\begin{equation}\label{recurrence1}
	(\mathbf X_{j+1},\mathbf y_{j+1}) = 
	(\mathbf 0,\mathbf y_j) + N(\mathbf Q_{t_j,\mathbf y_j}; \mathbf X_j,\mathbf 0) 
\end{equation}
	where the step size selection satisfies
	\begin{equation}\label{selection-next}
		t_{j+1} = \min \left(\strut T, \inf \left \{t>t_j: c_{**} \beta_{j+1}(t) \mu_{j+1}(t) 
	> \alpha\right \}\right)
	\end{equation}
and the notations $\beta_j$ and $\mu_j$ stand for
	\begin{eqnarray*}
		\beta_j(t) &=& 
\left\|\strut
	D\mathbf Q_{t,\mathbf y_j}(\mathbf X_j,\mathbf 0)^{-1} \mathbf Q_{t,\mathbf y_j}(\mathbf X_j,0)
\right\|_{\omega}
	\\
	\mu_j(t) &=& 
\left\|\strut
	D\mathbf Q_{t,\mathbf y_j}(\mathbf X_j,\mathbf 0)^{-1} 
\right\|_{\omega}
.
\end{eqnarray*}
\end{definition}





\begin{theorem}\label{prhomotopy} Assume that $\mathbf A=(A_1, \dots, A_n)$ is in normal form
	with respect to the splitting $\mathbb R^l \times \mathbb R^{n-l}$.
	There are constants $c_{**} \ge 1$, $\alpha_*$ and $u_*$ with the
	following properties.
	Suppose that $(\mathbf X_0,\mathbf y_0)$ satisfies 
\[
	c_{**} \, \beta_0(t_0)\, \mu_0(t_0) \le \alpha \le \alpha_*
\]
	and the sequence of $(\mathbf X_j, \mathbf y_j)$ is produced according to Definition~\ref{defprh} for
	$0=t_0 \le t \le t_J \le T$. 
	Suppose in addition that for $0 \le j \le J$, 
	$\max_k |(X_{j})_k| \le \frac{1}{4}$. Then,
\begin{enumerate}[(a)]
\item
	\label{kind1}
For all $j \le J$,
		\[
	c_{**} \, \beta_j(t_j)\, \mu_j(t_j) \le \alpha .
\]
\item Let $(\mathbf{\tilde X}_t, \mathbf{\tilde y}_t + \mathbf y_{j})$ be the zero of $\mathbf Q_{t, \mathbf y_j}$ associated
	to $(\mathbf X_j, \mathbf y_j)$, $0 \le j \le J$. The path $(\mathbf{\tilde X}_t, \mathbf{\tilde y}_t)$ is
		continuous for $0 \le t \le T$.
\item
	$\max_{k\le l} |(\mathbf{\tilde X}_t)_k| \le 1/2$,
\item For all
	\label{kind2}
	$t_j \le t \le t_{j+1} \le t_J$, 
\[
	u_j(t):= \left\|\strut D\mathbf Q_{t,\tilde {\mathbf y}_t}(\tilde {\mathbf X}_t,0)^{-1}\right\|_{\omega} 
	\left\|(\mathbf X_{j+1}-\tilde {\mathbf X}_t,\mathbf y_{j+1}-\tilde {\mathbf y}_t) \right\|_{\omega}
			\le u_*.
		\]
\item
	\[
	J \le O\left(\strut 
		\renlength{l}\left(\mathbf g_t \cdot R(\mathbf 0, \mathbf {\tilde y}_t), 
		\Omega_{\mathbf A}(\tilde {\mathbf X}_t, \mathbf 0; 0,T\right) \right)
.
\]
\end{enumerate}
\end{theorem}

\subsection{Preliminaries}
\begin{lemma}\label{fRdist}
Let $\mathbf q_i \in \mathscr F_{A_i}$ and $\mathbf y \in \mathbb C^n$.
Then for all $i=1, \dots, n$, 
\[
	d_{\mathbb P}(\mathbf q_i, \mathbf q_i \cdot R_i(\mathbf 0,\mathbf y)) \le \sqrt{5}\ \|(\mathbf 0,\mathbf y)\|_{i,\omega} \nu_{i,\omega}\  .
\]
Moreover,
\[
	d_{\mathbb P}(\mathbf q, \mathbf q \cdot R(\mathbf 0,\mathbf y)) \le \sqrt{5}\ \|(\mathbf 0,\mathbf y)\|_{\omega}\  \nu_{\omega}.
\]
\end{lemma}

The proof is the same as of Lemma \toricII{5.1.1} so it will be omitted. The two following results are similar to
Theorem~\toricI{4.3.1} but still require a proof.

\begin{lemma}\label{var-mu} There is a constant $c$ depending only of $\mathbf A$ and of the splitting
	$\mathbb R^l \times \mathbb R^{n-1}$ such that, 
	if $h=\max_{1 \le i \le l} |X_i|<\frac{1}{2}$ for all $i \le l$,
	$\beta = \| (\mathbf X,\mathbf y)-(\mathbf X', \mathbf y')\|_{\omega} \le \beta_0=\frac{1}{2\sqrt{5}\nu_{\omega}}$,
	then
\[
	\frac{ \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} }
	     { 1 + c \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} \beta }
		\le
	\|D\mathbf Q_{t,\mathbf y'}(\mathbf X',\mathbf 0)^{-1}\|_{\omega}
.
\]
If furthermore 
	and $c \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} \beta < 1$, 
	then
\[
	\|D\mathbf Q_{t,\mathbf y'}(\mathbf X',\mathbf 0)^{-1}\|_{\omega}
\\
		\le
	\frac{ \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} }
		{ 1 - c \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} \beta }.
\]
\end{lemma}

\begin{lemma}\label{var-mu2} There is a constant $c$ depending only of $\mathbf A$ and of the splitting
	$\mathbb R^l \times \mathbb R^{n-1}$ such that, 
	if $h=\max_{1 \le i \le l} |X_i|, |X_i'|<\frac{1}{2}$ for all $i \le l$,
	$d_{\mathbf P}(\mathbf g_t R(\mathbf 0, \mathbf y), \mathbf g_{t'} R(\mathbf 0, \mathbf y'))  \le \delta<\frac{1}{2}$,
	and $\beta = \| (\mathbf X,\mathbf 0)-(\mathbf X', \mathbf 0)\|_{\omega} 
	\le \beta_0=\frac{1}{2\sqrt{5}\nu_{\omega}}$,
	then
\[
	\frac{ \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} }
	     { 1 + c \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} (d_{\mathbb P}+\beta) }
		\le
	\|D\mathbf Q_{t',\mathbf y'}(\mathbf X',\mathbf 0)^{-1}\|_{\omega}
.
\]
If furthermore 
	and $c \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} (d_{\mathbb P}+\beta) < 1$, 
	then
\[
	\|D\mathbf Q_{t',\mathbf y'}(\mathbf X',\mathbf 0)^{-1}\|_{\omega}
\\
		\le
	\frac{ \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} }
		{ 1 - c \|D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0)^{-1}\|_{\omega} (d_{\mathbb P}+\beta) }.
\]
\end{lemma}

Before proceeding to the proof of the above Lemmas, we need to establish a few basic facts. 
Given $\mathbf 0 \ne \mathbf q, \mathbf q' \in \mathscr P_{\mathbf A}$, we define the (multi-)projective, 
(multi-)chordal  
 distances as
\begin{eqnarray*}
	d_{\mathbb P}(\mathbf q, \mathbf q') &=&
	\sqrt{\sum_i \left( \inf_{\lambda_i \in \mathbb C_{\times}} \frac {\| q_i - \lambda q_i'\|}{\| q_i\|} \right)^2} 
\\
	d_{\mathrm{chordal}}(\mathbf q, \mathbf q') &=&
	\sqrt{\sum_i \left( \inf_{\lambda_i \in S^1 \mathbb C_{\times}} \frac {\| q_i - \lambda q_i'\|}{\| q_i\|} \right)^2} 
\end{eqnarray*}
\begin{lemma} \label{chordal}
	Suppose that $\max_i d_{\mathbb P}(q_i, q_i')\le \eta$. Then,
	\[
d_{\mathbb P}(\mathbf q, \mathbf q') \le 
d_{\mathrm{chordal}}(\mathbf q, \mathbf q') 
\le
	\frac{1}{\sqrt{1-\eta^2}}
	d_{\mathbb P}(\mathbf q, \mathbf q')
	\]
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{chordal}]
	Rescale the $q_i$ and $q'_i$ so that $\|q_i\|=1$ and $\|q_i-\lambda_i q'_i\|$ minimal for $|\lambda_i|=1$.
	In this case $\langle q_i, q'_i \rangle > 0$ and the angle 
	$\alpha_i = \widehat{q_i, q'_i}$ is real, we take $\alpha_i \in [0, \pi/2]$. We can write

\begin{eqnarray*}
	d_{\mathbb P}(\mathbf q, \mathbf q') &=&
	\sqrt{\sum_i \left(\sin(\alpha_i)\right)^2}
\\
	d_{\mathrm{chordal}}(\mathbf q, \mathbf q') &=&
	\sqrt{\sum_i \left( 2 \sin\left( \frac{\alpha_i}{2} \right) \right)^2}
\end{eqnarray*}
	Concavity of the sine function implies that $\sin(\alpha_i) \le 2 \sin\left( \frac{\alpha}{2} \right)$
	for $0 \le \alpha \le \pi/2$.
	From the hypothesis, $\delta = \sin(\alpha_i) \le \eta$. 
	We claim that 
$2\sin \left( \arcsin \left(\frac{\delta}{2} \right) \right) \le
\frac{\delta}{\sqrt{1-\eta^2}}$.
	Indeed, define $d_{\mathbb P}(\delta)=
2\sin \left( \arcsin \left(\frac{\delta}{2} \right) \right)$. Then,
	\[
		{d_{\mathbb P}}'(\delta) = \frac{\cos\left( \arcsin \left(\frac{d}{2} \right)\right)}
		{\sqrt{1-\delta^2}} \le \frac{1}{\sqrt{1-\eta^2}}.
	\]
The mean value Theorem guarantees that there is $0 < \xi < 1$ such that
	\[
		d_{\mathbb P}(\delta) - d_{\mathbb P}(0) = \delta\, {d_{\mathbb P}}'(\xi \delta)
		\le
	\frac{\delta}{\sqrt{1-(\xi \eta)^2}}
		\le
	\frac{\delta}{\sqrt{1-\eta^2}}.
	\]
\end{proof}





\begin{proof}[Proof of Lemma ~\ref{var-mu}]
To simplify notations, write
\begin{eqnarray*}
	M &=& D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0) \\
		M' &=& D\mathbf Q_{t,\mathbf y'}(\mathbf X,\mathbf 0) \\
		N &=& D\mathbf Q_{t,\mathbf y'}(\mathbf X',\mathbf 0) \\
\end{eqnarray*}
	Also, let $\mathbf q= \mathbf g_t \cdot R(\mathbf 0,\mathbf y)$ and  $\mathbf q'= \mathbf g_t \cdot R(\mathbf 0,\mathbf y')$.
\medskip
	\noindent \\ {\bf Step 1:} We initially claim that
	\begin{equation}\label{Mstep1}
		\|M-M'\| \le d_{\mathrm{chordal}}(\mathbf q, \mathbf q') \max_i
	\frac{1}{\|\omega_i\|} \left\| D\Omega_{A_i}(\mathbf X,\mathbf 0) \right\|_{\omega}
	\end{equation}
Indeed,
\[
	M= 
\diag{\frac{1}{\|\omega_i\| \| q_{i}\|} }
\begin{pmatrix}
	\vdots\\
	q_{i} D\Omega_{A_i}(\mathbf X, \mathbf 0)  
	\\
	\vdots
\end{pmatrix}
\]
	and $M'$ is obtained by replacing $\mathbf q$ with $\mathbf q'$. 
	Since $M$ (resp. $M'$) is
	invariant by rescaling of each $q_i$ (resp $q_i'$), we rescale so that for each $i$, 
	that $\|q_i\|=\|q_i'\|=1$ and $\|q_i-q_i'\|$ is minimal. Then we see that
	$d_{\mathrm{chordal}}(\mathbf q, \mathbf q') = \|\mathbf q-\mathbf q'\|$ establishing \eqref{Mstep1}.



	The chordal distance in \eqref{Mstep1} can be bounded as follows. From 
	Lemma \ref{fRdist},
\[
	d_{\mathbb P}(\mathbf q, \mathbf q') \le 
		\sqrt{5} \beta \nu_{\omega} \le \frac{1}{2}.
\]
	Then we can apply Lemma~\ref{chordal} with $\eta=1/2$ to obtain
	\begin{equation}\label{Mstep2}
d_{\mathrm{chordal}}(\mathbf q, \mathbf q') \le 
		\frac{2 \sqrt{5}}{\sqrt{3}} \beta \nu_{\omega} \le \frac{1}{2}.
\end{equation}

	For the rightmost term of \eqref{Mstep1}, suppose that $\|\mathbf u\|_{i,\omega} \le 1$. From Lemma \ref{lemma-high-1},
	\begin{eqnarray*}
\|D\Omega_{A_i}(\mathbf X, \mathbf 0) \mathbf u\| 
		&\le&
		\|\omega_i\| + \sum_{k\ge 2} \frac{1}{(k-1)!}\| D^{k}\Omega_{A_i}(\mathbf 0, \mathbf 0) (\mathbf X, \dots, \mathbf X,u)\| 
\\
	&\le&
\|\omega_i\|+	
		\nu_{\omega} 
	\sqrt{\#A_i} 
		\sum_{k \ge 2} k h^{k-1}
	\\
		&\le&  
\|\omega_i\|+	
		\nu_{\omega}
		\sqrt{\#A_i} \frac{2h-h^2}{(1-h)^2}
		.
	\end{eqnarray*}
Multiplying by \eqref{Mstep2} and dividing by $\|\omega_i\|$,
	\begin{equation}\label{varmu-1}
\|M-M'\| \le 
		\frac{2\sqrt{5}}{\sqrt{3}} \beta \nu_{\omega}
		\left(1+ 
		\max(s_i) \frac{2h-h^2}{(1-h)^2} \nu_{\omega}\right).
	\end{equation}
\medskip
\noindent \\
	{\bf Step 2}. Assume $\finsler{\mathbf u}{\omega}\le 1$ and recall that $\| \mathbf X - \mathbf X', \mathbf 0\|_{\omega} \le \beta$. 
	We expand:
	\begin{eqnarray*}
D\Omega_{A_i}(\mathbf X', \mathbf 0) \mathbf u - D\Omega_{A_i}(\mathbf X, \mathbf 0) \mathbf u 
&=&
		\sum_{k \ge 2} \frac{1}{(k-1)!} D^k \Omega_{A_i}(\mathbf X,\mathbf 0)((\mathbf X'-\mathbf X)^{\otimes k-1}, \mathbf u) 
\\
		&&\hspace{-6em}=
		\sum_{k \ge 2} \sum_{l \ge 0}
		\frac{k \binomial{k+l}{l}}{(k+l)!} D^{k+l} \Omega_{A_i}(\mathbf 0,\mathbf 0)
		(\mathbf X^{\otimes l}, (\mathbf X'-\mathbf X)^{\otimes k-1}, \mathbf u).
	\end{eqnarray*}
Passing to norms and applying Lemma~\ref{lemma-high-1} again,
\begin{eqnarray*}
\|
D\Omega_{A_i}(\mathbf X', \mathbf 0) \mathbf u - D\Omega_{A_i}(\mathbf X, \mathbf 0) \mathbf u 
\|
	&\le&
	\sqrt{\#A_i}
\sum_{k \ge 2} \sum_{l \ge 0}
	k \binomial{k+l}{l} h^l \beta^{k-1} \nu_{\omega}^{k}
\\
&=&
\sqrt{\#A_i}
\sum_{k \ge 2}
	k \frac{\beta^{k-1} \nu_{\omega}^{k}}{(1-h)^{k+1}}
\\
	&=&
	\frac{
		\sqrt{\#A_i}\nu_{\omega}}
	{(1-h)^2}
	\left( \frac{1}{ \left(1- \frac{\beta \nu_{\omega}}{1-h}\right)^2}-1\right)
\end{eqnarray*}
It follows that
\begin{equation}\label{varmu-2} 
	\| (N-M')\mathbf u\| \le
	\frac{	\sqrt{\sum_i s_i^2} \nu_{\omega}}
	{(1-h)^2}
	\left( \frac{1}{ \left(1- \frac{\beta \nu_{\omega}}{1-h}\right)^2}-1\right)
\end{equation}

\medskip 
\noindent \\ {\bf Step 3:}
Combine equations \eqref{varmu-1} and \eqref{varmu-2},  
\[
\| M-N\| \le 
		\frac{2\sqrt{5}}{\sqrt{3}} \beta \nu_{\omega}
		\left(1+ 
		\max(s_i) \frac{2h\nu_{\omega}}{(1-h)^2} \right)
+
	\frac{	\sqrt{\sum_i s_i^2} \nu_{\omega}}
	{(1-h)^2}
	\left( \frac{1}{ \left(1- \frac{\beta \nu_{\omega}}{1-h}\right)^2}-1\right)
.
\]
Replace $h$ by $\frac{1}{2}$ and use $\beta \le \beta_0 \le \frac{1}{2 \sqrt{5} \nu_{\omega}}$
to bound the higher order terms.  
The right-hand side is bounded above by 
a constant times $\beta$. This constant is no more than
\[
	\nu_{\omega} \left(\frac{2\sqrt{5}}{\sqrt{3}}(1+4 \nu_{\omega} \max s_i) + 
	\frac{4}{3}\frac{2\sqrt{5}-1}{6-2\sqrt{5}} \sqrt{\sum_i s_i^2}\right)
.
\]
Finally apply Lemma \toricI{4.3.3}.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{var-mu2}] The proof is very similar to that of Lemma~\ref{var-mu},
	but this time we set
\begin{eqnarray*}
	M &=& D\mathbf Q_{t,\mathbf y}(\mathbf X,\mathbf 0) \\
