\subsection{Proof of Theorem~\ref{prhomotopy}}
The following is very similar to Lemma \toricII{5.2.1}, but the proof differs slightly. 

\begin{lemma}\label{lem-well-defined}
	Let $\alpha_0=\frac{13-3\sqrt{17}}{4}$ 
	and define $\psi(\alpha) = 1 - 4\alpha + 2 \alpha^2$.
	Let $\beta_0$ and $c$ be the constants of Lemma~\ref{var-mu}, let
	$c_*$ satisfy \eqref{c-star} for some $h=1/4$,
	and choose $c_{**}\ge\max(c_*,c)$.
	Denote by 
	$(\mathbf X_t',\mathbf y_t'-\mathbf y_j)=N(\mathbf Q_{t,\mathbf y_j}, (\mathbf X_j, \mathbf 0))$ 
	and
	$(\mathbf{\tilde X}_t,\tilde{\mathbf y}_t-\mathbf y_j)=\lim_{s \rightarrow \infty} N^s(\mathbf Q_{t,\mathbf y_j}, (\mathbf X_j, \mathbf 0))$.
	Assume that
		$h=\max_k |X_{j}|_k \le 1/4$
	and for all $t_j \le t \le t_{j_1}$,
\[
	c_{**} \, \beta_j(t) \mu_j(t) \le \alpha \le 
		  \alpha_*:=\min\left(\alpha_0, \frac{1}{8r_0(\alpha_0) \max_i \|\omega_i\|}\right)
\]
Then,
\begin{enumerate}[(a)]
		\item
		\[
	c_{**} \, \beta_{j+1}(t)\, \mu_{j+1}(t) 
	\le \alpha
.
\]
\item 
	$h'=\max_{k \le l} |(\mathbf X_{j+1})_k| \le 3/8$.
\item 
	$\tilde h=\max_{k \le l} |(\tilde {\mathbf X}_t)_k| \le 1/2$.
	\item The path $({\tilde {\mathbf X}}_t, \tilde {\mathbf y}_t)$ is continuous.
\end{enumerate}
\end{lemma}

\begin{proof}
	Part (a) is a direct consequence of the choice of $t_{j+1}$ in \eqref{selection-next}.
	By Lemma~\ref{inf-norms}(a),
\[
	h'\le h + \beta_j(t_j) 
\]
	and (b) follows from the bound
\[
	\beta_j(t_j) \le 
	\alpha \le \frac{1}{8 \max_i \|\omega_i\|}.
\]
	Item (c) is similar but uses 
	Theorem \ref{th-higher} to bound $\tilde h \le h + \beta_j(t) r_0(\alpha)$

	implies that
\[
	\beta(\mathbf Q_{t,\mathbf y_j}, (\mathbf X_j,\mathbf 0)) \gamma(\mathbf Q_{t,\mathbf y_j}, (\mathbf X_j,\mathbf 0)) \le \alpha_0
.
\]

	The first Newton iterate of $\mathbf Q_{t,\mathbf y_j}$ with initial condition $(\mathbf X_j, \mathbf 0)$ is
$(\mathbf X_{j+1}, \mathbf y_{j+1}-\mathbf y_j)$. 
We can invoke \ocite{Bezout1}*{Prop. 3 p.478} to recover that
\[
	\beta(\mathbf Q_{t,\mathbf y_j},(\mathbf X_{j+1}, \mathbf y_{j+1}-\mathbf y_j)) \le \frac{1-\alpha}{\psi(\alpha)} 
	\alpha \beta_j(t_j).
\]
	To establish continuity in item (d), fix $\tau \in [t_j, t_{j+1}]$ and $\epsilon>0$. Note that
	by construction,
	$(\mathbf {\tilde X_\tau}, \mathbf {\tilde y_\tau})$ is uniquely defined at transition
	points $\tau=t_i$. After a fixed number of
	Newton iterates,  we obtain a continuous path 
	$(\mathbf X''_t, \mathbf y''_t)$. Corollary \ref{cor-quadratic}(a) guarantees 
	that after 
	$O(\log \log \epsilon^{-1})$ iterates,
	$\| (\mathbf X''_t, \mathbf y''_t)-(\tilde {\mathbf X}_t, \tilde {\mathbf Y}_t) \|_{\omega} < \epsilon/3$. There is
	$\delta$ such that 
	$|t-\tau|<\delta$ implies $\| (\mathbf X''_t, \mathbf y''_t)-(\mathbf X''_{\tau}, \mathbf y''_{\tau}) \|_{\omega} < \epsilon/3$. It follows that
	$\| (\tilde {\mathbf X}_t, \tilde {\mathbf y}_t)-(\tilde {\mathbf X}_{\tau}, \tilde {\mathbf y}_{\tau}) \|_{\omega} < \epsilon$.
\end{proof}

We need to rework Lemma \toricII{5.2.2}:
\begin{lemma}\label{lem-u} 
	Let $t_j$, $t_{j+1}$ and $u(t)$, $t_j \le t \le t_{j+1}$ be as in Theorem~\ref{prhomotopy}.
	Assume the conditions of Lemma~\ref{lem-well-defined}. 
Set $u_0=\frac{5-\sqrt{17}}{4}$.
For $0 <\alpha<\alpha_{0}$, 
define
\[
u_{*}=
	\frac{\alpha r_0(\alpha)}
	{1 - r_0(\alpha) \alpha}
\]
\[
u_{**}=
	\frac{\alpha r_1(\alpha)}
	{1 - r_0(\alpha) \alpha}
\]
	and $u_{***}= \frac{\alpha  \psi(u_*)}{c_{**}(1+\alpha r_0(\alpha))(\psi(u_*) +u_*)}$.  
Then,
	\begin{enumerate}[(a)]
\item for $t_j \le t \le t_{j+1}$, $u_j(t) < u_* < u_0$, 
\item $u_{j}(t_j) \le u_{**}$, and 
\item If $t_{j+1}<T$, then $u_j(t_{j+1}) \ge u_{***}$.
\end{enumerate}
\end{lemma}

\begin{proof}
	Part (a): From the choice of $t \le t_{j+1}$,
	\[
		c_{**} \beta_{j+1}(t) \mu_{j+1}(t) \le \alpha < \alpha_* \le \alpha_0.
	\]
	We are in the conditions of Corollary~\ref{cor-quadratic}, and the
Newton iterates of $\mathbf Q_{t,\mathbf y_{j+1}}$ with initial value $(\mathbf X_{j+1},\mathbf 0)$
	converge quadratically to an actual zero 
	$(\tilde {\mathbf X}, \tilde {\mathbf y}+\mathbf y_{j+1})$ 
	of $\mathbf Q_{t,\mathbf y_{j+1}}$. Moreover,
\[
	\|(\mathbf X_{j+1},\mathbf 0) - (\tilde {\mathbf X}, \tilde {\mathbf y}+\mathbf y_{j+1})\|_{\omega}
	\le
	r_0(\alpha) \beta_{j+1}(t).
\]
	From Lemma~\ref{var-mu} and the choice $c \le c_{**}$,
\[
	\| D\mathbf Q_{t, y_{j+1}+\mathbf{\tilde y}}(\mathbf{\tilde X},\mathbf 0)^{-1} \|
	\le
	\frac{\mu_{j+1}}{1-c_{**} \mu_{j+1} r_0(\alpha) \beta_{j+1}(t)}
	\le \frac{\mu_{j+1}}{1-\alpha r_0(\alpha)}
\]
This establishes that
	\[
		u_j(t) \le \frac{\alpha r_0(\alpha)}{1-\alpha r_0(\alpha)}=:u_*.
	\]
	Part (b) is similar, but Corollary~\ref{cor-quadratic}(c) with iteration starting at
	$(\mathbf X_j, \mathbf y_j)$ implies rgar $\|(\mathbf X_{j+1},\mathbf y_{j+1})-(\mathbf{\tilde X}, \mathbf{\tilde y}) \|_{\omega} \le r_1(\alpha) \beta_j(t_j)$. 
	Therefore,
	\[
		u_j(t_j) \le \frac{\alpha r_1(\alpha)}{1-\alpha r_0(\alpha)}=:u_{**}.
	\]
	Part (c): Assume that $t_{j+1} \le T$ so by construction,
\[
	c_{**} \beta_{j+1}(t_{j+1}) \mu_{j+1}(t_{j+1}) = \alpha
.
\]
	From part (a) $u_j(t_{j+1}) \le u_*$. Let $(\mathbf X',\mathbf y'+\mathbf y_{j+1})$ be the first Newton iterate of $(\mathbf X_{j+1},\mathbf 0)$
	w.r.t. $\mathbf Q_{t, y_{j+1}}$. According to \ocite{BCSS}*{Prop. 1 p. 157},
\[
	\|(\mathbf X',\mathbf y')-(\mathbf{\tilde X}, \mathbf{\tilde y}) \|_{\omega} \le \frac{u_*}{\psi(u_*)} 
	\|(\mathbf X_{j+1},\mathbf y_{j+1})-(\mathbf{\tilde X}, \mathbf{\tilde y}) \|_{\omega} 
\]
From the triangle inequality,
	\[
		\beta_j(t_{j+1}) \le \|(\mathbf X',\mathbf y')-(\mathbf{\tilde X}, \mathbf{\tilde y}) \|_{\omega}  + \|(\mathbf X_{j+1},\mathbf y_{j+1})-(\mathbf{\tilde X},\mathbf {\tilde y}) \|_{\omega} 
		\le 
		\left( 1 + \frac{u_*}{\psi(u_*)}\right) 
		\|(\mathbf X_{j+1},\mathbf y_{j+1})-(\mathbf{\tilde X}, \mathbf{\tilde y}) \|_{\omega}
.	\]
From the unconditional bound of Lemma~\ref{var-mu},
	\begin{eqnarray*}
	\mu_j(t_{j+1})
		&=&
	\| D\mathbf Q_{t_{j+1}, \mathbf y_{j}}(\mathbf X_j,\mathbf 0)^{-1} \|
		\\&\le&
	(1+c\mu_j(t_{j+1})\beta_j(t_{j+1}) r_0(\alpha)
		\| D\mathbf Q_{t_{j+1}, \mathbf y_{j+1}+\mathbf{\tilde y}}(\mathbf{\tilde X},\mathbf 0)^{-1} \|
		\\&\le&
	(1+\alpha r_0(\alpha))
		\| D\mathbf Q_{t_{j+1}, \mathbf y_{j+1}+\mathbf{\tilde y}}(\mathbf{\tilde X},\mathbf 0)^{-1} \|
	.\end{eqnarray*}
Hence,
	\[
		\frac{\alpha}{c_{**}} \le 
	(1+\alpha r_0(\alpha))
	\left( 1 + \frac{u_*}{\psi(u_*)}\right) u_{j+1}(t_{j+1})
	\]
and part(c) follows.
\end{proof}
\begin{lemma}\label{cstarstarstar} Assume $c_{**}\ge 1$ is fixed.
	For $0 \le \alpha$ small enough, $u_{**} \le u_{***} \le u_{*} \le u_0$.
	Moreover, there is a constant $c_{***}$ so that
	$u_{***}-u_{**} \ge c_{***}\alpha$
\end{lemma}

\begin{proof} All we need is the Taylor development of $u_*$ (resp. $u_{**}$, $u_{***}$) w.r.t. $\alpha$, viz.
\begin{eqnarray*}
	u_*(\alpha) &=& \alpha + 2 \alpha^2 + 6 \alpha^3 + \dots \\
	u_{**}(\alpha) &=& \alpha^2 + 4 \alpha^3 + 16 \alpha^4 + \dots\\
	u_{***}(\alpha) &=& \frac{1}{c_{**}}(\alpha - 2 \alpha^2 - 4 \alpha^3 - \dots )
\end{eqnarray*}
\end{proof}




\begin{proof}[Proof of Theorem~\ref{prhomotopy}]
