	The triangle inequality can be used to bound $d(t_{j+1})$ below.
\[
	\| (\mathbf X_{j+1}, \mathbf y_{j+1})-(\mathbf{\tilde X}_{t_{j+1}}, \mathbf{\tilde y}_{t_{j+1}}) \|_{\omega}
	-
	\| (\mathbf X_{j+1}, \mathbf y_{j+1})-(\mathbf{\tilde X}_{t_j}, \mathbf{\tilde y}_{t_j}) \|_{\omega}
	\le d(t_{j+1}).
\]
	Multiplying by $\tilde \mu(t_j)$,
\[
	u_j(t_{j+1}) \frac{\tilde \mu(t_{j})}{\tilde \mu(t_{j+1})} - u_j(t_j) \le \tilde \mu(t_j) d_{\mathrm{max}(t_{j+1})}
.
\]
Invoking Lemma~\ref{var-mu2},
\[
	u_j(t_{j+1})\left(\strut 1-c \tilde \mu(t_j) d(t_{j+1})\right)  - u_j(t_j) \le 
\frac{\renlength{}}{1-c\renlength{}}
.
\]
Using \eqref{prhA} again and rearranging,
\[
	u_j(t_{j+1})
	- u_j(t_j) \le 
\frac{\renlength{}}{1-c\renlength{}}
	+c \tilde \mu(t_j) d(t_{j+1}) u_j(t_{j+1}) 
\le
(1+c u_j(t_{j+1}))
\frac{\renlength{}}{1-c\renlength{}}
.
\]
The occurrences of $u_j$ on the right (resp. left) of the equation above can be bounded by
Lemma~\ref{lem-u}(a) (resp. Lemma~\ref{lem-u}(b,c) and also  
Lemma~\ref{cstarstarstar}),
\[
	c_{***}\alpha \le u_{***}-u_{**} \le 
	u_j(t_{j+1})
	- u_j(t_j) \le 
(1+cu_*) 
\frac{\renlength{}}{1-c\renlength{}}.
\]
Rearranging terms once again,
\[
	\frac{1}{c+ \frac{1+c u_*}{c_{***}\alpha}} \le \renlength{}
\]
\end{proof}
\section{Global analysis}
\label{sec:global}


In this section we prove the Main Theorem. We start with a toric variety $\mathscr V_{\mathbf A}$ that is $n$-dimensional and smooth. This implies Hypothesis~\ref{NDIH}. The main cover $\mathscr U$ in the main Theorem is essentially provided by Theorem~\ref{th-coords}.
Let $\mathbf A$ be the original tuple of supports. For each chart
$\Omega: \mathcal D_{\Omega} \rightarrow \mathscr V_{\mathbf A}$ from the Theorem, i
let $U=\Omega(\mathcal D_{\Omega})$ be
its image. Theorem~\ref{th-coords} implies that the set of all $U$ is a cover of $\mathscr V_{\mathbf A}$.
Coordinates $(\mathbf X, \mathbf y)$ satisfy
\[
	|X_1|, \dots, |X_l| < e^{-\Phi \|\Re (\mathbf y)\|_{\infty} - \Psi}
\]
and
\[
-\frac{\Phi^{n-l}-1}{\Phi-1}\Psi - \epsilon <
	\Re(y_{l+1}), \dots,  \Re(y_{n}) < \epsilon .
.
\]
For convenience, we add the domain of the main chart, viz.
\[
	U_0 = \left \{ v \in \mathscr V_{\mathbf A}: v=\mathbf v_{\mathbf A}(\mathbf z):
\max |\Re(z_k)| < 
\frac{\Phi^{n-1}-1}{\Phi-1}\Psi \right \}
.
\]


The path-following can start using the main chart and Theorem~\toricII{4.1.4} until a change 
of chart is necessary.  Then we pick a chart as in Theorem~\ref{th-coords}, as explained in Remarks~\ref{effective} and~\ref{algorithmic-reduction}.  The support tuple $\mathbf A$ may then be reduced to the normal form of Theorem~\ref{normal-form}.  We will argue that the algorithm in Theorem~\ref{prhomotopy} produces the correct homotopy continuation, within a number of steps that is linear on the condition length. 
The restrictions for this argument to work are as follows.
\begin{enumerate}[(A)]
	\item All the complexity bounds obtained so far depend on the renormalized condition length
		$\mathcal L$ or the partially renormalized condition length $\mathcal L_l$. We need
		bounds in terms of the natural condition length $\mathscr L$.
	\item We must be able to guarantee that during homotopy continuation, the Hypothesis
		$\max_{k \le l} |(\mathbf X_j)_k| \le e^{-h} \le 1/4$ in Theorem \ref{prhomotopy} is always satisfied
		for some $U \in \mathscr U$.
\end{enumerate} 

The following bound (proof postponed) addresses the issue (A).

\begin{theorem}\label{general-bound} 
	\begin{enumerate}[(a)]
\item
Assume that $\mathbf g_t V_{\mathbf A}( \mathbf {\tilde z}_t )\equiv 0$ 
for $T_1 \le t \le T2$. Let 
\[
\bar\ell = \max_{T_1 \le t \le T_2} 
			\max_i \left(\ell_i (\mathbf {\tilde z}_t) + \ell_i( \mathbf{\tilde z}_t) \right).
\]
	Then,
\[
	\renlength{}(\mathbf g_t \cdot R( \mathbf {\tilde z}_t); T_1,T_2) \le 
		\frac{4 \sqrt{2n} \nu(\mathbf 0) \max_i(\sqrt{\#A_i})}{\lambda_0}
	e^{3 \bar \ell} \condlength(g_t, \tilde z_t; T_1,T_2) .
\]
\item Now assume $\mathbf B=\mathbf A^S$ in normal form with respect to the splitting
	$\mathbb R^l \times \mathbb R^{n-l}$, and suppose that
	$\mathbf g_t \Omega_{\mathbf B}(\mathbf{\tilde X}_t, \mathbf {\tilde y}_t )\equiv 0$. 
	Suppose in addition that equation \eqref{h-bound} holds for all 
$(\mathbf{\tilde X}_t, \mathbf {\tilde y}_t )$, $T_1 \le t \le T_2$, that is
	\[
		\| \mathbf{\tilde X}_t\|_{\infty} <
		\frac{\lambda_{\omega}}{
			8 \nu_{\omega}
		\max_i\left( \sqrt{\#A_i} e^{ 2\max_i( \ell_i(\mathbf {\tilde y}_t), 
		\ell_i(-\mathbf {\tilde y}_t) )}\right)}.
	\]
Let,
\[
\bar\ell = \max_{T_1 \le t \le T_2} 
			\max_i \left(\ell_i (\mathbf {\tilde y}_t) + \ell_i (\mathbf{\tilde y}_t) \right).
\]
	Then,
\[
	\renlength{l}(\mathbf g_t \cdot R(\mathbf 0, \mathbf {\tilde y}_t),(\mathbf{\tilde X}_t, \mathbf 0); T_1,T_2) \le 
	\frac{28\,\sqrt{n} \nu(\boldsymbol \omega) \max_i(\sqrt{\#A_i})}{\lambda_{\boldsymbol \omega}} 
			e^{3 \bar \ell} \condlength(g_t, (\mathbf {\tilde X}_t, \mathbf{\tilde y}_t); T_1,T_2) .
\]
\end{enumerate}
\end{theorem}



\begin{proof}[Proof of the Main Theorem]
	Let $S = (\Xi, \Theta)$ range over all monomial transforms in $\mathfrak S$
	leaving the supports in normal form,
	for each of the domains in $\mathscr U$ except possibly the main chart.
	The constants $\Phi$ and $\Psi$ are
\begin{eqnarray*}
	\Phi &=& 4 \max_S \left( \max_i \max_{\mathbf b \in A_i^S} \|\mathbf b\|_1 \right)
\\
	\Psi &=& \max_S \left(
	\log( \nu_{\omega}) 
	- \log (\lambda_{\omega})
	\right) 
	+ 
	\frac{1}{2} \log(\max_i \#A_i) 
	+\log (8) 
\end{eqnarray*}

	This choice guarantees that for any $(\mathbf{\tilde X}_t, \mathbf{\tilde y}_t) \in U$ for $U \in \mathscr U$ will
	satisfy
	\[
		\| \mathbf{\tilde X}_t\|_{\infty} <
		\frac{\lambda_{\omega}}{
			8 \nu_{\omega}
		\max_i\left( \sqrt{\#A_i} e^{ 2\max_i( \ell_i(\mathbf {\tilde y}_t), 
		\ell_i(-\mathbf {\tilde y}_t) )}\right)}.
.	\]

	In particular, Theorem~\ref{general-bound} will bound the renormalized and partially renormalized
	condition length linearly in the condition length. We have always
\[
	\bar \ell \le 2 
	\max \left( \max_{\mathbf a \in A_i} \left( \|\mathbf a\|_1 \frac{\Phi^{n-1}-1}{\Phi - 1} \Psi
	\right), 
	\max_S \left(\max_{\mathbf b \in A_i^S} \left( \|\mathbf b\|_1 \frac{\Phi^{n-1}-1}{\Phi - 1} \Psi
	\right) \right) \right).
\]
	If $(\tilde v_t)_{t \in [T_1, T_2]} \subset U_0$, write $\tilde v_t=\mathbf v_{\mathbf A}(\tilde{\mathbf z_t})$.
	The algorithm supporting the Main Theorem is the recurrence in  
	Definition~\toricII{4.1.2}. Its correctness follows from Theorem~\toricII{4.1.4},
	as well as the step bound of $1+\frac{1}{\delta_*}
	(\renlength{}(g_t, \tilde z_t; T_1,T_2))$
	for the constant $\delta_*$ in the Theorem.
	Theorem~\ref{general-bound} yields
\[
\renlength{}(g_t, \tilde z_t; T_1,T_2) 
\le 
		\frac{4 \sqrt{2n} \nu(\mathbf 0) \max_i(\sqrt{\#A_i})}{\lambda_0}
	e^{3 \bar \ell}
\condlength(g_t, \tilde z_t; T_1,T_2) .
\]


	Now we consider the case $(\tilde v_t)_{t \in T_1, T_2} \subset U_{S}$ for some monomial transform $S$. The notation
	now is $\tilde v_t = \Omega_{\mathbf A^S}(\tilde{\mathbf X}_t, \tilde{\mathbf y}_t)$.
	We assume inductively that
\[
	c_{**} \, \beta_0(t_j)\, \mu_0(t_j) \le \alpha \le \alpha_*.
\]
	for $t_0=T_1$. From the choice of $\Psi$, we know at each step that
	$\|\mathbf{\tilde X}_{t_j}\|_{\infty} < 1/8$.


	We claim that for $\alpha$ small enough, $\|\mathbf X_j\|_{\infty} < 1/4$. 
	Indeed, from Corollary~\ref{cor-quadratic}
\[
		\|\, 
		(\mathbf{\tilde X}_{t}, \tilde y_{t}) - 
		(\mathbf X_{j}, \mathbf y_{j})\, \|_{\omega} \le r_0(\alpha) \beta_{j}(t) .
\]
	and Lemma~\ref{inf-norms}(a) implies that
\[
	\| \mathbf X_{j} \|_{\infty} < \frac{1}{8} + r_0(\alpha) \alpha < \frac{1}{4}
\]
after making $\alpha$ small enough. This fulfills the hypotheses
of Theorem~\ref{prhomotopy}. By induction, as long as $\tilde v_t)_{t \in [T_1, T_2]} \subset U$, 
the number of steps satisfies
\[
	J \le O( 
\renlength{l}(g_t, (\mathbf{\tilde X}_t,\mathbf{ \tilde y}_t)); T_1,T_2) 
).
\]
Now Theorem~\ref{general-bound}(b) guarantees that there is a constant $C_U$ so that the
number $J$ of steps is bounded above by
\[
	J \le C_U 
\condlength(g_t, (\mathbf{\tilde X}_t, \mathbf{\tilde y}_t)); T_1,T_2) 
).
\]
\end{proof}


\subsection{Proof of Theorem~\ref{general-bound}}

We will need two more Lemmas before proving Theorem~\ref{general-bound}.

\begin{lemma}\label{main-chart-bound} In the conditions of Theorem~\ref{general-bound}(a),
\[
	\begin{split}
	\left\| \frac{\partial}{\partial t} (\mathbf g_t \cdot R(\mathbf {\tilde z}_t))\right\|_{\mathbf g_t \cdot R(\mathbf z_t)}
	+\nu(\mathbf 0) \left\| \frac{\partial}{\partial t} \mathbf{\tilde z}_t
	\right\|_{\mathbf 0}
		\le &\\ &\hspace{-8em}\le
		 e^{\ell_i(\mathbf {\tilde z}_t)+\ell_i(-\mathbf {\tilde z}_t) }
	\left( \left\| \frac{\partial}{\partial t} \mathbf g_t \right\|_{\mathbf g_t}
		+
		\frac{4 \sqrt{2n} \nu(\mathbf 0) \max_i(\sqrt{\#A_i})}{\lambda_0}
		\left\| \frac{\partial}{\partial t} \mathbf {\tilde z}_t
	\right\|_{\mathbf {\tilde z}_t} \right)
	\end{split}
\]
\end{lemma}
\begin{proof}
Without loss of generality, scale $\mathbf g_t$ so that $\langle (g_i)_t, (\dot g_i)_t \rangle \equiv 0$ for each $i$.
	Fix a value of $t$ and through the momentum action, assume that $m_{i}(\mathbf {\tilde z}_t)=\mathbf 0$ at this point.
	From the product rule, $ \frac{\partial}{\partial t} ((g_i)_t \cdot R_i(\mathbf {\tilde z}_t))=
	(\dot g_i)_t \cdot R_i(\mathbf {\tilde z}_t)+
	(g_i)_t \cdot R_i(\mathbf {\tilde z}_t) \cdot \diag{A_i \frac{\partial {\mathbf {\tilde z}_t}}{\partial t}}$.
	Next, recall that the row vector notation for the $g_i$'s. Also, write $p_i=(g_i)_t R_i({\tilde z}_t)$. Under that notation, 
	$e^{-\ell_i(-\mathbf {\tilde z}_t)} \|g_i\|\le
	\|p_i\| \le e^{\ell_i(\mathbf {\tilde z}_t)} \|g_i\|$ and
	\begin{eqnarray*}
		\left\| (\dot g_i)_t \cdot R_i(\mathbf {\tilde z}_t) \right\|_{\mathbf g_t \cdot R(\mathbf {\tilde z}_t))}
		&=&
	\left\|
	\frac{1}
	{\|p_i\|}
		(\dot g_i)_t \cdot R_i(\mathbf {\tilde z}_t) 
	\left( I - 
	\frac{1}{\|p_i\|^2} p_i^* p_i\right)
	\right\| \\
		&\le&
	\left\|
	\frac{1}
	{\|p_i\|}
		(\dot g_i)_t \cdot R_i(\mathbf {\tilde z}_t) 
	\right\| \\
		&\le&
		e^{ \ell_i(\mathbf {\tilde z}_t)+\ell_i(-\mathbf {\tilde z}_t) }
		\frac{\|(\dot g_i)_t\|}
		{\|(g_i)_t\|}
\end{eqnarray*}
and hence
	\begin{equation}\label{metric-part-1}
	\left\| \dot {\mathbf g}_t \cdot R_i(\mathbf {\tilde z}_t) \right\|_{\mathbf g_t \cdot R(\mathbf {\tilde z}_t))}
\le
		e^{\max_i (\ell_i(\mathbf {\tilde z}_t)+\ell_i(-\mathbf {\tilde z}_t)) }
		\frac{\|\dot {\mathbf g}_t\|}
		{\|{\mathbf g}_t\|}
.
\end{equation}
	By the definition of $\nu_{i}(\mathbf 0)$,
\[
	\frac{ \| p_i \cdot \diag{A_i \frac{\partial {\mathbf {\tilde z}_t}}{\partial t}} \|}{\|p_i\|} \le
	\nu_i(\mathbf 0) \left\| \frac{\partial {\mathbf {\tilde z}}_t}{\partial t} \right\|_{i,\mathbf 0} 
\]
and hence
	\begin{equation}\label{metric-part-2}
	\left\| \mathbf g_t \cdot R(\mathbf {\tilde z}_t) \cdot 
	\diag{A_i \frac{\partial{\mathbf {\tilde z}}_t}{\partial t}} 
	\right\|
	_{\mathbf g_t \cdot R(\mathbf {\tilde z}_t)}
	\le
	\nu(\mathbf 0) \left\| \frac{\partial {\mathbf {\tilde z}}_t}{\partial t} \right\|_{\mathbf 0} 
	.
	\end{equation}
	Equations~\eqref{metric-part-1} and \eqref{metric-part-2} together imply that
\[
	\left\| \frac{\partial}{\partial t} (\mathbf g_t \cdot R(\mathbf {\tilde z}_t))\right\|_{\mathbf g_t \cdot R(\mathbf z_t)}
	+\nu(\mathbf 0) \left\| \frac{\partial}{\partial t} \mathbf{\tilde z}_t
	\right\|_{\mathbf 0}
\ \le \
		 e^{\ell_i(\mathbf {\tilde z}_t)+\ell_i(-\mathbf {\tilde z}_t) }
	\left\| \frac{\partial}{\partial t} \mathbf g_t \right\|_{\mathbf g_t}
	+2 \nu(\mathbf 0) \left\| \frac{\partial}{\partial t} \mathbf {\tilde z}_t
	\right\|_{\mathbf 0} 
.\]
Lemma~\ref{metric1} finishes the proof.
\end{proof}

\begin{lemma}\label{any-chart-bound} In the conditions of Theorem~\ref{general-bound}(b),
\[
\begin{split}
\left\| \frac{\partial}{\partial t} \mathbf g_t 
\cdot 
\mathbf R(\mathbf 0, \tilde {\mathbf y}_t)
\right\|_{\mathbf g_t} 
+\left\| \frac{\partial}{\partial t} \Omega_{\mathbf A}(\tilde {\mathbf X}_t, 
\mathbf 0 
)
\right\|_{\boldsymbol \omega}
	\le& \\ &\hspace{-10em}\le
		 e^{\ell_i(\mathbf {\tilde y}_t)+\ell_i(-\mathbf {\tilde y}_t) }
	\left( \sqrt{2}\left\| \frac{\partial}{\partial t} \mathbf g_t \right\|_{\mathbf g_t}
	+
	\frac{28\,\sqrt{n} \nu(\boldsymbol \omega) \max_i(\sqrt{\#A_i})}{\lambda_{\boldsymbol \omega}} 
	\left\| \frac{\partial}{\partial t} \mathbf {\tilde y}_t
	\right\|_{\mathbf {\tilde y}_t} \right)
\end{split}
\]
\end{lemma}
\begin{proof}[Sketch of the proof]
	Argue exactly as in Lemma~\ref{main-chart-bound} to obtain
\[
\left\| \frac{\partial}{\partial t} \mathbf g_t 
\cdot 
\mathbf R(\mathbf 0, \tilde {\mathbf y}_t)
\right\|_{\mathbf g_t} 
+\left\| \frac{\partial}{\partial t} \Omega_{\mathbf A}(\tilde {\mathbf X}_t, 
\mathbf 0 
)
\right\|_{\boldsymbol \omega}
	\le
		 e^{\ell_i(\mathbf {\tilde y}_t)+\ell_i(-\mathbf {\tilde y}_t) }
	\left\| \frac{\partial}{\partial t} \mathbf g_t \right\|_{\mathbf g_t}
	+2 \nu(\boldsymbol \omega) \left\| \frac{\partial}{\partial t} \mathbf {\tilde y}_t
	\right\|_{\boldsymbol \omega}
\]
	and then apply Lemma~\ref{metric2}.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{general-bound}]
Part (a) follows directly from Theorem~\ref{cost-of-renorm-legacy} combined with Lemma ~\ref{main-chart-bound}.
	Part (b) is similar. By hypothesis, equation 
\eqref{h-bound} holds for all $(\mathbf{\tilde X}_t,\mathbf {\tilde y}_t)$
with $T_1 \le t \le T_2$. Then Theorem
~\ref{cost-of-renorm} applies along the path. This bounds the condition number, the speed is bounded by
Lemma~\ref{any-chart-bound}.
\end{proof}


\section{Final remarks}
In this paper, we gave a `bundle' of local algorithms for homotopy on toric varieties. The number of homotopy steps
is linearly bounded by the condition length. It is possible to produce a global algorithm by swapping charts where
convenient. For instance, one can coarsely estimate the condition length at each step from the available data
and swap charts when it is larger than the theoretical bound, or maybe try to swap charts at every 10 steps. As
mentioned in Remark~\ref{rem-global}, the regularity of the path may affect the worst case complexity bound. 
The following problems are left open.

\begin{enumerate}
	\item
	Let $\mathbf f \in \mathscr P_{\mathbf A}$ be fixed and non-degenerate. Show that the expected condition length
	of the random linear path $\mathbf g_t = \mathbf f + t \mathbf g$, $t \in [0,1]$, $\mathbf g$ Gaussian random polynomial, is 
	polynomially bounded by the condition number of $\mathbf f$.
\item
	Let $\mathbf g_t \in \mathscr P_{\mathbf A}$ be a random path as above. Bound the expected number of chart
	swaps needed to cover its lifting $(\mathbf g_t, \mathbf {\tilde v}_t)$.
\item Also, the implementation of the algorithm suggested here is left for future work.
\end{enumerate}
All the theory in this paper makes sense if we replace the Riemannian metric
$\|\mathbf u\|_{\mathbf z} = \sqrt{ \sum_i \| \mathbf u\|_{i,\mathbf z}}$ 
by the Finsler metric $\finsler{\mathbf u}{\mathbf z} = \max_i \| \mathbf u\|_{i,\mathbf z}$.
The Finsler metric is more natural in toric varieties such as $\mathscr V_{\mathbf A}$, 
and the $\sqrt{n}$ factors in Theorems~\ref{cost-of-renorm-legacy}, \ref{cost-of-renorm} and
\ref{general-bound} go away. This requires redefining condition numbers to use a
Finsler operator norm, for instance replacing \eqref{defmu} by
		\[
\mu_{\text{Fin.}}(\mathbf f, \mathbf v)
=
\max_i \left\| 
\left(
\diag{\frac{1}{\| f_i\| \|V_{A_i}(\mathbf Z)\|}}
\begin{pmatrix}
\vdots \\
	f_i \, \diag{V_{A_i}(Z)} A_i\\
\vdots
\end{pmatrix}
\diag{\mathbf Z}^{-1}
\right)^{-1}
	\right\|_{i,\mathbf v}
		\]
which may be computationally costly.
