\begin{theorem}\label{thm:Always}
	All instances of \textsc{DiTTR} with $\Delta \leq k+1$ for odd $\Delta$ and with $\Delta \leq k+2$ for even $\Delta$ are feasible.
\end{theorem}
\begin{proof}
All instances with $\Delta \leq k+1$ for odd $\Delta$ and with $\Delta \leq k+2$ for even $\Delta$ can be realized by a simple algorithm detailed in Algorithm \ref{lis:RealAlg}.
Two realizations computed by this algorithm can be seen in  \cref{fig:sols}.
	There are three cases for the direction of a path between two vertices: 
	\begin{enumerate}
		\item The path runs entirely towards the root.
		\item The path leads  strictly away from the root.
		\item The path first heads towards the root and then changes direction away from it.
	\end{enumerate}
	In the first two cases there is no delay at all. 
	For the last case, it is easy to see that waiting time can only occur when changing direction and therefore only once per path.
	Thus, the maximum waiting time is at most $\Delta-1$ on any path.
	If $\Delta$ is even, the waiting time is at most $\Delta-2$, because by construction  incoming and outgoing edges of every vertex are assigned values of different parity. Hence, there cannot be two identical labels in a row on a fastest path.
\end{proof}

\begin{corollary}\label{thm:Always2}
	All instances of \textsc{DiTTR} with $\Delta =2$ are feasible.
\end{corollary}
\begin{proof}
	In a solution constructed by Algorithm~\ref{lis:RealAlg}, waiting time can only occur when changing direction.
	As $\Delta$ is even, the waiting time is at most $\Delta-2=0$ (see the proof for \cref{thm:Always}).
\end{proof}

This result can easily be generalized to directed bipartite graphs.

\begin{corollary}\label{thm:Always3}
	All instances of \textsc{DiTGR} where the input is restricted to a directed bipartite graph $G=(U,V,E)$ with $E \subseteq (U\times V) \cup (V \times U)$ and period $\Delta =2$ are feasible.
\end{corollary}
\begin{proof}
Given any directed, bipartite graph $G=(U,V,E)$ with $E \subseteq (U\times V) \cup (V \times U)$ and $\Delta =2$, set $\lambda(e_0)=0$ for all $e_0 \in E \cap (U\times V)$ and $\lambda(e_1)=1$ for all $e_1\in E \cap (V\times U)$.
Since every path in $G$ alternates between vertices in $U$ and vertices in $V$, there is no waiting time.
\end{proof}


\begin{restatable}{thm}{cycles}\label{thm:OddCycle}
    Instances of \textsc{DiTGR} with period $\Delta =2$ which are restricted to a directed graph $G=(V,E)$ that consists of only one bi-directed cycle of odd length and trees rooted at this cycle
    with  $D_{u,v}\in\{\hat{d}(u,v),\infty\}$ for all $u,v \in V$ can be decided in polynomial time.
\end{restatable}
\begin{proof}
	We show this by giving a reduction to \textsc{2--Vertex-Coloring} as shown in \cref{fig:1Tree}.
	Note that there is a unique shortest path in the underlying static graph for every pair of vertices $(v,w)$.
	Given an instance  $(G=(V,E), D, \Delta)$, let $\mathtt{P}\subseteq 2^E$ be the set of all edge sets of paths in $G$ and let $\mathtt{P_e}\subseteq\mathtt{P}\setminus\{\emptyset\}$ be the set of edge sets of all shortest paths where no waiting time is allowed. 
	We construct an undirected auxiliary graph $G'=(E,E')$ with 
	$E'=\{\{(x,y),(y,z)\} \mid \exists P \in \mathtt{P_e}: (x,y),(y,z) \in P\}$.
	This means that the labeling has to be chosen such that $\lambda(x,y)=(1-\lambda(y,z)) \bmod \Delta$ for any $\{(x,y),(y,z)\} \in E'$ since waiting at $y$ on the way from $x$ to $z$ is not allowed.
	As $\Delta=2$, this is true if and only if $\lambda(x,y) \neq \lambda(y,z) \text{ for all } \{(x,y),(y,z)\} \in E'$.
	Thus, given a feasible coloring $C: E \rightarrow \{0,1\}$ for $G'$, we can set $\lambda(x,y)=C((x,y)) \text{ for all } (x,y)\in E$. 
	Therefore, the instance is feasible if and only if $G'$ is bipartite which can be decided in polynomial time.
\end{proof}
