        \ex Action: set $f$\bp$[N] := f[n]$
    \end{xlist} 
\end{exe}

\begin{exe}
    \ex \textsf{NextField2}: final form [production G3 of (\ref{tbl:gen})]
    \label{ex:NFprod2**}
    \begin{xlist}
        \ex \squeeze{0.92}{Condition: $n, N$ satisfy $f[n] == f$\bp$[N]$, $r[n] ==$ CQ, $d[n] == 0, e[N] == 0, x[N] == 0$}
