\title{Vectorized Sparse Second-Order Forward Automatic Differentiation for Optimal Control Direct Methods}
\author{Yilin Zou\thanks{Ph.D. candidate, School of Aerospace Engineering, zouyl22@mails.tsinghua.edu.cn.} }
\author{Fanghua Jiang\thanks{Associate Professor, School of Aerospace Engineering, jiangfh@tsinghua.edu.cn (Corresponding Author).}}
