\includegraphics[width=\linewidth]{fig3b-crop.pdf}
\end{minipage}
\caption{{\small Test with the smooth solution given by~\eqref{eq:66}. Relative errors in the norm $\mathcal{V}_{e,\bh}(Q_T)$ for the discrete solution computed with the scheme in \eqref{eq:37}. The results are obtained by fixing the temporal mesh size $h_t$, decreasing the spatial mesh size $h_x$ and varying the polynomial degree $p$: \textcolor{myblue}{$p=1$}, \textcolor{myorange}{$p=2$}, \textcolor{myyellow}{$p=3$}, \textcolor{mypurple}{$p=4$}, \textcolor{mygreen}{$p=5$}. The left plot corresponds to maximal regularity splines, while the right plot shows results obtained using $C^1$ splines.}}
