\section{Many-server heavy-traffic}


In this section we extend our results to the case where the number of servers $n$ diverges at the same time that the slack $\epsilon$ converges to zero. This is the so-called many-server heavy-traffic regime. Throughout this section, we assume that
\begin{align}
    \lim_{n\to\infty} \frac{1}{n} \sum\limits_{l=1}^{n}\mu_l = \bar{\mu} \qquad \text{and} \qquad \lim_{n\to\infty}  \frac{1}{n} \sum\limits_{l=1}^{n}\sigma_{\mu_l}^2 = \bar{\sigma}^2.
\end{align}

\subsection{Throughput optimality}
Recall that Corollary \ref{co_our:condition} implies that $k$-SLQ-$d$ is throughput optimal if and only if
\[ d \geq n - \sum\limits_{l=1}^n \frac{ \mu_l}{\max\limits_{l\in[n]} \big\{ \mu_l \big\}}. \]
Therefore, if
\[ \bar{\mu} < \lim\limits_{n\to\infty} \max\limits_{l\in [n]} \{\mu_l\} = \mu_{\max}, \]
then skipping the $d\in \Theta(n)$ longest queues is required to be throughput optimal. In particular, we need
\[ \lim_{n\to\infty} \frac{d}{n} \geq 1- \frac{\bar{\mu}}{\mu_{\max}} .  \]
This means that, in order to be throughput optimal, we need to skip a constant fraction of servers that only deppends on the ratio of the average service rate over the maximum one.  


\subsection{Delay optimality} \label{subsec:manyserver}
The delay-optimality in the many-server heavy-traffic regime is obtained as a corollary of the non-asymptotic bounds of Theorem \ref{thm_our:SSCUpper}.


\begin{corollary} \label{co_our:manyserver}
    Consider the $k$-SLQ-$d$ system as defined in Section \ref{subsec:k-SLQ-d}. Suppose that Equation \eqref{eq:d_large_enough} holds. Then, if $\epsilon k^2 \in o\left(n^{-11}\right)$, then $k$-SLQ-$d$ is asymptotically delay optimal in heavy-traffic.
\end{corollary}

Note that we have three parameters here: the stability slack $\epsilon$ (which converges to zero), the number of servers $n$ (that diverges), and the number of rounds $k$ (which can either be a constant, or diverge). These need to be such that $\epsilon k^2 n^{11}$ converge to zero. Even when $k$ is constant, the system needs to be in a very heavy traffic with $\epsilon \in o\left(n^{-11}\right)$, well beyond Halfin-Whitt and Non-Degenerate-Slowdown, in order for the delay optimality to hold. In this case, the message rate is $\Theta\left(1/n\right)$, which is $o\left(\epsilon^{1/11}\right)$. 


\section{Proof of Theorem \ref{thm_our:stable}} \label{prf:thm_stable}
First we prove the sufficient condition for positive recurrence. Suppose that
\begin{align}
    n\lambda < \min_{I \subseteq [n] \, : \, |I| \geq d+1 } \  \left \{ \frac{n-d}{|I|-d} \sum_{ l\in I} \mu_l \right \}. \notag 
\end{align}
We want to show the Markov Chain \hyperref[def:Mkchain]{$ \{\mathbf{X}(t)\}_{t\geq 0} $} is positive recurrent. Given that the dispatcher collects the queue length vector every $k(n-d)$ time slots under our $k$-SLQ-$d$ policy, we define a new Markov chain 
\[ \tilde{\mathbf{X}}(t) := \Big( \tilde{\mathbf{Q}}(t), \tilde I_d(t), \tilde I_R(t), \tilde N_R(t)\Big) \]
such that
\[ \tilde{\mathbf{X}}(t)=\mathbf{X}(k(n-d)t) \]
for all $t\geq 0$. Since the original Markov chain $ \{\mathbf{X}(t)\}_{t\geq 0} $ is irreducible, it is enough to prove that $\{\tilde{\mathbf{X}}(t)\}_{t\geq 0}$ is positive recurrent. The proof follows the same rough structure as in \cite{eryilmaz2012asymptotically-driftmethod}, but with considerably more technical challenges due to the nature of our policy.\\

Let us define the Lyapunov functions
\[ V(\mathbf{x})= \|\mathbf{x}\|_{2} \qquad \text{ and } \qquad  W(\mathbf{x})= \|\mathbf{x}\|_2^2, \]
and the drift operator $\Delta$ by
\begin{align}
    \Delta V(\mathbf{Q}(t)) & := V(\mathbf{Q}(t+1))-V(\mathbf{Q}(t)) \notag \\
    \Delta W(\mathbf{Q}(t)) & := W(\mathbf{Q}(t+1))-W(\mathbf{Q}(t)) \notag 
\end{align}
Further, the drift of $V$ can be bounded by the drift of $W$ as follows:
\begin{align}
    \Delta V(\mathbf{Q}(t)) & = \| \mathbf{Q}(t+1) \|_2 - \| \mathbf{Q}(t) \|_2 \notag \\
    & = \sqrt{\| \mathbf{Q}(t+1) \|_2^2} - \sqrt{\| \mathbf{Q}(t) \|_2^2} \notag \\
    & \leq \frac{1}{2\| \mathbf{Q}(t) \|_2} \Big( \| \mathbf{Q}(t+1) \|_2^2 - \| \mathbf{Q}(t) \|_2^2 \Big) \notag \\
    & = \frac{1}{2\| \mathbf{Q}(t) \|_2}\big[ \Delta W\big(\mathbf{Q}(t) \big) \big] \notag
\end{align}
Fix $t\geq 0$ such that $t$ is a multiple of $k(n-d)$, and let $t'=t/k(n-d)$.\\


We begin by showing that the drift of $V(\tilde{\mathbf{Q}}(t'))$ is uniformly absolutely bounded:
\begin{align}
    | \Delta V(\tilde{\mathbf{Q}}(t')) | & = |\| \tilde{\mathbf{Q}}(t'+1) \|_2 - \| \tilde{\mathbf{Q}}(t')\|_2 | \notag \\
    & \overset{(a)}{\leq} \| \tilde{\mathbf{Q}}(t'+1)-\tilde{\mathbf{Q}}(t') \|_2 \notag \\
    & \overset{(b)}{\leq} \| \tilde{\mathbf{Q}}(t'+1)-\tilde{\mathbf{Q}}(t') \|_1 \notag \\
    & = \| \mathbf{Q}(t+k(n-d))-\mathbf{Q}(t) \|_1 \notag \\
    & = \sum\limits_{l=1}^{n} \left | \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right ) - Q_{l}(t) \right | \notag \\
    & = \sum\limits_{l=1}^{n} \left | \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right | \notag \\
    & \overset{(c)}{\leq} \sum\limits_{l=1}^{n} \left [ \left | \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) \right | + \left | \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right | \right ] \notag \\
    & \overset{(d)}{\leq} \sum\limits_{l=1}^{n} \left [ \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right ] \notag \\
    & \overset{(e)}{\leq} k(n-d)n(A_{\max}+S_{\max}), \label{eq:absolutebound}
\end{align}
where (a) follows from the fact that $\| \mathbf{x} \|_2 - \| \mathbf{y} \|_2 \leq \| \mathbf{x}-\mathbf{y} \|_2$ for any $\mathbf{x},\mathbf{y}\in\mathbb{R}^n $, (b) holds because $ \| \mathbf{x} \|_1 \geq \| \mathbf{x} \|_2 $, (c) follows from the triangle inequality, (d) follows from the fact that $ S_l(t) \geq U_l(t)\geq 0,\  \forall \ l,t $, and (e) is is due to the facts that $\|A(t)\|_1 \leq n A_{\max}$ and $S_l(t)\leq S_{\max}$ for all $l$ and $t$.\\


Secondly, we show that $W(\tilde{\mathbf{Q}}(t'))$ has a negative drift when the total queue length is sufficiently long, i.e., when  $ \| \tilde{\mathbf{Q}}(t') \|_1 \geq n k(n-d)S_{\max} $. Note that this assumption implies that there exists at least one queue $l$ such that $\tilde Q_l(t') \geq k(n-d)S_{\max} $. With this in mind, we divide the $n$ queues into a partition of five sets as follows. Given a fixed
\[ l'\in \underset{l\in [n]}{\arg\max} \left\{ \tilde{\mathbf{Q}}(t') \right\}, \]
and the set of the $d$ longest queues $\tilde I_d(t')$ selected by the algorithm, we define:
\begin{align}
    & I_1 := \{ l' \}, \notag \\
    & I_2:= \left \{ l \in \tilde I_d(t') \setminus \{ l^{\prime} \} : \tilde Q_l(t') \geq k(n-d)S_{\max} \right \}, \notag \\
    & I_3:= \left \{ l \in \tilde I_d(t') \setminus \{ l^{\prime} \} : \tilde Q_{l}(t') < k(n-d)S_{\max}  \right \}, \notag \\
    & I_4:= \left \{ l \in [n] \setminus \tilde I_d(t') : \tilde Q_{l}(t') \geq k(n-d)S_{\max} \right \}, \notag \\
    & I_5:= \left \{ l \in [n] \setminus \tilde I_d(t') : \tilde Q_{l}(t') < k(n-d)S_{\max} \right \}. \notag
\end{align}
Note that $I_1 \cup I_2 \cup I_3 = \tilde I_d(t')$, and that $I_4 \cup I_5 = [n] \setminus \tilde I_d(t')$. Using this partition, we bound the drift of $W(\tilde{\mathbf{Q}}(t'))$ as follows:
\begin{align}
    & E[\Delta W(\tilde{\mathbf{Q}}(t'))\ | \  \tilde{\mathbf{Q}}(t')=\mathbf{q}] \notag \\
    & = E[\| \tilde{\mathbf{Q}}(t'+1) \|_2^2 - \| \tilde{\mathbf{Q}}(t') \|_2^2 \  | \  \tilde{\mathbf{Q}}(t')=\mathbf{q} ] \notag \\
    & = E[\| \mathbf{Q}(t+k(n-d)) \|^2 - \| \mathbf{Q}(t) \|^2 \  | \ \mathbf{Q}(t)=\mathbf{q} ] \notag \\ 
    & = E \left [ \sum\limits_{l=1}^{n} \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right )^2 - \sum\limits_{l=1}^{n} Q_{l}(t)^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\ 
    & = E \left [ \sum\limits_{l=1}^{n} \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right )^2 - Q_{l}(t)^2  \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right] \notag \\ 
    & \overset{(a)}{=} E \left[ \left (Q_{l^{\prime}}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l^{\prime}}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l^{\prime}}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l^{\prime}}(t+j) \right )^2 - Q_{l^{\prime}}(t)^2 \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l\in I_2 } \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l\in I_3 } \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l\in I_4 } \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j)\right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l \in I_5 } \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \overset{(b)}{\leq} E \left[ \left (Q_{l^{\prime}}(t) - \sum\limits_{j=0}^{k(n-d)-1}S_{l^{\prime}}(t+j) \right )^2 - Q_{l^{\prime}}(t)^2 \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l\in I_2 } \left [ \left (Q_{l}(t) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l\in I_4 } \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left[ \sum\limits_{ l \in I_5 } \left [ \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) \right )^2 - Q_{l}(t)^2 \right ] \  \middle | \ \mathbf{Q}(t)=\mathbf{q} \right ], \label{eq:stable_expofwq}
\end{align}
where (a) follows from the definition of the partition, (b) follows from the following facts:
\begin{itemize}
    \item[(i)] The $d$ largest queues selected by the algorithm do not receive any arrivals during the $k(n-d)$ time slots, that is, we have $A_{l}(t+j) = 0$ for all $j \in \{ 0,...,k(n-d)-1\}$, for all $l\in I_1 \cup I_2 \cup I_3$.
    \item[(ii)] The queues which have at least $k(n-d)S_{\max}$ jobs in them at time $t$ will have no unused services for the $k(n-d)$ time slots, that is, we have $U_{l}(t+j)=0$ for all $j = \{ 0,...,k(n-d)-1 \}$ for all $l\in I_1 \cup I_2 \cup I_4$.
    \item[(iii)] The number of unused services is smaller than or equal to the number of potential services, that is, we have $ S_{l}(t+j) \geq U_{l}(t+j)$ for all $l\in[n]$ and $j\geq 0$.
\end{itemize}
We now compute the expectation in Equation \eqref{eq:stable_expofwq} for each term separately. For the longest queue $ l^{\prime} $, using the fact that potential services are independent from each other and from past queue lengths, we have
\begin{align}
    & E \left [ \left (Q_{l^{\prime}}(t)  - \sum\limits_{j=0}^{k(n-d)-1}S_{l^{\prime}}(t+j) \right )^2 - Q_{l^{\prime}}(t)^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    &\qquad\qquad\qquad = E \left [ -2 Q_{l^{\prime}}(t) \left ( \sum\limits_{j=0}^{k(n-d)-1}S_{l^{\prime}}(t+j) \right ) + \left ( \sum\limits_{j=0}^{k(n-d)-1}S_{l^{\prime}}(t+j) \right )^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    &\qquad\qquad\qquad = -2 q_{l^{\prime}}k(n-d)\mu_{l^{\prime}} + k^2(n-d)^2\mu_{l^{\prime}}^2+k(n-d)\sigma_{\mu_{l^{\prime}}}^2. \label{eq:stable_longest}
\end{align}
For the queues with indices in $ I_2 $, we have
\begin{align}
    & E \left [ \sum\limits_{ l \in I_2 } \left [ 
        \left (Q_{l}(t) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )^2 - (Q_{l}(t))^2 
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad\qquad= E \left [ \sum\limits_{ l \in I_2 } \left [ 
        -2Q_{l}(t) \left (\sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right ) + \left ( \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )^2 
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad\qquad= \sum\limits_{ l \in I_2 } \left [
        -2 q_lk(n-d)\mu_l + k^2(n-d)^2\mu_l^2+k(n-d)\sigma_{\mu_l}^2
    \right ]. \label{eq:stable_I2}
\end{align}
For the queues with indices in $ I_4 $, we have
\begin{align}
    & E \left [ \sum\limits_{ l \in I_4 } \left [ 
        \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )^2 - (Q_{l}(t))^2 
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad = E \left [ \sum\limits_{ l \in I_4 } \left [ 
        2Q_{l}(t) \left (\sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad\qquad\qquad + E \left [ \sum\limits_{ l \in I_4 } \left [ \left (\sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) \right )^2 
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad = \sum\limits_{ l \in I_4 } \left [
        2q_{l} k \left ( n \lambda-(n-d)\mu_l \right )+ k^2 \left ( n \lambda-(n-d)\mu_l \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_l}^2
    \right ]. \label{eq:stable_I4}
\end{align}
For queues with indices in $ I_5 $, using the fact that their queue lengths are bounded by $ k(n-d)S_{\max} $ by the definition of the partition, we have
\begin{align}
    & E \left [ \sum\limits_{ l \in I_5 } \left [ 
        \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) \right )^2 - (Q_{l}(t))^2 
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad= E \left [ \sum\limits_{ l \in I_5 } \left [ 
        2Q_{l}(t) \left (\sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) \right ) + \left (\sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) \right )^2 
    \right ] \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \qquad\qquad= \sum\limits_{ l\in I_5 } \left [
        2q_{l} k n\lambda + k^2 n^2\lambda^2 + kn\sigma_{\lambda}^2
    \right ] \notag \\
    & \qquad\qquad\leq \sum\limits_{ l\in I_5 } \left [
        2S_{\max}k^2(n-d) n\lambda + k^2 n^2\lambda^2 + kn\sigma_{\lambda}^2
    \right ] \label{eq:stable_I5}
\end{align}
Combining equations \eqref{eq:stable_expofwq}, \eqref{eq:stable_longest}, \eqref{eq:stable_I2}, \eqref{eq:stable_I4}, and \eqref{eq:stable_I5}, we get that
\begin{align}
    E[\Delta W(\tilde{\mathbf{Q}}(t'))\ | \  \tilde{\mathbf{Q}}(t')=\mathbf{q}] & = -2 q_{l^{\prime}}k(n-d)\mu_{l^{\prime}} + k^2(n-d)^2\mu_{l^{\prime}}^2+k(n-d)\sigma_{\mu_{l^{\prime}}}^2 \notag \\
    & \quad + \sum\limits_{ l \in I_2 } \left [ -2 q_l k (n-d)\mu_l + k^2(n-d)^2\mu_l^2+k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l \in I_4 } \left [ 2q_{l} k\left ( n\lambda-(n-d)\mu_l \right )+k^2\left ( n\lambda-(n-d)\mu_l \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l\in I_5 } \left [ 2q_l kn\lambda + k^2 n^2\lambda^2 + kn\sigma_{\lambda}^2 \right ] \notag \\
    & \leq -2 q_{l^{\prime}}k(n-d)\mu_{l^{\prime}} + k^2(n-d)^2\mu_{l^{\prime}}^2+k(n-d)\sigma_{\mu_{l^{\prime}}}^2 \notag \\
    & \quad + \sum\limits_{ l \in I_2 } \left [ -2 q_l k (n-d)\mu_l + k^2(n-d)^2\mu_l^2+k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l \in I_4 } \left [ 2q_{l} k\left ( n\lambda-(n-d)\mu_l \right )+k^2\left ( n\lambda-(n-d)\mu_l \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l\in I_5 } \left [ 2S_{\max}k(n-d) kn\lambda + k^2 n^2\lambda^2 + kn\sigma_{\lambda}^2 \right ] \notag \\
    & \overset{(a)}{=} - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} 2 k \left ( n\lambda-(n-d)\mu_l \right ) q_{l} \notag \\
    & \quad + k^2(n-d)^2\mu_{l^{\prime}}^2+k(n-d)\sigma_{\mu_{l^{\prime}}}^2 \notag \\
    & \quad + \sum\limits_{ l \in I_2 } \left [ k^2(n-d)^2\mu_l^2+k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l \in I_4 } \left [ k^2\left ( n\lambda-(n-d)\mu_l \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\mu}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l\in I_5 } \left [ 2S_{\max}k^2(n-d)n\lambda + k^2n^2\lambda^2 + kn\sigma_{\lambda}^2 \right ] \notag \\
    & \overset{(b)}{\leq} - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} \left. 2 k \left ( n\lambda-(n-d)\mu_l \right ) q_{l} \right. \notag \\
    & \quad + k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\max}^2 \notag \\
    & \quad + (d-1) \left [ k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\max}^2 \right ] \notag \\
    & \quad + (n-d) \left [ k^2\left ( n\lambda + (n-d)\mu_{\max} \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\max}^2 \right ] \notag \\
    & \quad + (n-d) \left [ 2S_{\max}k^2(n-d)n\lambda + k^2 n^2\lambda^2 + kn\sigma_{\lambda}^2 \right ], \label{eq:stable_aveofwx}
\end{align}
where (a) follows from rearranging the terms, and (b) follows from the the definition of the partition, which yields $ |I_2|\leq d-1$, $|I_4| \leq n-d$, and $|I_5| \leq n-d $.

To further simplify the first term in Equation \eqref{eq:stable_aveofwx}, we define two subsets
\begin{align*}
    I_4^+ &:=\{ l\in I_4 : n\lambda-(n-d)\mu_l > 0 \}, \\
    I_4^- &:=\{ l\in I_4 : n\lambda-(n-d)\mu_l \leq 0 \}.
\end{align*}
We then have
\begin{align}
    & - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l} \notag \\
    & = - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4^+} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l} + \sum\limits_{ l\in I_4^-} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l} \notag \\
    & \overset{(a)}{\leq} - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4^+} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l}, \label{eq:stable_drift_I4}
\end{align}
where (a) follows from the definition of $ I_4^+$, and $I_4^-$. We have two different cases.


{\bf Case 1: $| I_4^+ | = 0$. } In this case, Equation \eqref{eq:stable_drift_I4} can be bounded as follows
\begin{align}
    & - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4^+} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l} \notag \\
    & = - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} \notag \\
    &\leq - 2k(n-d)\mu_{\min} q_{l^{\prime}} \notag \\
    & \overset{(a)}{\leq} - \frac{2k(n-d)\mu_{\min}}{n}\| \mathbf{q} \|_1 \notag \\
    & \overset{(b)}{\leq} - \frac{2k(n-d)\mu_{\min}}{n}\| \mathbf{q} \|_2, \label{eq:stable_drift_case1}
\end{align} 
where  (a) follows from the fact that $ q_{l^{'}} \geq \| \mathbf{q} \|_1/n $, and (b) follows from the inequality $ \| \mathbf{x} \|_1 \geq \| \mathbf{x} \|_2 $ for all $ \mathbf{x} \in \mathbb{R}^n $.

{\bf Case 2: $| I_4^+ | > 0$.} In this case, we have $|I_3|=0$. Let
\[ l^{\prime\prime} \in  \argmin\limits_{ l \in I_2 } \{ q_l \} \qquad \text{and} \qquad l^{\prime\prime\prime} \in \underset{ l \in I_4^+}{\arg\max} \{ q_l \}, \]
and let
\begin{align}
    \epsilon^{\prime} & = \min_{I \subseteq [n] \ : \ |I| \geq d+1 } \  \left \{ \frac{1}{|I|-d} \sum_{ l\in I} \mu_l \right \} - \frac{n\lambda}{n-d}, \notag
\end{align} 
which is positive because we assumed that 
\[ n\lambda < \min_{I \subseteq [n] \ : \ |I| \geq d+1 } \  \left\{ \frac{n-d}{|I|-d} \sum_{ l\in I} \mu_l \right\}. \] 
Then, Equation \eqref{eq:stable_drift_I4} can be bounded as follows
\begin{align}
    & - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4^+} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l} \notag \\
    & \overset{(a)}{\leq} -2k(n-d)\mu_{l^{\prime}}q_{l^{\prime}} - 2k\sum\limits_{ l\in I_2} (n-d)\mu_l q_{l^{\prime\prime}} + 2k\sum\limits_{ l\in I_4^+} \left [ n\lambda - (n-d)\mu_l  \right ]q_{l^{\prime\prime\prime}} \notag \\
    & = -2k(n-d)\epsilon^{\prime}  q_{l^{\prime}} - 2k(n-d) \left [ (\mu_{l^{\prime}}-\epsilon^{\prime})q_{l^{\prime}} + \sum\limits_{ l\in I_2} \mu_l q_{l^{\prime\prime}} \right ] + 2k \sum\limits_{ l\in I_4^+} \left [ n\lambda-(n-d)\mu_l \right ]q_{l^{\prime\prime\prime}} \notag \\
    & \overset{(b)}{\leq} -2k(n-d)\epsilon^{\prime} q_{l^{\prime}} - 2k(n-d) \left ( \sum\limits_{ l\in I_1 \cup I_2} \mu_l - \epsilon^{\prime} \right ) q_{l^{\prime\prime}} + 2k \sum\limits_{ l\in I_4^+} n\lambda q_{l^{\prime\prime\prime}} -2k(n-d)\sum\limits_{ l\in I_4^+} \mu_lq_{l^{\prime\prime\prime}} \notag \\
    & \overset{(c)}{\leq} -2k(n-d)\epsilon^{\prime} q_{l^{\prime}} - 2k(n-d) \left ( \sum\limits_{ l\in I_1 \cup I_2} \mu_l - \epsilon^{\prime} \right ) q_{l^{\prime\prime\prime}} + 2k \sum\limits_{ l\in I_4^+} n\lambda q_{l^{\prime\prime\prime}} -2k(n-d)\sum\limits_{ l\in I_4^+} \mu_lq_{l^{\prime\prime\prime}} \notag \\
    & = -2k(n-d)\epsilon^{\prime} q_{l^{\prime}} - 2k(n-d) \left ( \sum\limits_{ l\in I_1 \cup I_2 \cup I_4^+} \mu_l - \epsilon^{\prime} \right ) q_{l^{\prime\prime\prime}} + 2k \sum\limits_{ l\in I_4^+} n\lambda q_{l^{\prime\prime\prime}} \notag \\
    & = -2k(n-d)\epsilon^{\prime} q_{l^{\prime}} - 2k \left [ (n-d) \left ( \sum\limits_{ l\in I_1 \cup I_2 \cup I_4^+} \mu_l - \epsilon^{\prime} \right ) - \sum\limits_{ l\in I_4^+} n\lambda \right ] q_{l^{\prime\prime\prime}}, \label{eq:stable_drift_case2}
\end{align} 
where (a) follows from the definitions of $ l^{\prime\prime} $ and $ l^{\prime\prime\prime} $, and (b) and (c) follow from the fact that $ q_{l^{\prime}} \geq q_{l^{\prime\prime}} \geq q_{l^{\prime\prime\prime}}$ by the definition of the partition. Since $I_4 \cup I_5 = [n]\backslash I_d(t)$ and $\emptyset \neq I_4^+ \subset I_4$, we have $| I_4^+ | = n-d-| I_5 |-|I_4^-| \in \{ 1,...,n-d\} $. Therefore, the last term in Equation \eqref{eq:stable_drift_case2} can be rewritten as follows:
\begin{align}
    (n-d) \left ( \sum\limits_{ l\in I_1 \cup I_2 \cup I_4^+} \mu_l - \epsilon^{\prime} \right ) - \sum\limits_{ l\in I_4^+} n\lambda & = (n-d) \sum\limits_{ l\in I_1 \cup I_2 \cup I_4^+} \mu_l - \sum\limits_{ l\in I_4^+}  n\lambda - (n-d)\epsilon^{\prime} \notag \\
    & = (n-d) \sum\limits_{ l\in I_1 \cup I_2 \cup I_4^+} \mu_l - (n-d-| I_5 |-|I_4^-|) n\lambda - (n-d)\epsilon^{\prime} \notag \\
    & = (n-d) \sum\limits_{ l\in I_1 \cup I_2 \cup I_4^+} \mu_l \notag \\ 
    & \quad - (n-d-| I_5 |-|I_4^-|) \left [ n\lambda + \frac{n-d}{(n-d-| I_5 |-|I_4^-|)} \epsilon^{\prime} \right ]. \label{eq:stable_case_I4+}
\end{align}
We now claim that this is positive. Let $ I_{m^*} $ be an optimal solution for the optimization problem that defines the capacity region, and let us reorder the service rates $ \{ \mu_1, \mu_2,...,\mu_n \} $ into a descending order $\mu_1^{\prime} \geq \mu_2^{\prime} \geq \cdots  \geq \mu_n^{\prime}$. We then have
\begin{align}
    n\lambda + \frac{n-d}{(n-d-| I_5 |-|I_4^-|)} \epsilon^{\prime} & < n\lambda + (n-d)\epsilon^{\prime} \notag \\
    & = \min_{I \subseteq [n] \ : \ |I| \geq d+1 } \  \left \{ \frac{n-d}{|I|-d} \sum_{ l\in I} \mu_l \right \} \notag \\
    & = \frac{n-d}{|I_{m^{*}}|-d}\sum\limits_{l=n-|I_{m^{*}}|+1}^{n} \mu_l^{\prime} \notag \\
    & \overset{(a)}{\leq} \frac{n-d}{n-| I_5 |-|I_4^-|-d} \sum\limits_{l=| I_5 |+|I_4^-|+1}^{n} \mu_l^{\prime} \notag \\ 
    % & \overset{(b)}{\leq} \frac{n-d}{n-| I_5 |-|I_4^-|-d} \sum\limits_{l=1}^{n-| I_5 |-|I_4^-|} \mu_l^{\prime} \notag \\
    & \overset{(b)}{\leq} \frac{n-d}{n-| I_5 |-|I_4^-|-d} \sum\limits_{l\in I_1 \cup I_2 \cup I_4^+} \mu_l, \notag
\end{align}
where (a) follows from the fact that $ n-| I_5 |-|I_4^-| \geq d+1$, and (b) follows from the fact that $ |I_1 \cup I_2 \cup I_4^+| = n-| I_5 |-|I_4^+|$ and $\mu_1^{\prime} \geq \mu_2^{\prime} \geq \cdots  \geq \mu_n^{\prime}$. It follows that \eqref{eq:stable_case_I4+} is positive, and thus Equation \eqref{eq:stable_drift_case2} can be further bounded by
\begin{align}
    -2k(n-d)\epsilon^{\prime} q_{l^{\prime}} - 2k \left [ (n-d) \left ( \sum\limits_{ l\in I_1 + I_2 + I_4^+} \mu_l - \epsilon^{\prime} \right ) - \sum\limits_{ l\in I_4^+} n\lambda \right ] q_{l^{\prime\prime\prime}}  & \leq - 2k(n-d)\epsilon^{\prime} q_{l^{\prime}} \notag \\
    & \leq - \frac{2\epsilon' (n-d)k}{n}\| \mathbf{q} \|_1 \notag \\
    & \leq - \frac{2\epsilon' (n-d)k}{n}\| \mathbf{q} \|_2. \notag 
\end{align}
Combining this with Equation \eqref{eq:stable_drift_case1}, we get that Equation \eqref{eq:stable_drift_I4} can be bounded as follows:
\begin{align}
    & - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} 2k \left ( n\lambda - (n-d)\mu_l \right ) q_{l} \leq - \frac{2 \min\{\mu_{\min},\,\epsilon'\} (n-d)k}{n}\| \mathbf{q} \|_2. \notag 
\end{align}
Finally, we have
\begin{align}
    E[\Delta W(\mathbf{Q}(t))\ | \  \mathbf{Q}(t)=\mathbf{q}]  & \leq - \frac{2 \min\{\mu_{\min},\,\epsilon'\} (n-d)k}{n}\| \mathbf{q} \|_2  + C_1 \label{eq:stable_wx}
\end{align}
where
\begin{align*}
     C_1 &= k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\max}^2 + (d-1) \left [ k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\max}^2 \right ] \notag \\
    & \quad \quad +  (n-d) \left [ k^2\left ( n\lambda + (n-d)\mu_{\max} \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\max}^2 \right ] \notag \\ 
    & \quad \quad + (n-d) \left [ 2S_{\max}k^2(n-d)n\lambda + k^2n^2\lambda^2 + kn\sigma_{\lambda}^2 \right ] \notag
\end{align*}
Since this drift is negative for all $\| \mathbf{q} \|_2$ large enough, the Foster-Lyapunov Theorem implies that the Markov chain $\{\tilde{\mathbf{X}}(t)\}_{t\geq 0} $ is positive recurrent. \\



We now prove the necessary condition. Suppose that
\begin{align}
    & n\lambda \geq \min_{I \subseteq [n] \ : \ |I| \geq d+1 } \  \left\{ \frac{n-d}{|I|-d} \sum_{ l\in I} \mu_l \right\}, \notag
\end{align}
and let $ I_{m^{*}} $ be an optimal solution. Let us reorder the service rates $\mu_1, \mu_2,...,\mu_n$ into a descending order $\mu_1^{\prime} \geq \mu_2^{\prime}\geq \cdots \geq \mu_n^{\prime}$. Let $\lambda_l$ be the average arrival rate to the $l$-th queue. Under the $k$-SLQ-$d$ policy, queues can receive at most one arrival every $n-d$ time slots. That is, we have $\lambda_l \leq n\lambda/(n-d)$, for all $l \in [n]$. Then, we have
\begin{align*}
    \sum\limits_{l=n-|I_{m^{*}}|+1}^n \mu_l^{\prime} - \sum\limits_{l=n-|I_{m^{*}}|+1}^{n}\lambda_l & = \frac{|I_{m^*}|-d}{n-d}\frac{n-d}{|I_{m^*}|-d} \sum\limits_{l=n-|I_{m^{*}}|+1}^n \mu_l^{\prime} - \sum\limits_{l=n-|I_{m^{*}}|+1}^{n}\lambda_l \\
    & \overset{(a)}{\leq} \frac{|I_{m^*}|-d}{n-d}n\lambda - \sum\limits_{l=n-|I_{m^{*}}|+1}^{n}\lambda_l \\
    & = \left ( 1 - \frac{n-|I_{m^*}|}{n-d} \right ) n \lambda - \sum\limits_{l=n-|I_{m^{*}}|+1}^{n}\lambda_l \\
    & \overset{(b)}{=} \sum\limits_{l=1}^{n-|I_{m^{*}}|} \lambda_l - \frac{n-|I_{m^*}|}{n-d}n\lambda \\
    & \leq 0,
\end{align*}
where (a) follows from the assumption above, and (b) follows from the fact that $ \sum_{l=1}^n \lambda_l = n\lambda $. Finally, note that the queue lengths can be lower bounded as
\begin{align}
    Q_{n-|I_{m^{*}}|+1}(t)+...+Q_n(t) & \geq \sum\limits_{i=1}^{t}\sum\limits_{l=n-|I_{m^{*}}|+1}^{n} (A_l[i] - S_l[i]), \notag
\end{align}
where the right hand side is a random walk with non-negative bias. Therefore, under both scenarios, the Markov chain $ \{\mathbf{X}(t) \}_{t\geq 0}$ cannot be positive recurrent.


\section{Proof of Corollary \ref{co_our:condition}} \label{prf:cor_stableregion}

First we prove the sufficient condition. It is enough to prove that, for any subset $I_m \subset [n]$ with $|I_m|\geq d+1$, we have
\begin{align}
    \frac{n-d}{|I_m|-d} \sum_{ l\in I_m} \mu_l \geq \sum\limits_{l=1}^{n} \mu_l. \notag 
\end{align}
Let $ I_m \subset [n]$, with $|I_m|=m \in \{d+1,...,n-1\}$, be the feasible solution for the objective function and reorder the service rates $\mu_1, \mu_2,...,\mu_n$ into a descending order $\mu_1^{\prime} \geq \mu_2^{\prime} \geq \cdots \geq \mu_n^{\prime}$. We have
\begin{align}
    \frac{n-d}{|I_m|-d} \sum_{ l\in I_m} \mu_l - \sum\limits_{l=1}^{n} \mu_l & \overset{(a)}{\geq} \frac{n-d}{|I_m|-d} \sum\limits_{l=n-|I_m|+1}^{n} \mu_l^{\prime} - \sum\limits_{l=1}^{n} \mu_l^{\prime} \notag \\
    & = \frac{n-d}{|I_m|-d} \left ( \sum\limits_{l=n-|I_m|+1}^{n} \mu_l^{\prime} + \sum\limits_{l=1}^{n-|I_m|} \mu_l^{\prime} - \sum\limits_{l=1}^{n-|I_m|} \mu_l^{\prime} \right ) - \sum\limits_{l=1}^{n} \mu_l^{\prime} \notag \\
    & = \frac{n-d}{|I_m|-d} \left ( \sum\limits_{l=1}^{n} \mu_l^{\prime} - \sum\limits_{l=1}^{n-|I_m|} \mu_l^{\prime} \right ) - \sum\limits_{l=1}^{n} \mu_l^{\prime} \notag \\
    & = \frac{n-|I_m|}{|I_m|-d}\sum\limits_{l=1}^{n} \mu_l^{\prime} - \frac{n-d}{|I_m|-d} \sum\limits_{l=1}^{n-|I_m|} \mu_l^{\prime} \notag \\ 
    & \overset{(b)}{\geq} \frac{n-|I_m|}{|I_m|-d}\sum\limits_{l=1}^{n} \mu_l^{\prime} - \frac{n-d}{|I_m|-d} (n-|I_m|) \mu_1^{\prime} \notag \\ 
    & = \frac{n-|I_m|}{|I_m|-d} \left [ \sum\limits_{l=1}^{n} \mu_l - (n-d) \mu_{\max} \right ] \notag \\
    & = \frac{n-m}{m-d} \left [ \sum\limits_{l=1}^{n} \mu_l - (n-d) \mu_{\max} \right ] \notag \\ 
    & \geq 0, \notag 
\end{align}
where (a) follows from the descending order of the service rates, and (b) follows from the fact that $ \mu_1^{\prime}=\mu_{\max} \geq \mu_l^{\prime}$, for all $l\geq 1$.\\

We now prove the necessary condition by contradiction. Suppose that the stability region is $n \lambda < \sum_{l=1}^{n} \mu_l $, and let us assume that $ \sum_{l=1}^{n} \mu_l < (n-d)\mu_{\max} $ holds. We define $ \epsilon := \sum_{l=1}^{n} \mu_l-n \lambda $, and reorder the service rates $\mu_1, \mu_2,...,\mu_n$ into a descending order $\mu_1^{\prime} \geq \mu_2^{\prime} \geq \cdots \geq \mu_n^{\prime}$. Note that the condition $ \sum_{l=1}^{n} \mu_l < (n-d)\mu_1' $ implies that
\begin{align}
    \frac{n-d}{n-d-1} \sum\limits_{l=2}^n \mu_l^{\prime} - \left ( \sum_{l=1}^n \mu_l^{\prime} - \epsilon \right ) & =  \frac{n-d}{n-d-1} \left ( \sum\limits_{l=2}^n \mu_l^{\prime} + \mu_1' -\mu_1' \right ) - \sum_{l=1}^n \mu_l^{\prime} + \epsilon \notag \\
    & = \frac{n-d}{n-d-1} \sum_{l=1}^n \mu_l^{\prime} - \sum_{l=1}^n \mu_l^{\prime} - \frac{n-d}{n-d-1} \mu_1' + \epsilon \notag \\
    & = \frac{1}{n-d-1} \sum_{l=1}^n \mu_l^{\prime} - \frac{n-d}{n-d-1} \mu_1' + \epsilon \notag \\
    & < 0, \label{eq:mu_for_small_epsilon}
\end{align}
for all $\epsilon$ small enough. Now let $ \lambda_l $ be the average arrival rate to the $l$-th queue. For all $\epsilon$ small enough, we have
\begin{align*}
    \sum\limits_{l=2}^n \mu_l^{\prime} - \sum\limits_{l=2}^{n}\lambda_l & = \frac{n-d-1}{n-d}\frac{n-d}{n-d-1} \sum\limits_{l=2}^n \mu_l^{\prime} - \sum\limits_{l=2}^{n}\lambda_l \\
    & \overset{(a)}{<} \frac{n-d-1}{n-d} \left (\sum_{l=1}^n \mu_l^{\prime} - \epsilon \right )  - \sum\limits_{l=2}^{n}\lambda_l \\
    & = \frac{n-d-1}{n-d} n\lambda  - \sum\limits_{l=2}^{n}\lambda_l \\
    & = \left ( 1 - \frac{1}{n-d} \right ) n \lambda - \sum\limits_{l=2}^{n}\lambda_l \\
    & = \lambda_1 - \frac{1}{n-d}n\lambda \\
    & \overset{(b)}{\leq} 0,
\end{align*}
where (a) follows from Equation \eqref{eq:mu_for_small_epsilon}, and (b) follows from the fact that under the $k$-SLQ-$d$ policy, queues receive at most one arrival every $n-d$ time slots, and thus $\lambda_l \leq n\lambda/(n-d)$, for all $l \in [n]$. It follows that
\begin{align}
    Q_2(t)+Q_3(t)+...+Q_n(t) & \geq \sum\limits_{i=1}^{t}\sum\limits_{l=2}^{n} (A_l[i] - S_l[i]), \notag 
\end{align}
where the right hand side is a random walk with positive bias. Therefore, the Markov chain $ \{\mathbf{X}(t) \}_{t\geq 0}$ is transient. 


\section{Conclusion}
In this paper we introduce and analyze a new dispatching policy dubbed $k$-SLQ-$d$, which is throughput and delay optimal in classical and many-server heavy-traffic under certain conditions on the number of skipped servers $d$. Moreover, this policy can be implemented with an arbitrarily small communication overhead (by choosing the number of rounds $k$ to be sufficiently large) without sacrificing the throughput or delay optimality in heavy traffic. Moreover, our policy showcases how it is enough to skip the longest queue in order to obtain excellent delay performance, and that this can perform even better than sending jobs to the shortest queue when the communication overhead is extremely low.



