\section{Proof of Theorem \ref{thm_our:SSC}} \label{prf:thm_SSC}
Let us define the Lyapunov Functions
\begin{align*}
    V_{\perp}(\mathbf{Q}(t)) &= \| \mathbf{Q}_{\perp}(t) \|_2, \\
    W(\mathbf{Q}(t)) &= \| \mathbf{Q}(t) \|_2^2, \\
    W_{\parallel}(\mathbf{Q}(t)) &= \| \mathbf{Q}_{\parallel}(t) \|_2^2.
\end{align*}
Given that the dispatcher collects the queue length vector every $k(n-d)$ time slots under our $k$-SLQ-$d$ policy, we define a new Markov chain 
\[ \tilde{\mathbf{X}}(t) := \Big( \tilde{\mathbf{Q}}(t), \tilde I_d(t), \tilde I_R(t), \tilde N_R(t)\Big) \]
such that
\[ \tilde{\mathbf{X}}(t)=\mathbf{X}(k(n-d)t) \]
for all $t\geq 0$. We also define the drift operator $\Delta$ by
\begin{align}
    \Delta V_{\perp}(\mathbf{Q}(t)) & := V(\mathbf{Q}_{\perp}(t+1))-V(\mathbf{Q}_{\perp}(t)) \notag \\
    \Delta W_{\parallel}(\mathbf{Q}(t)) & := W(\mathbf{Q}_{\parallel}(t+1))-W(\mathbf{Q}_{\parallel}(t)) \notag 
\end{align}

Fix $t\geq 0$ such that $t$ is a multiple of $k(n-d)$, and let $t'=t/k(n-d)$. We first show that $\Delta V_{\perp}(\tilde{\mathbf{Q}}(t'))$ is uniformly absolutely bounded, as follows.
\begin{align}
    | \Delta V_{\perp}(\tilde{\mathbf{Q}}(t')) | & = | \| \tilde{\mathbf{Q}}_{\perp}(t'+1) \|_2 - \| \tilde{\mathbf{Q}}_{\perp}(t') \|_2 | \notag \\
    & \overset{(a)}{\leq} \| \tilde{\mathbf{Q}}_{\perp}(t'+1) - \tilde{\mathbf{Q}}_{\perp}(t') \|_2 \notag \\
    & \overset{(b)}{=} \| \tilde{\mathbf{Q}}(t'+1) - \tilde{\mathbf{Q}}_{\parallel}(t'+1) - \tilde{\mathbf{Q}}(t') + \tilde{\mathbf{Q}}_{\parallel}(t')  \|_2 \notag \\
    & \overset{(c)}{\leq} \| \tilde{\mathbf{Q}}(t'+1) - \tilde{\mathbf{Q}}(t') \|_2 + \| \tilde{\mathbf{Q}}_{\parallel}(t'+1) - \tilde{\mathbf{Q}}_{\parallel}(t')  \|_2 \notag \\
    & \overset{(d)}{\leq} 2 \| \tilde{\mathbf{Q}}(t'+1) - \tilde{\mathbf{Q}}(t') \|_2 \notag \\
    & \overset{(e)}{\leq} 2 \| \tilde{\mathbf{Q}}(t'+1) - \tilde{\mathbf{Q}}(t') \|_1 \notag \\
    & = 2 \| \mathbf{Q}(t+k(n-d)) - \mathbf{Q}(t) \|_1 \notag \\
    & = 2 \sum\limits_{l=1}^{n} \left | \left (Q_{l}(t) + \sum\limits_{j=0}^{k(n-d)-1}A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1}S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1}U_{l}(t+j) \right ) - \left (Q_{l}(t) \right ) \right | \notag \\
    & = 2 \sum\limits_{l=1}^{n} \left | \sum\limits_{j=0}^{k(n-d)-1} A_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1} S_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1} U_{l}(t+j) \right | \notag \\
    & \leq 2 \sum\limits_{l=1}^{n} \left [ \left | \sum\limits_{j=0}^{k(n-d)-1} A_{l}(t+j) \right | + \left | \sum\limits_{j=0}^{k(n-d)-1} S_{l}(t+j) - \sum\limits_{j=0}^{k(n-d)-1} U_{l}(t+j) \right | \right ] \notag \\
    & \leq 2 \sum\limits_{l=1}^{n} \left [ \sum\limits_{j=0}^{k(n-d)-1} A_{l}(t+j) + \sum\limits_{j=0}^{k(n-d)-1} S_{l}(t+j)  \right ] \notag \\
    & \leq 2k(n-d)n(A_{\max}+S_{\max}), \notag
\end{align}
where (a) follows from the fact that $ | \| x \|_2 - \| y \|_2 | \leq \| x-y \|_2$ for $ x,y\in\mathbb{R}^L $, (b) follows from the fact that $ \mathbf{Q}_{\perp}(t) + \mathbf{Q}_{\parallel}(t) = \mathbf{Q}(t) $, (c) follows from the triangle inequality, (d) follows from the fact that $\mathbf{Q}_{\parallel}(t)$ is the projection of $\mathbf{Q}(t)$ onto $c$, which implies that $ \| \mathbf{Q}_{\parallel}(t'+1) - \mathbf{Q}_{\parallel}(t') \|_2 \leq \| \mathbf{Q}(t'+1) - \mathbf{Q}(t') \|_2 $, and (e) follows from the fact that $\| x \|_1 \geq \| x \|_2$. The remaining equalities and inequalities follow the same way as in the derivation of Equation \eqref{eq:absolutebound}.\\ 

We now show that $ \Delta V_{\perp}(\tilde{\mathbf{Q}}(t')) $ can be bounded by a function of $ \Delta W(\tilde{\mathbf{Q}}(t')) $ and $ \Delta W_{\parallel}(\tilde{\mathbf{Q}}(t')) $.
\begin{align}
    \Delta V_{\perp}(\tilde{\mathbf{Q}}(t')) & = \| \tilde{\mathbf{Q}}_{\perp}(t'+1) \|_2 - \| \tilde{\mathbf{Q}}_{\perp}(t') \|_2 \notag \\
    & = \sqrt{\| \tilde{\mathbf{Q}}_{\perp}(t'+1) \|_2^2} - \sqrt{\| \tilde{\mathbf{Q}}_{\perp}(t') \|_2^2} \notag \\
    & \overset{(a)}{\leq} \frac{1}{2\| \tilde{\mathbf{Q}}_{\perp}(t') \|_2}\left ( \| \tilde{\mathbf{Q}}_{\perp}(t'+1) \|_2^2 - \| \tilde{\mathbf{Q}}_{\perp}(t') \|_2^2 \right ) \notag \\
    & \overset{(b)}{=} \frac{1}{2\| \tilde{\mathbf{Q}}_{\perp}(t') \|_2}\left ( \| \tilde{\mathbf{Q}}(t'+1) \|_2^2 - \| \tilde{\mathbf{Q}}_{\parallel}(t'+1) \|_2^2 - \| \tilde{\mathbf{Q}}(t') \|_2^2 + \| \tilde{\mathbf{Q}}_{\parallel}(t') \|_2^2 \right ) \notag \\
    & = \frac{1}{2\| \tilde{\mathbf{Q}}_{\perp}(t') \|_2} \Big[\Delta W(\tilde{\mathbf{Q}}(t')) -\Delta W_{\parallel}(\tilde{\mathbf{Q}}(t')) \Big], \label{eq:difference_drifts}
\end{align}
where (a) follows from the fact that $ f(x)=\sqrt{x} $ is concave for $ x \geq 0 $, and thus $ f(y) - f(x)\leq (y-x)f^{\prime}(x) $, and (b) follows from the Pythagorean theorem.\\

We now proceed to bound the drift term $E[\Delta W(\tilde{\mathbf{Q}}(t'))\ | \ \tilde{\mathbf{Q}}(t') = \mathbf{q}] $. As it was shown in the proof of Theorem \ref{prf:thm_stable} (cf. Equation \eqref{eq:stable_aveofwx}), we have
\begin{align}
    & E\left[\Delta W\left(\tilde{\mathbf{Q}}(t')\right)\ | \ \tilde{\mathbf{Q}}(t')=\mathbf{q} \right] \notag \\ 
    & \leq -2 q_{l^{\prime}}k(n-d)\mu_{l^{\prime}} + k^2(n-d)^2\mu_{l^{\prime}}^2+k(n-d)\sigma_{\mu_{l^{\prime}}}^2 \notag \\
    & \quad + \sum\limits_{ l \in I_2 } \left [ -2 q_l k (n-d)\mu_l + k^2(n-d)^2\mu_l^2+k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l \in I_4 } \left [ 2q_{l} k\left ( \sum\limits_{i=1}^{n} \mu_i -\epsilon-(n-d)\mu_l \right )+k^2\left ( \sum\limits_{i=1}^{n}\mu_i - \epsilon-(n-d)\mu_l \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l\in I_5 } \left [ 2q_l k\left ( \sum\limits_{i=1}^{n}\mu_i -\epsilon \right ) + k^2\left ( \sum\limits_{i=1}^{n}\mu_i - \epsilon \right )^2 + kn \sigma_{\lambda}^2 \right ] \notag \\
    & = - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} 2 k \left ( \sum\limits_{i=1}^{n} \mu_i -\epsilon-(n-d)\mu_l \right ) q_{l} + \sum\limits_{ l\in I_5} 2 k \left ( \sum\limits_{i=1}^{n} \mu_i -\epsilon \right ) q_{l} \notag \\
    & \quad + k^2(n-d)^2\mu_{l^{\prime}}^2+k(n-d)\sigma_{\mu_{l^{\prime}}}^2 \notag \\
    & \quad + \sum\limits_{ l \in I_2 } \left [ -2 q_l k (n-d)\mu_l + k^2(n-d)^2\mu_l^2+k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l \in I_4 } \left [ k^2\left ( \sum\limits_{i=1}^{n}\mu_i - \epsilon-(n-d)\mu_l \right )^2 + kn\sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_l}^2 \right ] \notag \\
    & \quad + \sum\limits_{ l\in I_5 } \left [ k^2\left ( \sum\limits_{i=1}^{n}\mu_i - \epsilon \right )^2 + kn \sigma_{\lambda}^2 \right ]. \label{eq:ssc_aveofssc}
\end{align}

The first term in Equation \eqref{eq:ssc_aveofssc} can be further bounded as follows:
\begin{align}
    & - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} 2k \left ( \sum\limits_{i=1}^{n} \mu_i -\epsilon-(n-d)\mu_l \right ) q_{l} + \sum\limits_{ l\in I_5} 2k \left ( \sum\limits_{i=1}^{n} \mu_i -\epsilon \right ) q_{l} \notag \\
    & = - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} -2k \sum\limits_{ l\in I_2 \cup I_3} (n-d)\mu_l q_{l} + 2k\sum\limits_{ l\in I_4 \cup I_5} \left ( \sum\limits_{i=1}^{n} \mu_i -\epsilon - (n-d)\mu_l \right ) q_{l} + 2k\sum\limits_{ l\in I_3 \cup I_5} \left ( n-d \right ) \mu_l q_{l} \notag \\ 
    & = - 2k(n-d) \epsilon \frac{ \| \mathbf{q} \|_1 }{n} - 2k(n-d) \left ( \mu_{l^{\prime}} - \frac{\epsilon}{n} \right) q_{l^{\prime}} -2k(n-d) \sum\limits_{ l\in I_2 \cup I_3} \left (\mu_l - \frac{\epsilon}{n} \right ) q_{l} \notag \\
    & \quad - 2k (n-d) \sum\limits_{ l\in I_4 \cup I_5} \left [ \mu_l - \left (\sum\limits_{i=1}^{n} \mu_i -\epsilon \right) \frac{1}{n-d} - \frac{\epsilon}{n} \right ] q_{l} + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & = - \frac{2 \epsilon k(n-d)}{n} \| \mathbf{q} \|_1  - 2k(n-d) \sum\limits_{l=1}^n \beta_l q_l + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l}, \label{eq:ssc_defbeta}
\end{align}
where
\begin{align*}
    \beta_l = \left \{ \begin{array}{ll}
        \mu_l - \frac{\epsilon}{n}, & l \in \tilde{I_d}(t^{\prime}) \\
        \mu_l - \left (\sum\limits_{i=1}^{n} \mu_i -\epsilon \right) \frac{1}{n-d} - \frac{\epsilon}{n}, & l \in [n] \setminus \tilde{I_d}(t^{\prime})
    \end{array} \right.
\end{align*}
In particular, note that $\sum_{l=1}^n \beta_l = 0$. Equation \eqref{eq:ssc_defbeta} can be rearranged as follows:
\begin{align}
    & - \frac{2 \epsilon k(n-d)}{n} \| \mathbf{q} \|_1  - 2k(n-d) \sum\limits_{l=1}^n \beta_l q_l + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & = - \frac{2 \epsilon k(n-d)}{n} \| \mathbf{q} \|_1 - 2k(n-d)\beta_1(q_1-q_2) - 2k(n-d) \left ( \sum\limits_{r=1}^2 \beta_r \right ) (q_2 - q_3) \notag \\ 
    & \quad - ... - 2k(n-d) \left ( \sum\limits_{r=1}^{n-1} \beta_r \right ) (q_{n-1} - q_n) - 2k(n-d) \left ( \sum\limits_{r=1}^{n} \beta_r \right ) q_n + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & = - \frac{2 \epsilon k(n-d)}{n} \| \mathbf{q} \|_1 - 2k(n-d) \sum\limits_{l=1}^{n-1} \left [ \left( \sum\limits_{r=1}^{l} \beta_r \right )(q_l - q_{l+1}) \right ] + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \label{eq:ssc_sumbeta}
\end{align}
We now bound $ \sum_{r=1}^l \beta_r $ for two different cases.\\

{\bf Case 1:} If $ 1\leq l \leq d$, we have:
\begin{align*}
    \sum_{r=1}^l \beta_r & = \sum\limits_{r=1}^l \left( \mu_r - \frac{\epsilon}{n} \right) \\
    & \geq \sum\limits_{r=1}^l \mu_r - \epsilon \\
    & \geq \mu_{\min} - \epsilon \\
    & > 0
\end{align*}
Where in the last inequality we used that $\epsilon < \mu_{\min}$.\\

{\bf Case 2:} If $d+1\leq l \leq n-1 $, we have:
\begin{align*}
    \sum_{r=1}^l \beta_r & = \sum\limits_{r=1}^d \left( \mu_r - \frac{\epsilon}{n} \right) + \sum\limits_{r=d+1}^l \left( \mu_r - \left( \sum\limits_{i=1}^n \mu_i - \epsilon \right) \frac{1}{n-d} - \frac{\epsilon}{n} \right) \\
    & = \sum\limits_{r=1}^l \mu_r - \left ( \sum\limits_{i=1}^n \mu_i \right ) \frac{l-d}{n-d} + \epsilon \left ( \frac{l-d}{n-d} - \frac{l}{n} \right ) \\
    & = \sum\limits_{i=1}^n \mu_i \left ( \frac{\sum\limits_{r=1}^l \mu_r }{\sum\limits_{i=1}^n \mu_i} - \frac{l-d}{n-d} \right ) + \epsilon \left ( \frac{l-d}{n-d} - \frac{l}{n} \right ) \\
    & = \sum\limits_{i=1}^n \mu_i \left [ 1 - \frac{\sum\limits_{r=l+1}^n \mu_r }{\sum\limits_{i=1}^n \mu_i} - \left ( 1 - \frac{n-l}{n-d} \right ) \right ] + \epsilon \left ( \frac{l-d}{n-d} - \frac{l}{n} \right ) \\
    & = \sum\limits_{i=1}^n \mu_i \left ( \frac{n-l}{n-d} - \frac{\sum\limits_{r=l+1}^n \mu_r }{\sum\limits_{i=1}^n \mu_i} \right ) + \epsilon \left ( \frac{l-d}{n-d} - \frac{l}{n} \right ) \\
    & \geq \sum\limits_{i=1}^n \mu_i \left ( \frac{n-l}{n-d} - \frac{ (n-l) \mu_{max} }{\sum\limits_{i=1}^n \mu_i} \right ) + \epsilon \left ( \frac{l-d}{n-d} - \frac{l}{n} \right ) \\
    & \geq \sum\limits_{i=1}^n \mu_i \left ( \frac{n-l}{n-d} - \frac{ (n-l) \mu_{max} }{\sum\limits_{i=1}^n \mu_i} \right ) - \epsilon \\
    & \overset{(1)}{\geq} \sum\limits_{i=1}^n \mu_i \left ( \frac{1}{n-d} - \frac{ \mu_{max} }{\sum\limits_{i=1}^n \mu_i} \right ) - \epsilon \\
    & = \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i - \mu_{\max} - \epsilon \\
    & \overset{(2)}{>} 0,
\end{align*}
where (1) follows from Equation \eqref{eq:d_large_enough}, and (2) follows from the fact that $\epsilon < \sum_{i=1}^n \mu_i / (n-d) - \mu_{\max}$.\\

Let $\epsilon$ be such that
\[ \epsilon < \frac{1}{2}\min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \}. \]
Then, Equation \eqref{eq:ssc_sumbeta} can be further bounded as follows:
\begin{align} 
    & - \frac{2 \epsilon k(n-d)}{n} \| \mathbf{q} \|_1 - 2k(n-d) \sum\limits_{l=1}^{n-1} \left [ \left( \sum\limits_{r=1}^{l} \beta_r \right )(q_l - q_{l+1}) \right ] + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & \overset{(a)}{\leq} - \frac{2 \epsilon k(n-d)}{n} \| \mathbf{q} \|_1 -2k(n-d) \left ( \min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \} - \epsilon \right )(q_1 - q_n) + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & \overset{(b)}{\leq} - \frac{ 2 \epsilon k(n-d)}{\sqrt{n}} \| \mathbf{q_{\parallel}} \|_2 -2k(n-d) \left ( \min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \} - \epsilon \right )(q_1 - q_n) + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & \overset{(c)}{\leq} - \frac{ 2 \epsilon k(n-d)}{\sqrt{n}} \| \mathbf{q_{\parallel}} \|_2 - \frac{2k(n-d) \left ( \min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \} - \epsilon \right )}{\sqrt{n}} \| \mathbf{q}_{\perp} \|_2 + 2k (n-d) \sum\limits_{ l\in I_3 \cup I_5} \mu_l q_{l} \notag \\
    & \overset{(d)}{\leq} - \frac{ 2 \epsilon k(n-d)}{\sqrt{n}}v \| \mathbf{q_{\parallel}} \|_2 - \frac{2k(n-d) \left ( \min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \} - \epsilon \right )}{\sqrt{n}} \| \mathbf{q}_{\perp} \|_2 \notag \\
    & \quad + 2k^2(n-1)(n-d)^2 \mu_{\max}S_{\max}, \label{eq:SSC_waytodrift}
\end{align}
where (a) follows from the definition of $\epsilon$, (b) follows from the fact that $ \| \mathbf{q} \|_1/n = \sqrt{n(\mathbf{q}_{\Sigma}(t)/n)^2}/\sqrt{n} = \| \mathbf{q}_{\parallel} \|_2/\sqrt{n} $, (c) follows from the definition of $\| q_{\perp} \|_2$ and the fact that $q_1 \geq q_l$ for all $l \in [n]$ and $ (\sum_{s=1}^n q_s) / n \geq q_1$, which implies
\begin{align*}
    \| \mathbf{q}_{\perp} \|_2^2 = \sum\limits_{l=1}^n \left ( q_l -\frac{\sum\limits_{s=1}^n q_s}{n} \right )^2 \leq n (q_1 - q_n)^2,
\end{align*} 
and (d) follows from the fact that $ |I_3|+| I_5 | \leq n-1 $ and $ q_l \leq k(n-d)S_{\max}$ for all $l \in I_3 \cup I_5 $.\\

Combining equations \eqref{eq:ssc_aveofssc} and \eqref{eq:SSC_waytodrift}, we get
\begin{align}
    & E[\Delta W(\tilde{\mathbf{Q}}(t'))\ | \ \tilde{\mathbf{Q}}(t')=q] \notag \\
    & \leq - 2k(n-d)\mu_{l^{\prime}} q_{l^{\prime}} - \sum\limits_{ l\in I_2} 2k(n-d)\mu_l q_{l} + \sum\limits_{ l\in I_4} 2 k \left ( \sum\limits_{l=1}^{n} \mu_l -\epsilon-(n-d)\mu_l \right ) q_{l} + \sum\limits_{ l\in I_5} 2 k \left ( \sum\limits_{l=1}^{n} \mu_l -\epsilon \right ) q_{l} \notag \\
    & \quad + k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\mu_{\max}}^2 \notag \\
    & \quad + (d-1) \left [ k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\mu_{\max}}^2 \right ] \notag \\
    & \quad + (n-d) \left [ k^2\left ( \sum\limits_{l=1}^{n} \mu_l - \epsilon + (n-d)\mu_{\max} \right )^2 + kn \sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_{\max}}^2 \right ] \notag \\
    & \quad + (n-d) \left [ k^2 \left ( \sum\limits_{l=1}^{n} \mu_l-\epsilon \right )^2 + kn \sigma_{\lambda}^2 \right ] \notag \\
    & \leq - \frac{ 2\epsilon k(n-d)}{\sqrt{n}} \| \mathbf{q}_{\parallel} \|_2 - \frac{2k(n-d) \left ( \min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right) - \mu_{\max} \right \} - \epsilon \right )}{\sqrt{n}} \| \mathbf{q}_{\perp} \|_2 + C_1^{\prime}, \label{eq:ssc_driftofssc} 
\end{align}
where
\begin{align}
    & C_1^{\prime} = 2k^2(n-1)(n-d)^2\mu_{\max} S_{\max} + k^2(n-d)^2\mu_{\max}^2+k(n-d)\sigma_{\mu_{\max}}^2 \notag \\
    & \qquad+ (d-1) \left [ k^2(n-d)^2\mu_{\max}^2 + k(n-d)\sigma_{\mu_{\max}}^2 \right ] \notag \\
    & \qquad + (n-d) \left [ k^2\left ( \sum\limits_{l=1}^{n} \mu_l - \epsilon + (n-d)\mu_{\max} \right )^2 + kn \sigma_{\lambda}^2 +k(n-d)\sigma_{\mu_{\max}}^2 \right ] + (n-d) \left [ k^2 \left ( \sum\limits_{l=1}^{n} \mu_l-\epsilon \right )^2 + kn \sigma_{\lambda}^2 \right ]. \notag 
\end{align}


We now lower bound $ E[\Delta W_{\parallel}(\tilde{\mathbf{Q}}(t'))\ | \  \tilde{\mathbf{Q}}(t')=\mathbf{q}] $ as follows:
\begin{align}
    & E[\Delta W_{\parallel}(\tilde{\mathbf{Q}}(t'))\ | \ \tilde{\mathbf{Q}}(t') = \mathbf{q}] = E[\| \tilde{\mathbf{Q}}_{\parallel}(t'+1) \|_2^2 - \| \tilde{\mathbf{Q}}_{\parallel}(t') \|_2^2 \  | \  \tilde{\mathbf{Q}}(t')=\mathbf{q} ] \notag \\
    & = E[\| \mathbf{Q}_{\parallel}(t+k(n-d)) \|_2^2 - \| \mathbf{Q}_{\parallel}(t) \|_2^2 \  | \  \mathbf{Q}(t)=\mathbf{q} ] \notag \\
    & = E \left [ \sum\limits_{l=1}^{n} \left ( \frac{Q_{\Sigma}(t+k(n-d))}{n} \right )^2 - \sum\limits_{l=1}^{n} \left ( \frac{Q_{\Sigma}(t)}{n} \right )^2 \ \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\ 
    & = E \left [ \frac{1}{n}(Q_{\Sigma}(t+k(n-d))^2 - Q_{\Sigma}(t)^2) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & = \frac{1}{n} E \left [ \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right )^2 - Q_{\Sigma}(t)^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & = \frac{1}{n} \left \{ E \left [ \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{n-d-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )^2 - Q_{\Sigma}(t)^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \right. \notag \\
    & \quad + E \left [ 2\left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad \left. + E \left [ \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right)^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \right \} \notag \\
    & = \frac{1}{n} \left \{ E \left [ 2 Q_{\Sigma}(t) \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \right. \notag \\
    & \quad + E \left [ \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) ^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad + E \left [ 2 \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad - E \left [ 2\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right) \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \notag \\
    & \quad \left. + E \left [ + \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right)^2 \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \right \} \notag \\
    & \overset{(a)}{\geq} \frac{1}{n} \left \{ E \left[ 2 Q_{\Sigma}(t) \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \right. \notag \\
    & \quad \left. - E \left [ 2\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right) \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \  \middle | \  \mathbf{Q}(t)=\mathbf{q} \right ] \right \} \notag \\
    & \overset{(b)}{\geq} 2\frac{1}{n} \left ( k(n-d)\left (\sum\limits_{l=1}^{n}\mu_l-\epsilon \right )-k(n-d)\sum\limits_{l=1}^{n}\mu_l \right )q_{\Sigma}(t) - 2\frac{1}{n}k(n-d)nS_{\max}k(n-d)nS_{\max} \notag \\
    & = - \frac{2 \epsilon k(n-d)}{n}\|\mathbf{q} \|_1 - 2 k^2 (n-d)^2 n S_{\max}^2 \notag \\
    & = - \frac{2 \epsilon k(n-d)}{\sqrt{n}}\| \mathbf{q}_{\parallel} \|_2 - C_2, \label{eq:ssc_dirftofparallel}
\end{align}
with $C_2 = 2k^2(n-d)^2 n S_{\max}^2$, where (a) follows from removing the positive term, and (b) follows from using that $ U_l(t+j) \leq S_{\max}$ for all $l \in [n]$ and $j\geq 0$. \\

Finally, combining equations \eqref{eq:difference_drifts}, \eqref{eq:ssc_driftofssc}, and \eqref{eq:ssc_dirftofparallel}, we get
\begin{align}
         & E[ \Delta V_{\perp}(\tilde{\mathbf{Q}}(t'))\  |\ \tilde{\mathbf{Q}}(t')=\mathbf{q} ] \notag \\ 
         & \leq \frac{1}{2 \| \mathbf{q}_{\perp} \|_2 } E \left [\Delta W(\tilde{\mathbf{Q}}(t')) - \Delta W_{\parallel}(\tilde{\mathbf{Q}}(t')) \ \middle |\ \tilde{\mathbf{Q}}(t')= \mathbf{q} \right ] \notag \\ 
         & = \frac{1}{2 \| \mathbf{q}_{\perp} \|_2 } \Bigg [ -2\epsilon k \frac{n-d}{\sqrt{n}}\| \mathbf{q}_{\parallel} \|_2 - \frac{2k(n-d) \left ( \min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \} - \epsilon \right )}{\sqrt{n}} \left \| \mathbf{q}_{\perp} \right \|_2 + C_1^{\prime} \notag \\
         & \quad + 2\epsilon k \frac{n-d}{\sqrt{n}}\| \mathbf{q}_{\parallel} \|_2 + C_2 \Bigg ]  \notag \\
         & = - \frac{ k(n-d) \left ( \min \left \{ \mu_{\min}, \left (\frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \} - \epsilon \right )}{\sqrt{n}} + \frac{C}{2 \| \mathbf{q}_{\perp} \|_2 }. \notag 
\end{align}
In particular, for
\[ \epsilon \leq \frac{1}{2}\min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \}, \]
this implies that 
\begin{align}
    E \left [ \Delta V_{\perp}(\tilde{\mathbf{Q}}_{\perp}) + \epsilon_0 \  \middle | \  \| \tilde{\mathbf{Q}}_{\perp} \|_2 > a \right ] < 0, \notag
\end{align}
for
\begin{align*}
     a &= \frac{C \sqrt{n} }{k (n-d) \Delta } \qquad \text{and} \qquad \epsilon_0 = \frac{k (n-d) \Delta}{2 \sqrt{n} },
\end{align*}
where
\[ \Delta = \frac{\min \left \{ \mu_{\min}, \left ( \frac{1}{n-d} \sum\limits_{i=1}^n \mu_i \right ) - \mu_{\max} \right \}}{2}. \]
Then, Theorem 2.3 in \cite{hajek1982hitting-lyapunovupperbound} implies that
\begin{align}
    & E \left [ e^{\eta\| \tilde{\mathbf{Q}}_{\perp}\|_2} \right ] \leq \frac{1}{1-\rho}e^{\eta a + 1}, \label{eq:exp_bound}
\end{align}
where
\begin{align}
    & \eta = \min\left\{ \frac{1}{Z}, \frac{k (n-d) \Delta}{4 \sqrt{n} Z^2(e-2)}, \frac{k (n-d) \Delta}{C \sqrt{n}} \right\} \notag \\
    & \rho = 1 - \epsilon_0\eta + Z^2(e-2)\eta^2, \notag
\end{align}
with
\[ Z = 2k(n-d)n(A_{\max}+S_{\max}). \]
Taking the Taylor expansion for the left-hand side in Equation \eqref{eq:exp_bound} yields
\[ E \left [ 1 + \eta \| \tilde{\mathbf{Q}}_{\perp} \|_2 + \frac{\eta^2}{2!}\| \tilde{\mathbf{Q}}_{\perp} \|_2^2 + \sum\limits_{k=3}^{\infty}\frac{\eta^k}{k!} \| \tilde{\mathbf{Q}}_{\perp} \|_2^k \right ] \leq \frac{1}{1-\rho}e^{\eta a + 1}, \]
and thus
\begin{align}
    E \left [ \| \tilde{\mathbf{Q}}_{\perp} \|_2^2 \right ] &\leq \frac{2}{\eta^2}\frac{1}{1-\rho}e^{\eta a+1} \notag \\
    & = \frac{4 \sqrt{n} e^{\eta C \sqrt{n} /(k (n-d) \Delta)+1}}{k (n-d) \Delta \eta^3 - 2 \sqrt{n} Z^2 (e-2)\eta^4} \notag \\
    &= \frac{4 \sqrt{n} e^2}{k (n-d) \Delta \eta^3 - 2 \sqrt{n} Z^2(e-2)\eta^4} \notag \\ 
    & =: N_2(n,k,d). \notag 
\end{align}


Finally, even though the State Space Collapse result is only for the sampled queue length vector $\tilde{\mathbf{Q}}$, in between those sampling points the queues can only increase or decrease by at most $k(nA_{\max}+(n-d)S_{\max})$. Therefore, $\|\tilde{\mathbf{Q}}_{\perp}\|_2^2$ can only increase by at most $k^2(nA_{\max}+(n-d)S_{\max})^2n$, which is constant in $\epsilon$ and of order $\Theta(k^2n^3)$, which is smaller than or equal to $N_2$. It follows that we have the same State Space Collapse result for $\mathbf{Q}$.


