\section{Proof of Theorem \ref{thm_our:SSCUpper}} \label{prf:thm_upperbound}
Suppose that $\tilde{\mathbf{Q}}(t')=\mathbf{Q}(t)$ is in steady-state. Then, we have
\begin{align}
    & E \left [ \Delta W_{\parallel} ( \tilde{\mathbf{Q}}(t') ) \right ] = E \left [ \| \tilde{\mathbf{Q}}_{\parallel}(t'+1) \|^2 - \| \tilde{\mathbf{Q}}_{\parallel}(t') \|^2 \right ] \notag \\
    & = E\left [ \| \mathbf{Q}_{\parallel}(t+k(n-d)) \|^2 - \| \mathbf{Q}_{\parallel}(t) \|^2 \right ] \notag \\
    & = E \left [ \sum\limits_{l=1}^{n} \left ( \frac{Q_{\Sigma}(t+k(n-d))}{n} \right )^2 - \sum\limits_{l=1}^{n} \left ( \frac{Q_{\Sigma}(t)}{n} \right )^2 \right ] \notag \\ 
    & = E \left [ \frac{1}{n}(Q_{\Sigma}(t+k(n-d))^2 - Q_{\Sigma}(t)^2) \right ] \notag \\
    & = \frac{1}{n} E \left [ \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right )^2 - Q_{\Sigma}(t)^2 \right ] \notag \\
    & = \frac{1}{n} \left \{ E \left [ \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )^2 - Q_{\Sigma}(t)^2 \right ] \right. \notag \\
    & \quad + E \left [ 2\left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \right ]  \notag \\
    & \quad \left. + E \left [ \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right)^2 \right ] \right \} \notag \\
    & = \frac{1}{n} \left \{ E \left [ 2 Q_{\Sigma}(t) \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) \right ] \right. \notag \\
    & \quad + E \left [ \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) ^2 \right ] \notag \\
    & \quad + E \left [ 2\left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \right ]  \notag \\
    & \quad \left. + E \left [ \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right)^2 \right ] \right \} \notag
\end{align}
Since in steady-state we have $ E[\Delta W_{\parallel}(\tilde{\mathbf{Q}}(t')) ] = 0 $, then
\begin{align}
    & \frac{1}{n} E \left[
        Q_{\Sigma}(t) \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) \right ) \right ] \notag \\
    & = \frac{1}{2n} \left \{ E \left [ \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) ^2 \right ] \right. \notag \\
    & \quad + 2 E \left [ \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \right ]  \notag \\
