\end{align}
For the first term in Equation \eqref{eq:upb_qu}, we bound
\[ Q_l(t+k(n-d)) \left( \sum_{j=0}^{k(n-d)-1} U_l(t+j) \right ) \]
for each server $l$. For each $ l $, we have
\[ Q_l(t+j+1)U_l(t+j) = 0 \]
and
\[ Q_l(t+j+1) = Q_l(t+j) + A_l(t+j) - S_l(t+j) + U_l(t+j), \]
for all $j \in \{0,1,...,k(n-d)-1\}$. It follows that
\begin{align}
    & Q_l(t+k(n-d)) \left( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right ) \notag \\
    & =  Q_l(t+k(n-d)) \left( \sum\limits_{j=0}^{k(n-d)-2} U_l(t+j) \right ) + Q_l(t+k(n-d)) U_l(t+k(n-d)-1) \notag \\
    & = Q_l(t+k(n-d)-1) \left( \sum\limits_{j=0}^{k(n-d)-2} U_l(t+j) \right ) \notag \\
    & \quad + \Big[A_l(t+k(n-d)-1) - S_l(t+k(n-d)-1)+U_l(t+k(n-d)-1) \Big] \left( \sum\limits_{j=0}^{k(n-d)-2} U_l(t+j) \right ) \notag \\
    & = Q_l(t+1) U_l(t) + \sum\limits_{i=1}^{k(n-d)-1}\left [ (A_l(t+i) -S_l(t+i)+U_l(t+i)) \left( \sum\limits_{j=0}^{i-1} U_l(t+j) \right ) \right ] \notag \\
    & = \sum\limits_{i=1}^{k(n-d)-1}\left [ (A_l(t+i) -S_l(t+i) + U_l(t+i)) \left( \sum\limits_{j=0}^{i-1} U_l(t+j) \right ) \right ] \notag \\
    & \overset{(a)}{\leq} \sum\limits_{i=1}^{k(n-d)-1}\left [ A_l(t+i) \left( \sum\limits_{j=0}^{i-1} U_l(t+j) \right ) \right ] \notag \\
    & \leq \sum\limits_{i=1}^{k(n-d)-1}\left [ A_l(t+i) \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ] \notag \\
    & = \left [ \begin{array}{ll}
        \sum\limits_{i^{\prime}} A_l(t+i^{\prime}) \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) & \forall \ l: l \in I \setminus I_d(t) \\
        0 & \forall \ l: l \in I_d(t)
    \end{array} \right ., \label{eq:upb_alul}
\end{align}
where $i^{\prime}$ are the time slots in which the $l$-th queue receives exogenous arrivals, and where (a) follows from the fact that $S_l(t+j) \geq U_l(t+j)$ for all $\l\in [n]$ and $j\geq 1$. For all $n$ servers, we have
\begin{align}
    \sum\limits_{l=1}^{n}\left [ \left ( Q_l(t+k(n-d)) \right) \left( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right ) \right ] & \leq \sum\limits_{l\in I \setminus I_d }^{n} \left [ \sum\limits_{i^{\prime}} \left( A_l[t+i^{\prime}] \right) \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ] \notag \\
    & \overset{(a)}{\leq} \sum\limits_{l\in I \setminus I_d }^{n} \left [ kn A_{\max} \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ] \notag \\
    & = (n-d) k n A_{\max} \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ), \notag
\end{align}
Where (a) follows from the fact that the number of arrivals is bounded by $ n A_{\max} $. Combining this with equations \eqref{eq:upb_qu_org} and \eqref{eq:upb_qu} we get
\begin{align}
    & \frac{1}{n} E \left[
        \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \right ] \notag \\
    & \leq E \left[ \sum\limits_{l=1}^{n} \left [ \left ( Q_l(t+k(n-d)) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right ) \right ] \right ] \notag \\
    & \quad + E \left[ \sum\limits_{l=1}^{n} \left [ \left ( \frac{Q_{\Sigma}(t+k(n-d))}{n} - Q_l(t+k(n-d)) \right ) \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right ) \right ] \right ] \notag \\ 
    & \leq k(n-d)n A_{\max} E \left[ \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ] \notag \\
    & \quad + E \left[ \sum\limits_{l=1}^{n} \left [ \left ( \frac{Q_{\Sigma}(t+k(n-d))}{n} - Q_l(t+k(n-d)) \right ) \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right ) \right ] \right ] \notag \\
    & \overset{(a)}{\leq} k(n-d)n A_{\max} E \left[ \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ]  \notag \\
    & \quad + \sqrt{E \left[ \sum\limits_{l=1}^{n} \left ( \frac{Q_{\Sigma}(t+k(n-d))}{n} - Q_l(t+k(n-d)) \right)^2 \right ] E \left[ \sum\limits_{l=1}^{n} \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right )^2 \right ] }  \notag \\
    & \overset{(b)}{=} k(n-d)n A_{\max} 
        E \left[ \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ] 
        + \sqrt{E \left[ \sum\limits_{l=1}^{n} \left ( \frac{Q_{\Sigma}(t)}{n} - Q_l(t) \right)^2 \right ]
        E \left[ \sum\limits_{l=1}^{n} \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right )
        ^2 \right ]
        }  \notag \\ 
    & = k(n-d)n A_{\max} 
        E \left[ \left( \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ) \right ] 
        + \sqrt{E \left[ \| Q_{\perp} \|_2^2 \right ]
        E \left[ \sum\limits_{l=1}^{n} \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right )
        ^2 \right ] },  \label{eq:upb_Eofqu}
\end{align}
where (a) follows from the Cauchy-Schwartz inequality, and (b) follows from the fact that $\tilde{\mathbf{Q}}(t'+1) \overset{d}{=} \tilde{\mathbf{Q}}(t') $ because they are in steady-state. To bound the first term in Equation \eqref{eq:upb_Eofqu}, we use that
\begin{align}
    0&= E \left [ \frac{\tilde Q_{\Sigma}(t'+1)}{\sqrt{n}} - \frac{\tilde Q_{\Sigma}(t')}{\sqrt{n}} \right ] \notag \\ 
    & = E \left [ \frac{Q_{\Sigma}(t+k(n-d))}{\sqrt{n}} - \frac{Q_{\Sigma}(t)}{\sqrt{n}} \right ]  \notag \\ 
    & = E \left [ \frac{ Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) }{\sqrt{n}} - \frac{Q_{\Sigma}(t)}{\sqrt{n}} \right ], \notag
\end{align}
and thus
\begin{align}
    E \left [ \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right ] &= E \left [ \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) \right ] \notag \\
    & = k(n-d)\epsilon. \label{eq:upb_Eofu}
\end{align}
To bound the second term in Equation \eqref{eq:upb_Eofqu}, we use that
\begin{align}
    E \left[ \sum\limits_{l=1}^{n} \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right )
        ^2 \right ] & \leq E \left[ \sum\limits_{l=1}^{n} \left [ \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right )
        k(n-d)S_{\max} \right ] \right ] \notag \\
    & = k(n-d)S_{\max} E \left [ \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right ]  \notag \\
    & = k^2(n-d)^2 S_{\max}\epsilon \label{eq:upb_Eofu2}
\end{align}

Using the bounds in equations \eqref{eq:upb_Eofqu}, \eqref{eq:upb_Eofu}, and \eqref{eq:upb_Eofu2}, we bound each term in Equation \eqref{eq:upb_equation} by
\begin{align}
    E \left[
        \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right ) ^2 \right ] 
    \leq k^2(n-d)^2 \epsilon ^2 + k(n-d)n \sigma_{\lambda}^2 + k(n-d) \left ( \sum\limits_{l=1}^{n}\sigma_{\mu_l}^2 \right ) \notag
\end{align}
\begin{align}
    E \left[ \left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right)^2 \right ] & \leq k^2(n-d)^2nS_{max}\epsilon \notag 
\end{align}
\begin{align}
    & \frac{1}{n} E \left[
        \left ( Q_{\Sigma}(t) + \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) \right )\left ( \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n U_l(t+j) \right) \right ] \notag \\
    & \leq k(n-d) n A_{\max} 
        E \left[ \sum\limits_{j=0}^{k(n-d)-1}\sum\limits_{k=1}^{n} U_k(t+j) \right ] 
        + \sqrt{E \left[ \| Q_{\perp} \|_2^2  \right ]
        E \left[ \sum\limits_{l=1}^{n} \left ( \sum\limits_{j=0}^{k(n-d)-1} U_l(t+j) \right )
        ^2 \right ]
        }  \notag \\
    & \overset{(a)}{=} k(n-d) n A_{\max}k(n-d)\epsilon + \sqrt{N_2(n,k,d) k^2(n-d)^2nS_{\max}\epsilon} \notag \\
    & = k^2(n-d)^2n A_{\max}\epsilon + k(n-d)\sqrt{N_2(n,k,d) n S_{\max}\epsilon} \notag
\end{align}
where (a) follows from Theorem \ref{thm_our:SSC}. Finally, substituting the three inequalities above into the equation \eqref{eq:upb_equation}, and using that
\begin{align}
    E \left[ Q_{\Sigma}(t) \left (\sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n S_l(t+j) - \sum\limits_{j=0}^{k(n-d)-1} \sum\limits_{l=1}^n A_l(t+j) \right ) \right ] 
    = k(n-d)\epsilon E \left[ Q_{\Sigma}(t) \right ], \notag 
\end{align}
we get
\begin{align}
    \frac{k(n-d)\epsilon E \left[ Q_{\Sigma}(t) \right ]}{n}  & \leq \frac{k^2(n-d)^2\epsilon^2 + k(n-d)n \sigma_{\lambda}^2 + k(n-d)\left ( \sum\limits_{l=1}^{n}\sigma_{\mu_l}^2 \right )}{2n} \notag \\
    & \quad + k^2(n-d)^2n A_{\max}\epsilon + k(n-d)\sqrt{N_2(n,k,d) n S_{\max}\epsilon} \notag \\
    & \quad + \frac{k^2(n-d)^2 n S_{max}\epsilon}{2n}, \notag
\end{align}
and thus
\begin{align}
    \epsilon E \left[ Q_{\Sigma}(t) \right ] \notag \leq
    \frac{n \sigma_{\lambda}^2 + \sum\limits_{l=1}^{n}\sigma_{\mu_l}^2 }{2} + \epsilon^2 \frac{k(n-d)}{2} + \epsilon k(n-d)n \frac{2n A_{\max}+S_{\max}}{2} + \sqrt{\epsilon} n\sqrt{N_2(n,k,d) n S_{\max}}. \notag 
\end{align}


